with source_notes as (
  select *
  from jsonb_to_recordset($field_desk$[{"id":"Terms and Concepts/Cyber Attacks","title":"Cyber Attacks","section":"Terms and Concepts","domain":"Networking","description":"Malicious attempts by threat actors to damage, disrupt, or gain unauthorized access to computer systems, networks, or data.","tags":["IT","IT/Security","Level/Foundational"],"content":"# Cyber Attacks\n\n> Malicious attempts by threat actors to damage, disrupt, or gain unauthorized access to computer systems, networks, or data.\n\n## Overview\nCyber attacks encompass a wide range of malicious activities targeting digital systems — from individual users to enterprise networks to national infrastructure. Attackers may be motivated by financial gain, espionage, disruption, activism, or personal grievance. Understanding the major categories of attacks is foundational to building effective defenses.\n\nThe threat landscape is constantly evolving. Attackers combine techniques (phishing to deliver malware, malware to enable ransomware, social engineering to bypass technical controls), making it important to understand not just individual attack types but how they chain together.\n\n## Key Concepts\n\n- **[[Phising|Phishing]]:** Deceptive emails or messages impersonating legitimate sources to trick users into revealing credentials or clicking malicious links. The most common initial access vector.\n- **[[Malware]]:** Malicious software designed to damage, disrupt, or gain unauthorized access. Includes viruses, worms, Trojans, ransomware, and spyware.\n- **[[Ransomware]]:** A type of malware that encrypts victim data and demands payment for the decryption key. Has caused billions in damages to organizations worldwide.\n- **[[DDoS]] (Distributed Denial of Service):** Flooding a target with traffic from many sources simultaneously, making it unreachable to legitimate users.\n- **Man-in-the-Middle (MITM):** Intercepting communications between two parties — often to steal credentials or inject malicious content.\n- **[[SQL]] Injection:** Inserting malicious SQL code into an application's input fields to manipulate the database — potentially exposing or destroying data.\n- **Cross-Site Scripting (XSS):** Injecting malicious scripts into web pages viewed by other users, enabling session hijacking or data theft.\n- **[[Zero Day]]:** Exploiting a vulnerability that the software vendor is unaware of and for which no patch exists.\n- **[[Social Engineering]]:** Manipulating people (rather than systems) into divulging sensitive information or taking harmful actions.\n- **Insider Threat:** Attacks by employees, contractors, or partners — either maliciously or through negligence.\n- **Advanced Persistent Threat (APT):** Sophisticated, long-term attacks — often state-sponsored — aimed at maintaining persistent access to a target network for espionage or sabotage.\n\n## Why It Matters\nEvery IT professional must understand the cyber attack landscape. Knowing how attackers operate informs every security decision — from what patches to prioritize to how to configure firewalls to why user training matters. Security certifications (Security+, CEH, CISSP) are built around this knowledge. Real-world IT support and security roles require the ability to recognize attack patterns and respond appropriately.\n\n## Related Topics\n- [[Malware]]\n- [[Phising]]\n- [[Ransomware]]\n- [[DDoS]]\n- [[Social Engineering]]\n- [[Zero Day]]\n- [[CyberOps]]"},{"id":"Terms and Concepts/CyberOps","title":"CyberOps","section":"Terms and Concepts","domain":"Networking","description":"The ongoing practices, processes, and technologies used by security teams to monitor, detect, analyze, and respond to threats targeting an organization's systems and networks.","tags":["IT","IT/Security","Level/Advanced"],"content":"# CyberOps (Cybersecurity Operations)\n\n> The ongoing practices, processes, and technologies used by security teams to monitor, detect, analyze, and respond to threats targeting an organization's systems and networks.\n\n## Overview\nCyberOps refers to the operational side of cybersecurity — the day-to-day work of defending an organization from cyber threats in real time. While security engineering builds and configures defenses, CyberOps teams operate them: watching for signs of attack, investigating alerts, containing incidents, and hunting for threats that may have bypassed automated controls.\n\nThe heart of CyberOps is typically the Security Operations Center (SOC) — a team of analysts who monitor systems around the clock using SIEM tools, endpoint detection platforms, intrusion detection systems, and threat intelligence feeds. SOC analysts triage alerts, distinguish false positives from real threats, and escalate significant incidents for incident response.\n\nCisco's CyberOps Associate certification is a well-known credential specifically targeting this domain.\n\n## Key Concepts\n\n- **SOC (Security Operations Center):** A centralized team responsible for continuous monitoring and defense. SOC analysts work in tiers — Tier 1 triages alerts, Tier 2 investigates confirmed incidents, Tier 3 handles complex threats and threat hunting.\n- **SIEM (Security Information and Event Management):** Platform that collects, aggregates, and correlates log data from across the environment to detect threats. Examples: Splunk, Microsoft Sentinel, IBM QRadar.\n- **[[IDS]]/[[IPS]]:** Intrusion Detection/Prevention Systems that monitor traffic for malicious patterns. IDS alerts; IPS can block automatically.\n- **Incident Response:** The structured process for identifying, containing, eradicating, and recovering from a security incident. Follows defined playbooks.\n- **Threat Hunting:** Proactive searching through logs and network traffic to find threats that automated tools have not detected. Requires deep expertise.\n- **Vulnerability Management:** Regular scanning and prioritization of known vulnerabilities across the organization's systems, ensuring timely patching.\n- **Threat Intelligence:** Information about current threats, attacker tactics, and [[IoC]] (Indicators of Compromise) used to improve detection and response.\n- **EDR (Endpoint Detection and Response):** Security software on endpoints that records activity and alerts on suspicious behavior. Provides visibility beyond traditional antivirus.\n\n## Why It Matters\nCyberOps is the frontline of organizational defense against cyber threats. Every organization with significant digital assets needs some form of security operations capability — whether an in-house SOC, a managed security service provider (MSSP), or at minimum automated monitoring tools. IT professionals entering security roles will likely encounter CyberOps functions, and understanding SIEM, incident response, and threat detection is fundamental to career growth in cybersecurity.\n\n## Related Topics\n- [[IDS]]\n- [[IPS]]\n- [[Logging]]\n- [[Cyber Attacks]]\n- [[Security Assessments]]\n- [[NIST Cybersecurity Framework]]\n- [[Digital Forensics]]"},{"id":"Terms and Concepts/DaaS","title":"DaaS","section":"Terms and Concepts","domain":"Cloud","description":"A cloud computing model that delivers virtual desktop environments to end users over the internet, hosted and managed by a cloud provider.","tags":["IT","IT/Cloud","Level/Intermediate"],"content":"# DaaS (Desktop as a Service)\n\n> A cloud computing model that delivers virtual desktop environments to end users over the internet, hosted and managed by a cloud provider.\n\n## Overview\nDesktop as a Service (DaaS) is a form of Virtual Desktop Infrastructure (VDI) delivered from the cloud. Instead of running applications and a desktop OS on a local machine, users access a virtual desktop hosted on remote servers via the internet. The desktop environment (OS, applications, files) lives in the cloud; the user's device simply becomes a display and input mechanism.\n\nDaaS is distinct from traditional VDI, where the organization builds and manages its own virtual desktop infrastructure on-premises. With DaaS, the cloud provider handles the infrastructure, scaling, maintenance, and patching — the organization just manages user accounts and applications.\n\nPopular DaaS platforms include Amazon WorkSpaces, Azure Virtual Desktop (AVD), and Citrix DaaS.\n\n## Key Concepts\n\n- **Virtual Desktop Infrastructure (VDI):** The underlying technology — virtualized desktop instances running on centralized servers. DaaS is cloud-hosted VDI.\n- **Thin Client:** A low-spec device designed specifically for accessing virtual desktops. No local processing; all computation happens in the cloud.\n- **Device Independence:** Users access their desktop from any device — laptop, tablet, thin client, phone — without needing powerful local hardware.\n- **Persistent vs. Non-Persistent Desktops:** Persistent desktops retain user customizations and files between sessions. Non-persistent desktops reset to a clean state after logout (better for security and cost in call center/shared environments).\n- **Centralized Management:** IT manages a fleet of virtual desktops centrally — deploying apps, applying patches, and enforcing policies across all instances from one place.\n- **[[BYOD]] Enablement:** DaaS allows organizations to securely support BYOD — employees use personal devices to access a corporate virtual desktop, keeping company data off the personal device.\n- **Bandwidth Dependency:** DaaS requires a reliable, low-latency internet connection. A poor connection results in a degraded user experience.\n\n## Why It Matters\nDaaS represents a growing approach to endpoint management — especially for remote workforces, seasonal workers, or organizations that want to reduce dependency on physical endpoint hardware. IT professionals need to understand DaaS as an alternative to traditional desktop deployment, and how it integrates with identity management, [[Active Directory]], and [[Cloud Computing]] platforms. It also raises security considerations around data residency and access control.\n\n## Related Topics\n- [[Cloud Computing]]\n- [[Virtualization]]\n- [[Virtual Machines]]\n- [[BYOD]]\n- [[IaaS]]\n- [[Desktop]]\n- [[Remote Desktop]]"},{"id":"Terms and Concepts/DAS","title":"DAS","section":"Terms and Concepts","domain":"Networking","description":"A storage architecture where storage devices are physically connected directly to a single server or computer, without going through a network.","tags":["IT","IT/Hardware","Level/Intermediate"],"content":"# DAS (Direct-Attached Storage)\n\n> A storage architecture where storage devices are physically connected directly to a single server or computer, without going through a network.\n\n## Overview\nDirect-Attached Storage (DAS) is the simplest storage model — storage devices (HDDs, SSDs, tape drives) are connected directly to a single computer or server through interfaces like SATA, SAS, NVMe, or USB. No network is involved, and the storage is not shared with other systems unless special software or protocols are added.\n\nThis is how most personal computers and many servers work by default — an internal hard drive or SSD connected to the motherboard via SATA or NVMe. External USB drives are also a form of DAS.\n\nDAS contrasts with [[NAS]] (Network-Attached Storage), where storage is connected to the network and shared with multiple devices, and SAN (Storage Area Network), which provides block-level storage over a dedicated high-speed network.\n\n## Key Concepts\n\n- **Interfaces:** DAS uses direct connections: SATA (common for desktop drives), NVMe (high-speed SSDs via PCIe), SAS (enterprise servers), USB (external drives).\n- **Single-Host Access:** Data on DAS is accessible only to the connected server/computer. Sharing requires additional software (e.g., a file server application or network share).\n- **Low Latency:** Because there's no network hop, DAS provides extremely low latency — ideal for performance-intensive workloads like databases.\n- **No Network Dependency:** DAS is not affected by network congestion, switches, or cabling issues — storage performance is determined entirely by the local connection.\n- **[[RAID]]:** Multiple DAS drives are often configured in RAID for redundancy and/or performance. RAID can protect against single-drive failure.\n- **[[NAS]] vs. DAS:** NAS shares storage over a network to multiple clients. DAS serves one host only. NAS requires more infrastructure but enables collaboration.\n- **Scalability Limits:** Adding more storage to DAS requires physically adding more drives, limited by available ports and bays on the server.\n\n## Why It Matters\nUnderstanding DAS, NAS, and SAN are fundamental storage concepts that appear on CompTIA A+, Network+, and other certifications. IT professionals need to select the right storage architecture based on workload requirements — DAS for single-server performance needs, NAS for shared file access, SAN for high-performance shared block storage. Knowing the trade-offs guides hardware purchasing and infrastructure design decisions.\n\n## Related Topics\n- [[NAS]]\n- [[Storage]]\n- [[RAID]]\n- [[SSD]]\n- [[HHD]]\n- [[Server]]"},{"id":"Terms and Concepts/Data Breach","title":"Data Breach","section":"Terms and Concepts","domain":"Security","description":"A security incident where unauthorized individuals access, expose, or steal sensitive, confidential, or protected information.","tags":["IT","IT/Security","Level/Foundational"],"content":"# Data Breach\n\n> A security incident where unauthorized individuals access, expose, or steal sensitive, confidential, or protected information.\n\n## Overview\nA data breach occurs when protected information is accessed or disclosed without authorization. This includes personally identifiable information ([[PII]]), financial records, health data, login credentials, trade secrets, or any other data the organization is obligated to protect.\n\nBreaches can result from external attacks (hackers exploiting vulnerabilities, phishing campaigns), insider threats (malicious or negligent employees), physical theft (stolen laptops, USB drives), or misconfigurations (a cloud storage bucket left publicly accessible). The consequences range from regulatory fines and legal liability to reputational damage and direct harm to affected individuals.\n\nHigh-profile breaches — Equifax (2017, 147 million records), Yahoo (2016, 3 billion accounts), Colonial Pipeline (2021, operational shutdown) — illustrate the scale and variety of potential impact.\n\n## Key Concepts\n\n- **Breach Notification Laws:** Most jurisdictions require organizations to notify affected individuals and regulators when a breach occurs. Notification timelines vary — [[GDPR]] requires notice within 72 hours; US state laws vary by state.\n- **Indicators of Compromise (IoC):** Evidence that a breach has occurred or is in progress — unusual login activity, unexpected data transfers, unfamiliar processes.\n- **Attack Vectors:** Common methods include [[Phising|phishing]], [[Malware]], [[Brute Force]] attacks, [[SQL]] injection, credential stuffing, and insider misuse.\n- **Data Classification:** Not all data is equally sensitive. Classifying data by sensitivity helps prioritize protection efforts and understand the impact of a breach.\n- **[[PII]]:** Personally Identifiable Information — the most common target. Names, SSNs, email addresses, payment cards, health records.\n- **Breach Response:** Follows a structured incident response process — Identify → Contain → Eradicate → Recover → Notify → Review.\n- **Regulatory Penalties:** [[GDPR]] fines can reach 4% of global annual revenue. [[HIPAA]] penalties reach $1.9M per violation category per year. [[PCI DSS]] can result in loss of card processing rights.\n\n## Why It Matters\nData breaches are one of the most significant risks organizations face. IT professionals at every level bear some responsibility for preventing them — through proper configuration, patching, access controls, and security monitoring. Understanding how breaches happen, their consequences, and the required response is essential for IT support, sysadmin, and security roles. This knowledge is also tested across virtually all security certifications.\n\n## Related Topics\n- [[PII]]\n- [[Cyber Attacks]]\n- [[Phising]]\n- [[Malware]]\n- [[GDPR]]\n- [[HIPAA]]\n- [[Confidentiality]]"},{"id":"Terms and Concepts/Data Deduplication","title":"Data Deduplication","section":"Terms and Concepts","domain":"Cloud","description":"A storage optimization technique that identifies and removes redundant data copies, storing only unique instances and referencing them instead of keeping duplicates.","tags":["IT","IT/Cloud","IT/Hardware","Level/Advanced"],"content":"# Data Deduplication\n\n> A storage optimization technique that identifies and removes redundant data copies, storing only unique instances and referencing them instead of keeping duplicates.\n\n## Overview\nData deduplication (often shortened to \"dedupe\") reduces storage consumption by ensuring that identical data is stored only once. Instead of keeping 50 copies of the same 10MB file (500MB total), deduplication stores it once and maintains 50 references to that single copy — dramatically reducing the storage footprint.\n\nThis is especially valuable in backup environments, where the same files are backed up repeatedly. A VM backup that runs daily will contain mostly the same data day-to-day — dedupe identifies the blocks that haven't changed and stores only the new ones, reducing backup storage needs by 10x or more in typical environments.\n\nDeduplication can occur inline (as data is written, before storage) or post-process (after data is stored, as a background task). Inline dedupe reduces storage more aggressively but requires more CPU resources; post-process dedupe has less impact on write performance.\n\n## Key Concepts\n\n- **Block-Level Deduplication:** Divides data into small fixed or variable chunks and compares each chunk's hash to previously stored chunks. The most granular and effective form.\n- **File-Level Deduplication:** Compares entire files for duplication. Less granular than block-level; simpler to implement.\n- **[[Hashing]]:** Deduplication uses hash functions (typically SHA-256 or similar) to create a fingerprint of each data chunk. Matching hashes indicate duplicate data.\n- **Deduplication Ratio:** A measure of space savings — a 10:1 ratio means 10TB of data is stored in 1TB of physical space.\n- **Inline vs. Post-Process:** Inline dedupe processes data during write (more resource intensive, immediate savings). Post-process dedupe runs after data is written (less write overhead, savings come later).\n- **Compression:** Often used alongside deduplication. Dedupe eliminates duplicate data; compression shrinks what remains.\n- **Windows Server Deduplication:** Windows Server includes a built-in data deduplication feature for NTFS volumes, particularly useful on file servers and VDI deployments.\n- **Impact on Restore:** Restoring deduplicated data requires reconstruction from references and the data store. Must be factored into recovery time objectives ([[RTO]]).\n\n## Why It Matters\nStorage is one of the most significant costs in IT infrastructure. Deduplication is a primary tool for reducing that cost — especially in backup, VDI, and file server environments. IT professionals working in storage administration, backup configuration, or capacity planning need to understand how deduplication works, when to apply it, and how it interacts with backup performance and restore times.\n\n## Related Topics\n- [[Storage]]\n- [[Backups]]\n- [[Cloud Storage]]\n- [[Hashing]]\n- [[Cold Storage]]\n- [[NAS]]"},{"id":"Terms and Concepts/Data Link Layer","title":"Data Link Layer","section":"Terms and Concepts","domain":"Networking","description":"Layer 2 of the OSI model, responsible for reliable data transfer between directly connected network devices using MAC addresses and frame-based communication.","tags":["IT","IT/Networking","Level/Intermediate"],"content":"# Data Link Layer\n\n> Layer 2 of the OSI model, responsible for reliable data transfer between directly connected network devices using MAC addresses and frame-based communication.\n\n## Overview\nThe Data Link Layer is the second layer of the [[OSI Model]], sitting directly above the Physical Layer (which handles actual signal transmission) and below the [[Network Layer]] (which handles IP routing). It is responsible for turning raw bits from the Physical Layer into organized frames, ensuring that data is delivered correctly between two nodes that are directly connected on the same network segment.\n\nThe Data Link Layer has two sublayers: the MAC (Media Access Control) sublayer, which controls how devices share the physical medium and uses MAC addresses for addressing; and the LLC (Logical Link Control) sublayer, which manages flow control and error checking.\n\n[[Ethernet]], Wi-Fi (802.11), and PPP all operate at Layer 2. Switches operate primarily at Layer 2, making forwarding decisions based on MAC addresses.\n\n## Key Concepts\n\n- **Frames:** The basic unit of Layer 2 communication. A frame wraps an IP packet from Layer 3 with a Layer 2 header (source and destination MAC addresses) and a trailer (error detection).\n- **[[MAC]] Address:** A unique hardware identifier assigned to a network interface card (NIC). Layer 2 uses MAC addresses to deliver frames within a local network.\n- **CSMA/CD (Carrier Sense Multiple Access with Collision Detection):** The access control method used by [[Ethernet]] — devices listen before transmitting and detect/handle collisions.\n- **Error Detection:** The Data Link Layer adds a CRC (Cyclic Redundancy Check) to frames. The receiver recalculates the CRC; if it doesn't match, the frame is discarded.\n- **Flow Control:** Mechanisms to prevent a fast sender from overwhelming a slow receiver.\n- **[[Switch]]:** A Layer 2 device that forwards frames based on MAC addresses, building a MAC address table to make intelligent forwarding decisions.\n- **[[ARP]]:** While technically spanning Layer 2 and Layer 3, ARP resolves IP addresses to MAC addresses — fundamental to Layer 2 communication.\n- **[[Ethernet]]:** The dominant Layer 2 protocol for wired LANs. Defines how frames are formatted and how access to the wire is managed.\n\n## Why It Matters\nLayer 2 is where switches operate, where [[Ethernet]] frames are formed, and where MAC addresses are used. Troubleshooting network issues often requires understanding Layer 2 behavior — why a switch isn't forwarding to a specific port, why [[ARP]] is failing, or why VLAN traffic isn't routing correctly. It is a core OSI model layer tested on CompTIA Network+ and covered in all networking fundamentals courses.\n\n## Related Topics\n- [[OSI Model]]\n- [[MAC]]\n- [[Ethernet]]\n- [[Switch]]\n- [[ARP]]\n- [[Physical Layer]]\n- [[Network Layer]]"},{"id":"Terms and Concepts/Data Privacy Laws","title":"Data Privacy Laws","section":"Terms and Concepts","domain":"Security","description":"Legal frameworks that govern how organizations collect, store, use, and share individuals' personal data, establishing rights for individuals and obligations for organizations.","tags":["IT","IT/Security","IT/Compliance","Level/Intermediate"],"content":"# Data Privacy Laws\n\n> Legal frameworks that govern how organizations collect, store, use, and share individuals' personal data, establishing rights for individuals and obligations for organizations.\n\n## Overview\nData privacy laws are regulations enacted by governments to protect individuals' personal information from misuse, unauthorized disclosure, and exploitation. As the digital economy has grown and data collection has become ubiquitous, governments worldwide have responded with increasingly comprehensive privacy legislation.\n\nThese laws create obligations for any organization that collects or processes personal data — from small websites to multinational corporations. They establish individual rights (to access, correct, or delete data), require security measures, mandate transparency about data use, and impose penalties for violations.\n\nFor IT professionals, privacy laws are not abstract legal concepts — they have direct technical implications for how systems are designed, how data is stored, how access is controlled, and how breaches are responded to.\n\n## Key Concepts\n\n- **[[GDPR]] (General Data Protection Regulation):** The EU's comprehensive privacy law — widely considered the gold standard globally. Applies to any organization processing data of EU residents. Requires consent, data minimization, breach notification within 72 hours, and grants extensive individual rights. Fines up to 4% of global annual revenue.\n- **[[CCPA]] (California Consumer Privacy Act):** The most significant US state privacy law. Gives California residents rights to know, delete, and opt out of sale of their personal data.\n- **[[HIPAA]] (Health Insurance Portability and Accountability Act):** US federal law governing health information privacy and security. Covers healthcare providers, insurers, and their business associates.\n- **[[COPPA]] (Children's Online Privacy Protection Act):** US federal law protecting children under 13 online. Requires verifiable parental consent before collecting children's data.\n- **[[PCI DSS]] (Payment Card Industry Data Security Standard):** Not a law but a compliance standard for organizations handling payment card data. Mandates strong security controls.\n- **[[PII]] (Personally Identifiable Information):** The core category of protected data — names, SSNs, addresses, biometrics, health records, financial data.\n- **Data Minimization:** A common principle — collect only the personal data necessary for the stated purpose, retain it only as long as needed.\n- **Right to Erasure (\"Right to be Forgotten\"):** Under GDPR, individuals can request deletion of their personal data in certain circumstances.\n\n## Why It Matters\nPrivacy regulations have become business requirements, not just legal formalities. Violations can result in massive fines, legal liability, and reputational damage. IT professionals are responsible for implementing the technical controls these laws require — encryption, access logging, data deletion workflows, breach notification processes. Understanding which laws apply to your organization and what they require is a baseline expectation in modern IT roles.\n\n## Related Topics\n- [[GDPR]]\n- [[CCPA]]\n- [[HIPAA]]\n- [[COPPA]]\n- [[PII]]\n- [[Data Breach]]\n- [[Confidentiality]]"},{"id":"Terms and Concepts/DDoS","title":"DDoS","section":"Terms and Concepts","domain":"Networking","description":"A cyberattack where multiple compromised systems flood a target with overwhelming traffic, rendering it unavailable to legitimate users.","tags":["IT","IT/Security","IT/Networking","Level/Intermediate"],"content":"# DDoS (Distributed Denial of Service)\n\n> A cyberattack where multiple compromised systems flood a target with overwhelming traffic, rendering it unavailable to legitimate users.\n\n## Overview\nA Distributed Denial of Service (DDoS) attack is one of the most disruptive cyberattacks — it doesn't steal data or compromise systems, it simply makes them unavailable. By flooding a target (website, server, or network) with traffic from thousands or millions of compromised devices simultaneously, the attacker exhausts the target's resources and denies legitimate users access.\n\nThe \"distributed\" aspect is what makes DDoS attacks so difficult to stop. Traditional DoS attacks come from a single source — easy to block once identified. DDoS attacks use a **botnet** — a network of compromised devices (computers, IoT devices, servers) controlled by the attacker — making it impossible to simply block a single IP address.\n\nHigh-profile DDoS attacks have taken down banks, DNS providers (like the 2016 Dyn attack that disrupted GitHub, Twitter, and Netflix), and government websites. Organizations in finance, gaming, and media are frequent targets.\n\n## Key Concepts\n\n- **Botnet:** A network of compromised devices (often infected with [[Malware]]) that the attacker controls remotely. May include millions of devices worldwide.\n- **Volumetric Attack:** Floods the target with massive traffic (measured in Gbps or Tbps) to saturate bandwidth. Examples: UDP floods, ICMP floods.\n- **Protocol Attack:** Exploits weaknesses in network protocols to exhaust server resources. Example: SYN flood exploits the TCP handshake process.\n- **Application Layer (Layer 7) Attack:** Targets specific application functionality with seemingly legitimate requests — harder to detect because traffic looks normal. Example: HTTP flood.\n- **Amplification Attack:** Exploits protocols (DNS, NTP) that produce responses much larger than the request, amplifying attack volume using small amounts of attacker bandwidth.\n- **Scrubbing Center:** DDoS mitigation services route traffic through scrubbing centers that identify and remove malicious traffic before it reaches the target.\n- **[[Anycast]] Mitigation:** Services like Cloudflare use anycast networks to absorb and distribute DDoS traffic across many data centers globally.\n- **[[Flood Guards]]:** Network devices configured to detect and rate-limit flood attacks.\n\n## How It Works\n\n1. Attacker assembles or rents a botnet of thousands of compromised devices.\n2. Command is sent to all botnet nodes to send traffic to the target simultaneously.\n3. Target's bandwidth, CPU, or connection table is exhausted by the volume.\n4. Legitimate users receive timeouts or connection errors.\n5. Attack continues until the attacker stops or mitigation services absorb/filter the traffic.\n\n## Why It Matters\n[[Availability]] is one-third of the [[CIA Triad]], and DDoS attacks are the most direct threat to it. IT professionals must understand DDoS attack types, mitigation strategies (scrubbing services, rate limiting, CDNs), and how to respond during an active attack. Organizations hosting internet-facing services must have a DDoS mitigation plan. This is a core topic in networking and security certifications.\n\n## Related Topics\n- [[Availability]]\n- [[CIA Triad]]\n- [[Flood Guards]]\n- [[IPS]]\n- [[Firewall]]\n- [[Cyber Attacks]]\n- [[Malware]]"},{"id":"Terms and Concepts/Default Groups","title":"Default Groups","section":"Terms and Concepts","domain":"Security","description":"Pre-built user groups in operating systems and Active Directory that come with predefined permissions and roles, providing a starting framework for access management.","tags":["IT","IT/IAM","Level/Intermediate"],"content":"# Default Groups\n\n> Pre-built user groups in operating systems and Active Directory that come with predefined permissions and roles, providing a starting framework for access management.\n\n## Overview\nDefault groups (also called built-in groups) are security groups that are automatically created when an operating system is installed or when Active Directory is set up. They represent common roles and permission levels needed in most environments — administrators, standard users, backup operators, and so on — so organizations don't have to build these from scratch.\n\nIn Windows environments, default groups exist at two levels: local groups (on individual computers) and domain groups (in [[Active Directory]]). Understanding which groups exist, what they can do, and how to use them properly is foundational to managing Windows security.\n\nThe [[Principle of least Privilege]] applies here — users should be members of only the groups necessary for their role, and powerful groups like Administrators should have as few members as possible.\n\n## Key Concepts\n\n**Local Windows Groups (on individual computers):**\n\n- **Administrators:** Full control over the local system — can install software, change settings, manage users, and perform any system task. Should be used sparingly.\n- **Users:** Standard user access. Can run applications and access their own files; cannot change system settings or install most software.\n- **Guests:** Highly restricted access. Typically disabled by default for security reasons.\n- **Backup Operators:** Can back up and restore files regardless of file permissions, but cannot perform other admin tasks.\n- **Power Users:** Legacy group from older Windows versions. Had elevated permissions but less than Administrator. Largely deprecated in modern Windows.\n\n**Active Directory Default Groups:**\n\n- **Domain Admins:** Full control over the entire domain. Highly privileged — membership should be tightly controlled.\n- **Enterprise Admins:** Even more powerful — controls the entire forest. Used only for forest-level changes.\n- **Schema Admins:** Allowed to modify the Active Directory schema. Should have no permanent members.\n- **Domain Users:** Default group for all domain accounts. Standard user permissions.\n- **Authenticated Users:** Any user who has logged in with valid credentials. Often used in permissions to mean \"anyone who's logged in.\"\n\n## Why It Matters\nIT professionals configure, manage, and troubleshoot permissions and group memberships daily. Knowing what default groups exist and what they're authorized to do is essential for proper [[Access Control]], security hardening (auditing who's in Administrator groups), and troubleshooting permission issues. Over-permissioned users are a leading cause of security incidents — understanding default groups helps prevent this.\n\n## Related Topics\n- [[Groups]]\n- [[Active Directory]]\n- [[Access Control]]\n- [[Principle of least Privilege]]\n- [[Local Groups]]\n- [[Group Policy]]"},{"id":"Terms and Concepts/Default Printer","title":"Default Printer","section":"Terms and Concepts","domain":"Networking","description":"The printer automatically selected by an operating system when a user sends a print job without specifying a particular printer.","tags":["IT","IT/OS","IT/Fundamentals","Level/Foundational"],"content":"# Default Printer\n\n> The printer automatically selected by an operating system when a user sends a print job without specifying a particular printer.\n\n## Overview\nThe default printer is the printer a computer uses when a user clicks \"Print\" without manually choosing a destination. Every OS maintains a default printer setting so users don't have to select a printer for every print job — particularly useful when most printing goes to the same device.\n\nIn enterprise environments, the default printer can be set by administrators via [[Group Policy]] or login scripts, ensuring users on specific computers or in specific locations automatically have the appropriate printer configured. On personal machines, users set this themselves through system settings.\n\nModern Windows (10/11) introduced a \"Let Windows manage my default printer\" feature, which dynamically sets the default printer to the last printer used at the current location. This behavior can be disabled for predictability, which is often preferred in managed enterprise environments.\n\n## Key Concepts\n\n- **Setting a Default Printer (Windows):** Settings → Bluetooth & devices → Printers & scanners → Select a printer → Set as default. Alternatively, right-click the printer in the legacy Printers control panel.\n- **Setting a Default Printer (macOS):** System Settings (or System Preferences) → Printers & Scanners → Select printer from list → Set as default at the bottom.\n- **Setting a Default Printer (Linux):** Through the system's printer settings GUI, or via command line: `lpoptions -d PrinterName`\n- **[[Group Policy]] Deployment:** In Windows domains, administrators use Group Policy preferences to push default printer settings to users based on their location, OU, or security group membership.\n- **Print Spooler:** The Windows service that manages the queue of print jobs. If printing fails, the spooler is often the first service to check and restart (`services.msc` or `net stop/start spooler`).\n- **Universal Print:** Microsoft's cloud-based print service that allows printers to be managed centrally through Azure and accessed from anywhere without traditional print servers.\n\n## Why It Matters\nManaging printers and default print settings is a routine IT helpdesk task. Users frequently report printing issues — wrong printer selected, print jobs queuing to an unavailable printer, or the default not being set correctly after a device change. IT professionals must know how to view installed printers, set defaults, clear the print queue, and restart the spooler. In enterprise environments, understanding how Group Policy deploys printers is also essential.\n\n## Related Topics\n- [[Operating System]]\n- [[Group Policy]]\n- [[Windows Operating Systems]]\n- [[macOS]]\n- [[Linux]]"},{"id":"Terms and Concepts/Desktop","title":"Desktop","section":"Terms and Concepts","domain":"Hardware","description":"A type of personal computer designed for use at a fixed location on a desk, consisting of a separate tower/case, monitor, keyboard, and mouse.","tags":["IT","IT/OS","IT/Hardware","Level/Foundational"],"content":"# Desktop (Computer)\n\n> A type of personal computer designed for use at a fixed location on a desk, consisting of a separate tower/case, monitor, keyboard, and mouse.\n\n## Overview\nA desktop computer is a full-size personal computer designed to remain stationary. Unlike a [[Laptop]] (which integrates all components in one portable unit), a desktop separates the processing unit (the tower or case containing the CPU, RAM, storage, etc.) from the display (monitor) and input devices (keyboard and mouse).\n\nDesktops are the workhorses of enterprise IT — they power most office workstations, engineering stations, and developer machines. They offer more performance per dollar than laptops, are easier to repair and upgrade, and can accommodate high-powered components that wouldn't fit in a portable form factor.\n\nIn enterprise environments, desktop management involves imaging, deployment, hardware maintenance, software configuration, and ongoing support — all core helpdesk and sysadmin responsibilities.\n\n## Key Concepts\n\n- **Tower/Case:** The main housing that contains the [[Motherboard]], [[CPU]], [[RAM]], storage drives, [[GPU]], [[Power Supply]], and expansion cards. Available in full tower, mid tower, and small form factor (SFF) sizes.\n- **[[Form Factor]]:** Desktop cases and motherboards come in standard form factors — ATX (full-size), Micro-ATX, Mini-ITX — that determine what components fit in what cases.\n- **Expandability:** Unlike laptops, most desktops can be upgraded — adding RAM, replacing storage, installing a dedicated GPU, or adding a PCIe card is typically straightforward.\n- **All-in-One (AIO):** A desktop variant that integrates the computer components into the back of the monitor. Less expandable but saves desk space. Common in retail and healthcare environments.\n- **Thin Client:** A minimal desktop device designed to connect to a remote server or virtual desktop ([[DaaS]]) rather than process locally. Low power, low cost, low maintenance.\n- **Workstation:** A high-performance desktop designed for demanding tasks — CAD/CAM, video editing, scientific computing. Features ECC RAM, professional GPUs, and multiple-core CPUs.\n- **Display Resolution:** Connected to a monitor; display quality depends on the monitor's resolution and refresh rate, and the capabilities of the GPU.\n\n## Why It Matters\nDesktop computers are ubiquitous in corporate environments. IT support professionals image, deploy, configure, troubleshoot, and maintain them constantly. Understanding desktop components — what a CPU does, how RAM affects performance, when storage is the bottleneck — is foundational hardware knowledge required for every IT support role and tested on CompTIA A+.\n\n## Related Topics\n- [[Computer]]\n- [[Laptop]]\n- [[Motherboard]]\n- [[CPU]]\n- [[RAM]]\n- [[Operating System]]\n- [[Form Factor]]"},{"id":"Terms and Concepts/DevOps","title":"DevOps","section":"Terms and Concepts","domain":"Cloud","description":"A set of practices and cultural philosophy that bridges software development (Dev) and IT operations (Ops) to enable faster, more reliable software delivery through automation, collaboration, and continuous improvement.","tags":["IT","IT/Scripting","IT/Cloud","Level/Advanced"],"content":"# DevOps\n\n> A set of practices and cultural philosophy that bridges software development (Dev) and IT operations (Ops) to enable faster, more reliable software delivery through automation, collaboration, and continuous improvement.\n\n## Overview\nDevOps emerged from the observation that development teams and operations teams traditionally worked in silos — developers wrote code and threw it \"over the wall\" to operations to deploy and maintain, often leading to friction, delays, and blame. DevOps is the cultural and technical movement that tears down that wall.\n\nAt its core, DevOps is about automating the software delivery pipeline — from writing code to testing to deploying to monitoring — and creating shared ownership of the entire process. When done well, DevOps enables organizations to release software updates multiple times per day rather than once per quarter.\n\nThe practices overlap significantly with [[Cloud Computing]] and [[Containers|containerization]] — modern DevOps heavily relies on cloud infrastructure, Docker, Kubernetes, and CI/CD pipelines. Infrastructure as Code (IaC) is a cornerstone concept: managing servers, networks, and configurations through version-controlled code rather than manual processes.\n\n## Key Concepts\n\n- **CI/CD (Continuous Integration / Continuous Delivery):** Automated pipelines that continuously build, test, and deploy code changes. CI detects integration problems early; CD ensures the software is always deployable.\n- **Infrastructure as Code (IaC):** Managing infrastructure through code files (Terraform, CloudFormation, Ansible) rather than manual configuration. Enables reproducibility, version control, and automation.\n- **[[Automation]]:** Automating builds, tests, deployments, and infrastructure provisioning reduces human error and accelerates delivery.\n- **[[Containers]] and Kubernetes:** Docker containers and Kubernetes orchestration are central to modern DevOps, providing portable, consistent deployment environments.\n- **Monitoring and Observability:** Continuous monitoring of applications and infrastructure in production provides feedback that drives improvement — logs, metrics, and traces.\n- **Shift Left Security (DevSecOps):** Integrating security testing into the development pipeline rather than treating it as a gate at the end.\n- **Version Control:** Everything — code, configuration, infrastructure — is stored in version control (Git). Enables collaboration, rollbacks, and auditing.\n\n## Why It Matters\nDevOps is one of the most significant trends reshaping IT roles. Organizations that adopt DevOps practices deploy software faster and with fewer incidents. IT professionals with DevOps skills — scripting, CI/CD, IaC, containers, cloud — are among the most in-demand in the industry. Even traditional sysadmin roles increasingly require DevOps familiarity as manual configuration management is replaced by automated pipelines.\n\n## Related Topics\n- [[Automation]]\n- [[Containers]]\n- [[Scripting]]\n- [[Cloud Computing]]\n- [[Orchestration]]\n- [[Software Deployment]]\n- [[Virtualization]]"},{"id":"Terms and Concepts/DHCP","title":"DHCP","section":"Terms and Concepts","domain":"Networking","description":"A network protocol that automatically assigns IP addresses and network configuration parameters to devices when they connect to a network.","tags":["IT","IT/Networking","Level/Foundational"],"content":"# DHCP (Dynamic Host Configuration Protocol)\n\n> A network protocol that automatically assigns IP addresses and network configuration parameters to devices when they connect to a network.\n\n## Overview\nDHCP is what allows devices to connect to a network without requiring someone to manually assign an IP address. When a laptop, phone, or any network device connects, it broadcasts a request asking \"Is there a DHCP server here? I need an IP address.\" The DHCP server responds with an available IP address, subnet mask, default gateway, and DNS server addresses — everything the device needs to communicate on the network.\n\nWithout DHCP, network administrators would have to manually configure IP addresses on every device — a manageable task for a handful of computers, but impractical for enterprises with thousands of devices or networks that serve constantly changing clients (like a public Wi-Fi network).\n\nDHCP servers are typically built into routers (for home/small business) or run as a dedicated server role (Windows Server DHCP, ISC DHCP on Linux) in enterprise environments.\n\n## Key Concepts\n\n- **IP Address Pool / Scope:** The range of IP addresses the DHCP server can assign. For example, 192.168.1.100–192.168.1.200.\n- **Lease:** DHCP assignments are temporary — called leases. The server assigns an IP for a defined duration (e.g., 8 hours, 1 day). Clients must renew or request a new lease.\n- **Lease Renewal:** Clients attempt to renew their lease at 50% of the lease duration. If renewal fails, they try again later. If the lease expires, the IP is returned to the pool.\n- **DHCP Reservation / Static Mapping:** Some devices (servers, printers, network devices) should always get the same IP. DHCP reservations assign a specific IP to a specific MAC address, combining the benefits of DHCP management with the consistency of a static IP.\n- **DHCP Options:** Additional configuration data sent with IP assignments — commonly DNS server addresses (Option 6), default gateway (Option 3), and domain name (Option 15).\n- **DHCP Relay Agent:** In large networks with multiple subnets, a relay agent forwards DHCP broadcasts between clients and a centralized DHCP server, avoiding the need for a server on every subnet.\n- **DORA Process:** The four-step DHCP negotiation — Discover → Offer → Request → Acknowledge.\n\n## How It Works (DORA)\n\n1. **Discover:** Client broadcasts \"Any DHCP servers out there?\" to 255.255.255.255.\n2. **Offer:** DHCP server responds with an available IP address offer.\n3. **Request:** Client formally requests the offered IP address.\n4. **Acknowledge:** Server confirms the assignment; client configures its network interface.\n\n## Why It Matters\nDHCP is one of the most fundamental network services — without it, devices can't communicate. IT professionals configure DHCP scopes, manage lease databases, troubleshoot IP conflicts, create reservations for critical devices, and ensure relay agents are working correctly. DHCP failures cause widespread connectivity issues, making it one of the first things to check when users report network problems.\n\n## Related Topics\n- [[IP Address]]\n- [[DNS]]\n- [[Subnet]]\n- [[Router]]\n- [[Network]]\n- [[ARP]]"},{"id":"Terms and Concepts/Digital Forensics","title":"Digital Forensics","section":"Terms and Concepts","domain":"Networking","description":"The systematic process of collecting, preserving, analyzing, and presenting digital evidence from computers, networks, and devices for investigative or legal purposes.","tags":["IT","IT/Security","Level/Advanced"],"content":"# Digital Forensics\n\n> The systematic process of collecting, preserving, analyzing, and presenting digital evidence from computers, networks, and devices for investigative or legal purposes.\n\n## Overview\nDigital forensics is the application of scientific investigation techniques to digital devices and data. When a security incident occurs — a cyberattack, data breach, employee misconduct, or criminal activity — digital forensics investigators recover and analyze evidence from computers, storage devices, mobile phones, network logs, and cloud systems to determine what happened, how, and who is responsible.\n\nThe discipline is governed by the principle of evidence integrity: everything must be done in a way that preserves the original evidence and can withstand legal scrutiny. This means following strict [[Chain of Custody]] procedures, using write-blocked forensic copies, and documenting every action taken.\n\nDigital forensics overlaps with incident response — the two disciplines are complementary, with forensics providing the deeper investigative analysis that follows initial containment.\n\n## Key Concepts\n\n- **[[Chain of Custody]]:** The documented trail proving that evidence was properly collected, handled, and stored without tampering. Required for evidence to be admissible in court.\n- **Forensic Image:** An exact, bit-for-bit copy of a storage device created using a write blocker. Investigators work from the copy, never the original.\n- **Write Blocker:** Hardware or software that allows reading a storage device without making any changes to it. Essential for preserving evidence integrity.\n- **[[Hashing]] for Integrity:** SHA-256 or MD5 hashes are computed on the original and the forensic copy. Matching hashes prove the copy is identical to the original.\n- **Data Acquisition:** The process of creating a forensic copy of evidence. Must be done before any analysis begins.\n- **Data Carving:** Recovering deleted files by searching for file signatures in raw disk space, even after the file system entries have been removed.\n- **Metadata Analysis:** Files contain metadata (creation time, modification time, author, GPS coordinates for photos) that can be crucial evidence.\n- **Network Forensics:** Analyzing captured network traffic (pcap files) to reconstruct what occurred during an incident.\n- **Mobile Forensics:** Extracting and analyzing data from smartphones — call logs, messages, app data, location history.\n\n**Common Tools:**\n- FTK (Forensic Toolkit) and FTK Imager — imaging and analysis\n- Autopsy / Sleuth Kit — open-source forensic analysis\n- Wireshark — network traffic analysis\n- Cellebrite — mobile device forensics\n\n## Why It Matters\nDigital forensics is a growing field in cybersecurity. Incident response teams perform forensic analysis after every significant breach. Law enforcement relies on digital evidence in criminal investigations. IT professionals who understand forensic principles can respond to incidents more effectively, preserve evidence correctly, and support legal proceedings when required. Even non-forensic IT roles benefit from understanding how to avoid inadvertently destroying evidence during incident response.\n\n## Related Topics\n- [[Chain of Custody]]\n- [[Hashing]]\n- [[CyberOps]]\n- [[Logging]]\n- [[Auditing]]\n- [[Malware]]\n- [[NIST Cybersecurity Framework]]"},{"id":"Terms and Concepts/Digital License","title":"Digital License","section":"Terms and Concepts","domain":"Security","description":"An electronically stored authorization that grants a user or device the right to use a specific software product under defined terms and conditions.","tags":["IT","IT/IAM","IT/OS","Level/Foundational"],"content":"# Digital License\n\n> An electronically stored authorization that grants a user or device the right to use a specific software product under defined terms and conditions.\n\n## Overview\nA digital license is the modern form of software authorization. Rather than a physical certificate or paper document, a digital license is stored electronically — tied to a user account, a device, or authenticated online against a licensing server. When you activate Windows, install Adobe Creative Cloud, or subscribe to Microsoft 365, you're using digital licensing.\n\nDigital licensing replaced physical media and product keys for most consumer and enterprise software. For IT professionals, understanding the different license models is important for budgeting, compliance, and ensuring that software is deployed within its permitted terms.\n\nLicense compliance — ensuring an organization has licenses for all the software it's running — is a key responsibility in IT administration and is audited by software vendors.\n\n## Key Concepts\n\n- **Perpetual License:** A one-time purchase granting the right to use a specific version of software indefinitely. No ongoing fees, but typically no access to future major versions. Example: purchasing Office 2021.\n- **Subscription License:** Recurring fee (monthly or annual) for continued access. Includes updates and often cloud features. Example: Microsoft 365, Adobe Creative Cloud.\n- **Volume License:** A single agreement covering multiple users or devices within an organization. Often includes Software Assurance (rights to new versions during the agreement period).\n- **[[OEM]] License:** Software bundled with hardware, tied to that specific device. Cannot be transferred to a different machine. Common for Windows pre-installed on PCs.\n- **[[KMS]] (Key Management Service):** A Microsoft-provided tool for enterprise activation. An internal KMS server activates multiple devices within the organization without each needing to contact Microsoft.\n- **Digital Activation:** Windows 10/11 digital licenses are tied to hardware fingerprints and Microsoft accounts, enabling automatic reactivation after hardware changes.\n- **[[Product Key]]:** An alphanumeric code that proves license ownership. Used to activate software. Increasingly replaced by account-based activation.\n- **EULA (End User License Agreement):** The legal agreement defining what you can and cannot do with the software. Governs usage rights.\n- **Software Asset Management (SAM):** The practice of tracking software licenses across an organization to ensure compliance and optimize costs.\n\n## Why It Matters\nLicense compliance is an IT responsibility with real financial and legal consequences. Running unlicensed software can result in vendor audits, fines, and reputational damage. IT professionals must understand the different license types to properly procure software, configure activation, and maintain compliance. [[KMS]] activation, volume licensing, and digital entitlements are daily realities in enterprise IT administration.\n\n## Related Topics\n- [[Licensing]]\n- [[KMS]]\n- [[Product Key]]\n- [[OEM]]\n- [[Software]]\n- [[Software Deployment]]"},{"id":"Terms and Concepts/Directory","title":"Directory","section":"Terms and Concepts","domain":"Cloud","description":"A container in a file system that holds files and other directories (subdirectories), used to organize data in a hierarchical tree structure.","tags":["IT","IT/OS","Level/Foundational"],"content":"# Directory\n\n> A container in a file system that holds files and other directories (subdirectories), used to organize data in a hierarchical tree structure.\n\n## Overview\nA directory (also called a folder in most modern GUI environments) is a fundamental organizational unit in any file system. Just as physical filing cabinets use folders within drawers to organize documents, computer file systems use directories to group related files. Directories can contain other directories (called subdirectories), creating a tree structure that allows highly granular organization.\n\nEvery file system has a root directory — the top-level container from which all other directories branch. On Windows, this is `C:\\`; on Linux/Unix, it is `/`. All files and directories on the system exist somewhere within this tree.\n\nThe term \"directory\" tends to be used in command-line and server contexts; \"folder\" is used in graphical interfaces. They mean the same thing.\n\n## Key Concepts\n\n- **Root Directory:** The top-level directory in a file system. On Windows: `C:\\`. On Linux/Mac: `/`.\n- **Subdirectory:** A directory inside another directory. `C:\\Users\\Ryan\\Documents` — Documents is a subdirectory of Ryan, which is a subdirectory of Users.\n- **Path:** The address of a file or directory in the file system. Absolute paths start from the root; relative paths start from the current working directory.\n- **Current Working Directory (CWD):** The directory a terminal or program is currently operating in. Important for relative path references.\n- **Hidden Directories:** On Unix/Linux, directories beginning with `.` (e.g., `.ssh`, `.config`) are hidden from default directory listings.\n- **Permissions:** Directories have permissions just like files — controlling who can list, enter, create files in, or delete from a directory.\n- **Directory vs. Active Directory:** Not to be confused with [[Active Directory]] — a directory service for managing network identities. A file system directory is purely about organizing files.\n- **Navigation Commands:** `cd` (change directory), `ls`/`dir` (list contents), `pwd` (print working directory), `mkdir` (create directory), `rmdir`/`rm -r` (remove directory).\n\n## Why It Matters\nUnderstanding directories is essential for any IT professional. File management, scripting, troubleshooting, and server administration all require comfort with navigating and manipulating directory structures. In Linux environments especially, knowing the standard directory layout (`/etc`, `/var`, `/home`, `/usr`, etc.) is critical for locating configuration files, logs, and installed software.\n\n## Related Topics\n- [[File System]]\n- [[File Management]]\n- [[File Permission]]\n- [[BASH]]\n- [[Powershell]]\n- [[Operating System]]"},{"id":"Terms and Concepts/Disaster Recovery","title":"Disaster Recovery","section":"Terms and Concepts","domain":"Security","description":"The set of policies, tools, and procedures that enable an organization to restore IT systems and data after a disruptive event — natural disaster, cyberattack, hardware failure, or human error.","tags":["IT","IT/Security","Level/Intermediate"],"content":"# Disaster Recovery\n\n> The set of policies, tools, and procedures that enable an organization to restore IT systems and data after a disruptive event — natural disaster, cyberattack, hardware failure, or human error.\n\n## Overview\nDisaster Recovery (DR) is the discipline of planning, preparing for, and executing the restoration of IT operations after a disruption. Unlike day-to-day IT operations, DR focuses on the worst-case scenario — what happens when a major system goes down, a ransomware attack encrypts everything, or a data center floods.\n\nThe goal of DR is not just to recover, but to recover within acceptable limits. Every organization has a tolerance for how much data it can afford to lose and how long it can afford to be offline. DR plans are built around these tolerances.\n\nDR is a subset of the broader Business Continuity Plan (BCP) — while DR focuses on IT systems, BCP covers the entire organization's ability to operate during and after a disruption.\n\n## Key Concepts\n\n- **RPO (Recovery Point Objective):** The maximum acceptable amount of data loss, expressed as time. If RPO is 4 hours, backups must run at least every 4 hours — losing more than 4 hours of data is unacceptable.\n- **RTO (Recovery Time Objective):** The maximum time systems can be offline before the impact becomes unacceptable. Drives decisions about recovery infrastructure and procedures.\n- **Business Impact Analysis (BIA):** An assessment that identifies critical systems and quantifies the impact of downtime — used to set RPO and RTO targets.\n- **[[Backups]]:** The foundation of data recovery. Without backups, data lost in a disaster cannot be recovered.\n- **Failover:** Automatically switching to a redundant system when the primary fails. A warm or hot standby site enables rapid failover.\n- **DR Site Types:**\n  - *Cold site:* Empty facility with power/connectivity — requires hardware deployment. Cheapest but slowest to activate (days to weeks).\n  - *Warm site:* Pre-configured hardware awaiting data restore. Moderate cost; activation takes hours to days.\n  - *Hot site:* Fully operational mirror of production. Fastest activation (minutes); most expensive.\n- **[[Redundancy]]:** Duplicate components, systems, or sites that take over when primary resources fail.\n- **DR Testing:** Testing DR plans is critical — organizations regularly discover that untested plans fail during real events. Tests include tabletop exercises, simulation drills, and full failover tests.\n- **Cloud DR:** Cloud platforms enable cost-effective DR — replicate to the cloud, fail over when needed, pay only for what you use.\n\n## Why It Matters\nEvery organization depends on IT to operate. Disasters — whether technical failures or cyberattacks — will occur. Having a tested, documented DR plan means the difference between recovering in hours vs. weeks, or not recovering at all. IT professionals at all levels participate in DR — from configuring backup systems to executing recovery procedures to testing plans. DR planning is tested in CompTIA certifications and is a core responsibility in sysadmin and IT operations roles.\n\n## Related Topics\n- [[Backups]]\n- [[Availability]]\n- [[Redundancy]]\n- [[Cloud Computing]]\n- [[Ransomware]]\n- [[SLA]]\n- [[Five Nines]]"},{"id":"Terms and Concepts/Display Resolution","title":"Display Resolution","section":"Terms and Concepts","domain":"Networking","description":"The number of pixels displayed on a screen, expressed as width × height (e.g., 1920×1080), determining the sharpness and detail of the visual output.","tags":["IT","IT/Hardware","Level/Foundational"],"content":"# Display Resolution\n\n> The number of pixels displayed on a screen, expressed as width × height (e.g., 1920×1080), determining the sharpness and detail of the visual output.\n\n## Overview\nDisplay resolution describes how many individual pixels make up the image on a monitor, TV, or display device. More pixels means more detail, sharper text, and cleaner images. Resolution is one of the primary specs when selecting a monitor for a workstation, deploying digital signage, or configuring remote desktop connections.\n\nResolution is often described by a shorthand name (1080p, 4K) that refers to specific pixel dimensions. For IT support, understanding resolution matters when troubleshooting display issues, configuring monitors, setting up remote desktop, and ensuring compatibility between hardware and software.\n\n## Key Concepts\n\n- **Pixel:** The smallest unit of a display image. Each pixel can display a specific color, and millions together form the image.\n- **Aspect Ratio:** The proportional relationship between width and height. Most modern monitors are 16:9 (widescreen). Older displays used 4:3 or 16:10.\n- **PPI (Pixels Per Inch):** Pixel density — how many pixels fit in one inch of screen. Higher PPI = sharper image on the same physical size display. Important for phones and high-DPI monitors.\n- **DPI (Dots Per Inch):** Technically a print term, but often used interchangeably with PPI for displays.\n- **Scaling:** Windows and macOS automatically scale UI elements up on high-DPI (4K) displays so text isn't tiny. IT professionals configure scaling settings for optimal readability.\n- **Refresh Rate:** Related to resolution — measured in Hz, determines how many times per second the image updates. Standard is 60Hz; gaming monitors go higher (144Hz, 240Hz).\n\n## Common Resolutions\n\n| Name | Dimensions | Common Use |\n|------|-----------|------------|\n| 720p (HD) | 1280×720 | Older monitors, streaming |\n| 1080p (Full HD) | 1920×1080 | Standard office monitor, most common |\n| 1440p (QHD/2K) | 2560×1440 | High-performance workstations, gaming |\n| 4K (UHD) | 3840×2160 | Professional workstations, video production |\n| 8K | 7680×4320 | Professional video production |\n\n## Why It Matters\nIT support professionals configure monitor resolution when setting up workstations, troubleshoot display issues (blurry text, wrong resolution after driver update), and configure remote desktop connections at appropriate resolutions. Understanding resolution helps explain why a monitor looks blurry (running at non-native resolution) or why text appears tiny on a new 4K display (scaling not configured).\n\n## Related Topics\n- [[Hardware]]\n- [[GPU]]\n- [[Drivers]]\n- [[Desktop]]\n- [[Remote Desktop]]\n- [[Operating System]]"},{"id":"Terms and Concepts/DMZ","title":"DMZ","section":"Terms and Concepts","domain":"Networking","description":"A network segment that sits between the internal network and the internet, hosting public-facing servers in an isolated zone that limits exposure to the internal network.","tags":["IT","IT/Networking","IT/Security","Level/Intermediate"],"content":"# DMZ (Demilitarized Zone)\n\n> A network segment that sits between the internal network and the internet, hosting public-facing servers in an isolated zone that limits exposure to the internal network.\n\n## Overview\nThe DMZ (Demilitarized Zone) is a network architecture pattern borrowed from the military concept of a neutral buffer zone. In networking, a DMZ is a separate network segment that sits between the trusted internal network (corporate LAN) and the untrusted external network (the internet).\n\nPublic-facing servers — web servers, email servers, DNS servers, VPN endpoints — are placed in the DMZ. External users can reach these services, but a DMZ architecture ensures that even if an attacker compromises a server in the DMZ, they cannot directly access the internal network. Additional firewall rules must be crossed to reach internal systems.\n\nA typical DMZ uses two firewalls: one between the internet and the DMZ, and another between the DMZ and the internal network. Some simpler implementations use a single firewall with three interfaces — one for the internet, one for the DMZ, and one for the internal network.\n\n## Key Concepts\n\n- **Perimeter Firewall:** The outer firewall controlling traffic between the internet and the DMZ. Allows only specific inbound ports (e.g., 80/443 for web, 25 for email).\n- **Internal Firewall:** The inner firewall controlling what can flow from the DMZ into the internal network. Very restrictive — DMZ servers should not be able to initiate connections to internal systems.\n- **Bastion Host:** A server in the DMZ that is hardened and configured to withstand attacks — web servers, mail servers, and jump boxes are examples.\n- **Jump Host / Bastion:** A hardened server in the DMZ used as an intermediate access point for administrators to reach internal systems securely.\n- **Traffic Flow:** External → DMZ is permitted for specific services. DMZ → Internal is tightly restricted. External → Internal is blocked entirely.\n- **Isolation:** If a DMZ server is compromised, the attacker sees only other DMZ servers and the internet — not the internal databases, file servers, or workstations.\n- **Common DMZ Services:** Web servers, email servers, [[DNS]] servers, reverse proxies, VPN concentrators.\n\n## How It Works\n\n1. External user requests `https://company.com`.\n2. Outer firewall allows port 443 traffic to the web server in the DMZ.\n3. Web server processes the request. If it needs to query a database, it must pass through the inner firewall under tightly controlled rules.\n4. The internal database is never directly reachable from the internet.\n\n## Why It Matters\nThe DMZ is a foundational network security design concept. Understanding how it works helps IT professionals design secure network architectures, configure firewall rules, and understand why public-facing services require different security controls than internal systems. It is a core topic in security certifications and network architecture design.\n\n## Related Topics\n- [[Firewall]]\n- [[Network]]\n- [[Access Control]]\n- [[VPN]]\n- [[DNS]]\n- [[Web Server]]\n- [[IDS]]"},{"id":"Terms and Concepts/DNS","title":"DNS","section":"Terms and Concepts","domain":"Networking","description":"The internet's \\\"phone book\\\" — a distributed system that translates human-readable domain names (like google.com) into the IP addresses that computers use to communicate.","tags":["IT","IT/Networking","Level/Foundational"],"content":"# DNS (Domain Name System)\n\n> The internet's \"phone book\" — a distributed system that translates human-readable domain names (like google.com) into the IP addresses that computers use to communicate.\n\n## Overview\nDNS is one of the most critical services on the internet. Humans use domain names because they're memorable; computers communicate using IP addresses. DNS bridges these two worlds — when you type `www.google.com` in a browser, DNS translates that name into an IP address (like `142.250.80.78`) so your computer knows where to send the request.\n\nDNS is a globally distributed, hierarchical database. No single server holds all DNS records — instead, responsibility is delegated through a hierarchy of servers: root servers → TLD servers (.com, .org) → authoritative nameservers for specific domains.\n\nDNS runs on port 53 using both UDP (for most queries) and TCP (for larger responses or zone transfers). It is a foundational service that essentially everything else depends on — if DNS is broken, most internet-dependent services appear to be down even if the underlying servers are fully operational.\n\n## Key Concepts\n\n- **DNS Resolver:** The client-side component that initiates DNS queries. Provided by your ISP, your organization, or a public resolver (like 8.8.8.8 or 1.1.1.1).\n- **Authoritative DNS Server:** The definitive source of DNS records for a domain. When asked about `google.com`, Google's authoritative server provides the answer.\n- **Root Servers:** The top of the DNS hierarchy. 13 root server groups (operated by organizations worldwide) point queries to the right TLD servers.\n- **TLD Servers:** Servers responsible for top-level domains (.com, .org, .net, .uk, etc.). They point to authoritative servers for specific domains.\n- **DNS Records:** Individual entries in the DNS system defining a mapping. See [[DNS Record]] for full types.\n- **TTL (Time To Live):** How long a DNS response can be cached before it must be re-queried. Shorter TTL = faster propagation of changes; longer TTL = less server load.\n- **DNS Caching:** Resolvers and clients cache answers to reduce query volume. Changes to DNS records may take TTL time to propagate.\n- **[[DNS Zones]]:** Portions of the DNS namespace managed by a specific organization or administrator.\n- **DNSSEC:** DNS Security Extensions — adds digital signatures to DNS records to prevent tampering and spoofing.\n\n## How It Works\n\n1. User types `www.example.com`. Device checks its local DNS cache.\n2. If not cached, the resolver queries a root server, which refers to the `.com` TLD server.\n3. The TLD server refers to `example.com`'s authoritative nameserver.\n4. The authoritative server returns the A record (IP address) for `www.example.com`.\n5. The resolver caches the result and returns the IP to the browser.\n6. Browser connects to the IP address.\n\n## Why It Matters\nDNS is foundational to everything networked. IT professionals configure DNS records for domains, troubleshoot DNS resolution failures, secure DNS against poisoning attacks, and manage internal DNS servers in Windows environments. Understanding DNS is tested on CompTIA A+, Network+, and Security+ — and it comes up constantly in real-world IT work.\n\n## Related Topics\n- [[DNS Record]]\n- [[DNS Zones]]\n- [[DNS Sinkhole]]\n- [[DHCP]]\n- [[Domain Name]]\n- [[Anycast DNS]]\n- [[Common Ports]]"},{"id":"Terms and Concepts/DNS Policies","title":"DNS Policies","section":"Terms and Concepts","domain":"Networking","description":"Configuration rules that control how a DNS server responds to queries based on criteria like source IP, time of day, or domain — enabling security enforcement, traffic management, and split-horizon DNS.","tags":["IT","IT/Networking","Level/Advanced"],"content":"# DNS Policies\n\n> Configuration rules that control how a DNS server responds to queries based on criteria like source IP, time of day, or domain — enabling security enforcement, traffic management, and split-horizon DNS.\n\n## Overview\nDNS policies allow administrators to define how their DNS server behaves in response to different types of queries, rather than simply returning the same answer to everyone. By applying rules based on who is asking, what they're asking for, and when, organizations can implement security controls, optimize traffic, and deliver different DNS responses to different user groups.\n\nDNS policies are a feature of Windows Server DNS (available since Server 2016) and are also available in BIND and other enterprise DNS servers. They represent a more granular level of DNS management beyond basic record configuration.\n\n## Key Concepts\n\n- **Policy Criteria:** Rules can trigger based on client IP (which subnet is the query coming from?), query type (what record type is requested?), domain name, time of day, or FQDN patterns.\n- **Response Actions:** Policies can allow resolution, deny it, redirect the client to a different IP, or return a custom response.\n- **Split-Horizon DNS (Split-Brain DNS):** A common policy pattern — internal clients get internal IP addresses for a domain (reaching servers directly on the LAN), while external clients get the public IP. Enables seamless access for both audiences without exposing internal infrastructure.\n- **DNS Filtering / Content Control:** Policies can block queries for categories of domains (adult content, gambling, known malware) — effectively implementing web content filtering at the DNS layer.\n- **[[DNS Sinkhole]] Integration:** Policies can redirect known malicious domains to a sinkhole IP as a security control.\n- **Load Balancing:** DNS policies can distribute queries across multiple servers by returning different IP addresses to different clients or at different times.\n- **Geo-Routing:** Return different IPs based on the geographic location of the querying client, directing users to the nearest server.\n\n## Why It Matters\nDNS policies give IT administrators fine-grained control over how name resolution behaves across the network. In enterprise environments, split-horizon DNS is common and must be understood when troubleshooting connectivity issues between internal and external users. Security-focused DNS policies (blocking malicious domains, implementing DNS-layer content filtering) are increasingly deployed as lightweight, network-wide security controls. Understanding DNS policies is relevant for Windows Server administration and network security roles.\n\n## Related Topics\n- [[DNS]]\n- [[DNS Zones]]\n- [[DNS Sinkhole]]\n- [[Manage DNS Zones]]\n- [[Active Directory]]\n- [[Network]]"},{"id":"Terms and Concepts/DNS Record","title":"DNS Record","section":"Terms and Concepts","domain":"Networking","description":"An entry in a DNS zone file that maps a domain name to specific data — most commonly an IP address, but also mail servers, text information, and other values.","tags":["IT","IT/Networking","Level/Intermediate"],"content":"# DNS Record\n\n> An entry in a DNS zone file that maps a domain name to specific data — most commonly an IP address, but also mail servers, text information, and other values.\n\n## Overview\nDNS records are the individual data entries stored in the [[DNS]] system. Each record has a type that defines what kind of information it contains. When you visit a website, a DNS A record maps the domain to an IP address. When you send email, an MX record tells your mail client which server handles email for that domain.\n\nDNS records are stored on authoritative nameservers and managed by whoever controls the domain's DNS hosting (the domain registrar, a web host, or a company's own DNS servers). Changes to DNS records propagate based on the record's TTL value.\n\nIT professionals regularly create and manage DNS records when setting up websites, configuring email services, implementing SPF/DKIM for email security, and verifying domain ownership.\n\n## Key Concepts\n\n| Record Type | Full Name | Purpose |\n|-------------|-----------|---------|\n| **A** | Address | Maps a domain/hostname to an IPv4 address |\n| **AAAA** | IPv6 Address | Maps a domain/hostname to an IPv6 address |\n| **CNAME** | Canonical Name | Creates an alias — points one domain name to another (e.g., `www.example.com` → `example.com`) |\n| **MX** | Mail Exchange | Specifies the mail server for receiving email for a domain |\n| **TXT** | Text | Stores arbitrary text data; used for SPF, DKIM, and domain verification |\n| **PTR** | Pointer | Reverse lookup — maps an IP address back to a domain name |\n| **NS** | Nameserver | Specifies the authoritative nameservers for a domain |\n| **SOA** | Start of Authority | Contains authoritative info about the zone: primary NS, admin email, serial number, and timers |\n| **SRV** | Service | Defines host and port for specific services (e.g., SIP, LDAP, Microsoft Teams) |\n| **CAA** | Certification Authority Authorization | Specifies which Certificate Authorities may issue SSL certs for the domain |\n\n- **TTL (Time to Live):** How long a resolver should cache the record. Lower values (e.g., 300 seconds) mean faster propagation of changes; higher values reduce DNS query volume.\n- **SPF Record (TXT):** Specifies which mail servers are authorized to send email on behalf of a domain. Helps prevent email spoofing.\n- **DKIM (TXT):** A cryptographic signature added to email headers to verify the message was sent by an authorized server.\n- **DMARC (TXT):** Builds on SPF and DKIM to define policy for handling unauthenticated email.\n\n## Why It Matters\nDNS record management is a regular task for IT professionals. Setting up a website means creating A/CNAME records. Setting up email requires MX, SPF, DKIM, and DMARC records. Verifying domain ownership (for SSL certificates, Microsoft 365) uses TXT records. Understanding each record type and its function is tested in CompTIA A+, Network+, and is a practical daily skill in IT operations and web management roles.\n\n## Related Topics\n- [[DNS]]\n- [[DNS Zones]]\n- [[Domain Name]]\n- [[IP Address]]\n- [[SSL]]\n- [[TLS]]"},{"id":"Terms and Concepts/DNS Sinkhole","title":"DNS Sinkhole","section":"Terms and Concepts","domain":"Networking","description":"A security technique that redirects DNS queries for malicious domains to a controlled IP address, preventing infected systems from communicating with attacker infrastructure.","tags":["IT","IT/Networking","IT/Security","Level/Advanced"],"content":"# DNS Sinkhole\n\n> A security technique that redirects DNS queries for malicious domains to a controlled IP address, preventing infected systems from communicating with attacker infrastructure.\n\n## Overview\nA DNS sinkhole (also called DNS blackholing) is a defensive tool that intercepts DNS queries and substitutes a fake response. When a device on the network tries to resolve a malicious domain — a command-and-control (C2) server, a phishing site, a malware distribution point — the DNS sinkhole responds with a harmless IP address (or no address at all) instead of the real one. The device's traffic never reaches the attacker's infrastructure.\n\nThis technique works because most malware, botnets, and phishing campaigns rely on domain names (rather than hardcoded IPs) to reach their infrastructure. Sinkholes exploit this dependency — cut off DNS resolution to the malicious domain and the malware is blinded.\n\nDNS sinkholes are implemented on internal DNS servers (where the organization controls all DNS queries for its clients) or via threat intelligence integration with DNS services. Commercial products like Cisco Umbrella (formerly OpenDNS) and Pi-hole implement sinkholing automatically using threat intelligence feeds.\n\n## Key Concepts\n\n- **Sinkhole IP:** The IP address returned in place of the real malicious domain. Often `0.0.0.0`, a loopback address, or a monitoring server that logs the connection attempt.\n- **Domain Blacklist / Blocklist:** A list of known malicious domains the sinkhole intercepts. Must be regularly updated with threat intelligence feeds.\n- **C2 Disruption:** The primary use case — preventing malware-infected devices from \"phoning home\" to the attacker's command-and-control server.\n- **Threat Intelligence:** DNS sinkholes become more effective when fed real-time threat intel (lists of malicious domains from security vendors, government feeds, or community sources like Abuse.ch).\n- **False Positives:** A risk — a legitimate domain incorrectly listed as malicious will be blocked. Good threat intel sources and regular review mitigate this.\n- **Logging and Detection:** A well-configured sinkhole logs which devices tried to reach malicious domains — a valuable signal that a device may be compromised.\n- **[[Honeypots]]:** The sinkhole IP can point to a honeypot that simulates a response, gathering information about the malware's behavior.\n\n## Why It Matters\nDNS sinkholes are a cost-effective, non-disruptive security control deployable on any DNS infrastructure. They help detect compromised devices, block malware from communicating, and protect users from phishing sites — all without installing software on endpoints. IT security professionals are expected to understand this technique as part of layered network defense. Products like Cisco Umbrella, Cloudflare Gateway, and Pi-hole all use sinkholing principles.\n\n## Related Topics\n- [[DNS]]\n- [[Malware]]\n- [[Honeypots]]\n- [[IDS]]\n- [[Cyber Attacks]]\n- [[CyberOps]]\n- [[DNS Policies]]"},{"id":"Terms and Concepts/DNS Zones","title":"DNS Zones","section":"Terms and Concepts","domain":"Networking","description":"Administrative portions of the DNS namespace for which a specific DNS server holds authoritative records and is responsible for managing.","tags":["IT","IT/Networking","Level/Intermediate"],"content":"# DNS Zones\n\n> Administrative portions of the DNS namespace for which a specific DNS server holds authoritative records and is responsible for managing.\n\n## Overview\nA DNS zone is a distinct, manageable section of the DNS namespace. Think of it as a \"folder\" within the DNS hierarchy that a specific organization or administrator controls. The DNS server responsible for a zone holds the authoritative records for all domains within it.\n\nEvery registered domain has at least one DNS zone. For example, `example.com` is a zone — its authoritative DNS server holds all the A records, MX records, CNAMEs, and other records for `example.com` and its subdomains. Large organizations may delegate subdomains to separate zones with their own authoritative servers (e.g., `sales.example.com` and `engineering.example.com` as separate zones).\n\nIn Windows Server, DNS zones are managed through the DNS Manager console and are a core component of [[Active Directory]] integration.\n\n## Key Concepts\n\n- **Primary Zone:** The master copy of a zone — authoritative records are created and edited here. In Windows AD-integrated zones, the primary zone is stored in Active Directory itself, allowing any domain controller to act as authoritative.\n- **Secondary Zone:** A read-only replica of a primary zone, obtained via zone transfer. Provides redundancy and load distribution for DNS queries.\n- **Stub Zone:** Contains only NS records and the minimal information needed to find the authoritative servers for a zone. Used to maintain referral efficiency without a full zone transfer.\n- **Forward Lookup Zone:** The most common type — maps domain names to IP addresses (A/AAAA records). When you query `www.example.com`, a forward lookup zone provides the answer.\n- **Reverse Lookup Zone:** Maps IP addresses back to domain names (PTR records). Used in logging, email spam filtering (rDNS), and network troubleshooting. Named in reverse notation (e.g., `1.168.192.in-addr.arpa`).\n- **Zone Transfer (AXFR/IXFR):** The process of copying zone data from a primary server to secondary servers. AXFR = full transfer; IXFR = incremental (only changes). Zone transfers should be restricted to authorized secondary servers.\n- **Split DNS (Split-Horizon):** Two zones with the same name — one for internal clients (returns internal IPs) and one for external clients (returns public IPs). See [[DNS Policies]].\n- **SOA Record:** Every zone starts with a Start of Authority (SOA) record defining the primary nameserver, admin email, serial number, and synchronization timers.\n\n## Why It Matters\nUnderstanding DNS zones is essential for any IT professional managing Windows Server environments with Active Directory, hosting websites, or configuring email. Zone configuration determines how DNS resolution works for an organization's domains. Incorrectly configured zones cause DNS failures, which appear as broken websites, email delivery problems, and inability to log into domain-joined computers.\n\n## Related Topics\n- [[DNS]]\n- [[DNS Record]]\n- [[Manage DNS Zones]]\n- [[Active Directory]]\n- [[Domain]]\n- [[FQDN]]"},{"id":"Terms and Concepts/Domain","title":"Domain","section":"Terms and Concepts","domain":"Networking","description":"In a Windows networking context, a domain is a logical grouping of computers, users, and resources managed centrally by a domain controller running Active Directory.","tags":["IT","IT/IAM","IT/Networking","Level/Intermediate"],"content":"# Domain (Windows/Active Directory)\n\n> In a Windows networking context, a domain is a logical grouping of computers, users, and resources managed centrally by a domain controller running Active Directory.\n\n## Overview\nIn Windows networking, a \"domain\" refers to an administrative boundary managed by [[Active Directory]]. It is a collection of users, computers, printers, and other network objects that share a common directory database, security policies, and authentication infrastructure. Users log into the domain once and gain access to all resources they're authorized for — this is Single Sign-On.\n\nEvery Windows domain has at least one domain controller (DC) — a server running [[Active Directory Domain Services]] — which stores the directory database and handles all authentication requests. Organizations typically deploy multiple domain controllers for redundancy.\n\nThe domain name (e.g., `company.local` or `company.com`) also serves as the DNS namespace for the domain. When a computer joins a domain, it becomes a managed, trusted member of that administrative unit.\n\nThis is distinct from an internet domain name — though the two share the same naming system, an Active Directory domain is an internal construct.\n\n## Key Concepts\n\n- **Domain Controller (DC):** A Windows Server running AD DS that authenticates users and enforces policies. Every domain needs at least one DC.\n- **Domain Name:** The identifier for the domain — typically an internal namespace like `corp.contoso.com`.\n- **Domain Join:** When a computer is joined to a domain, it becomes a managed member — Group Policy is applied, and domain users can log in.\n- **[[FQDN]] (Fully Qualified Domain Name):** The complete domain name used to identify resources. `server1.corp.contoso.com` is the FQDN of a server named `server1` in the `corp.contoso.com` domain.\n- **Domain Trust:** A relationship between two domains allowing users in one to access resources in the other. Can be one-way or two-way, transitive or non-transitive.\n- **Tree:** Multiple related domains sharing a common namespace form a tree. `corp.contoso.com` and `sales.contoso.com` are in the same tree.\n- **Forest:** The highest-level structure in Active Directory. A forest contains one or more domain trees and shares a common schema and [[Global Catalog]].\n- **Workgroup vs. Domain:** A workgroup is a peer-to-peer arrangement with no central management. A domain has centralized management through Active Directory. Domains are standard in enterprise environments.\n\n## Why It Matters\nUnderstanding Windows domains is foundational for any IT professional in a Windows enterprise environment. Joining computers to the domain, managing domain user accounts, troubleshooting login failures, and understanding trust relationships are all everyday tasks. Domain concepts appear extensively on CompTIA A+ and Network+ exams and are central to every Microsoft certification.\n\n## Related Topics\n- [[Active Directory]]\n- [[Active Directory Domain Services]]\n- [[Group Policy]]\n- [[Domain Name]]\n- [[FQDN]]\n- [[OU]]\n- [[Kerberos]]"},{"id":"Terms and Concepts/Domain and Forest Functionality","title":"Domain and Forest Functionality","section":"Terms and Concepts","domain":"Networking","description":"Feature and capability levels within a Windows Active Directory environment, determined by the version of Windows Server running on domain controllers.","tags":["IT","IT/IAM","Level/Advanced"],"content":"# Domain and Forest Functionality\n\n> Feature and capability levels within a Windows Active Directory environment, determined by the version of Windows Server running on domain controllers.\n\n## Overview\nIn Windows [[Active Directory]], domain and forest functionality levels control which features are available across an organization's network. These levels are tied directly to the versions of Windows Server running on the domain controllers — the higher the version, the more advanced features become available.\n\nA **domain** represents a logical administrative boundary containing users, computers, and resources. **Forest functionality** extends across all domains in a forest (a collection of related domains sharing a schema and configuration). Raising these functional levels is a one-way operation that unlocks new capabilities but requires all domain controllers to be running at least that version of Windows Server.\n\nFunctional levels affect things like [[Password]] policy granularity, [[Replication]] improvements, [[Authentication]] mechanisms, and [[Kerberos]] support. Environments with legacy controllers may be locked to older functional levels until those controllers are retired or upgraded.\n\n## Key Concepts\n\n- **Domain Functional Level (DFL):** Controls features available within a single [[Active Directory]] domain. Determined by the lowest Windows Server version among that domain's controllers.\n- **Forest Functional Level (FFL):** Controls features across all domains in the forest. Must be at or below the lowest DFL in the forest.\n- **Domain Controller (DC):** A server that authenticates users and enforces policies. Its OS version sets the ceiling for functional levels.\n- **Trust Relationships:** Domains can establish trusts to allow cross-domain resource access. Forest functional levels affect available trust types.\n- **Raising Functional Levels:** Irreversible — upgrading requires all DCs to meet the minimum OS version for that level, and legacy DCs must be decommissioned first.\n\n## How It Works\nWhen an administrator raises a functional level, Active Directory evaluates whether all domain controllers meet the version requirement. Once raised, new features activate globally within that domain or forest. For example, raising to Windows Server 2016 level enables Privileged Access Management (PAM) features and improvements to [[Kerberos]] authentication.\n\n## Why It Matters\nUnderstanding functional levels is essential when planning [[Active Directory]] upgrades or deploying new features. Mismatched functional levels can prevent features from working or block the addition of new domain controllers. Knowing how to assess, plan, and raise functional levels is a core Active Directory administration skill covered in certifications like CompTIA Server+ and Microsoft's AZ/AD tracks.\n\n## Related Topics\n- [[Active Directory]]\n- [[Domains]]\n- [[Kerberos]]\n- [[Authentication]]\n- [[Active Directory Domain Services]]\n- [[Replication]]"},{"id":"Terms and Concepts/Domain Name","title":"Domain Name","section":"Terms and Concepts","domain":"Networking","description":"A human-readable label used to identify a website, server, or network resource on the internet, mapped to an underlying IP address through DNS.","tags":["IT","IT/Networking","Level/Foundational"],"content":"# Domain Name\n\n> A human-readable label used to identify a website, server, or network resource on the internet, mapped to an underlying IP address through DNS.\n\n## Overview\nA domain name is the memorable, text-based address humans use to navigate the internet. Instead of remembering `142.250.80.78`, you type `google.com`. Behind the scenes, [[DNS]] translates that name into the corresponding IP address.\n\nDomain names have a hierarchical structure, read from right to left. In `www.example.com`: `.com` is the top-level domain (TLD), `example` is the second-level domain (the registered name), and `www` is a subdomain. The complete address — like `mail.example.com` — is called a Fully Qualified Domain Name (FQDN) when it includes all levels including the implied trailing dot.\n\nDomain names must be registered with an ICANN-accredited registrar (GoDaddy, Namecheap, Google Domains, etc.) to ensure global uniqueness. Registration grants exclusive use of the domain for the registration period (typically 1–10 years).\n\n## Key Concepts\n\n- **TLD (Top-Level Domain):** The rightmost portion of a domain name — `.com`, `.org`, `.net`, `.edu`, `.gov`, or country codes like `.uk`, `.de`, `.ca`.\n- **Second-Level Domain:** The registered name immediately left of the TLD — `google` in `google.com`. This is the unique, registrable part.\n- **Subdomain:** Additional labels to the left of the second-level domain. `mail.google.com` and `maps.google.com` are subdomains of `google.com`. Organizations control their own subdomains.\n- **FQDN (Fully Qualified Domain Name):** The complete domain name that specifies the exact location in the DNS hierarchy — e.g., `www.example.com.` (with trailing dot). Used in DNS configuration.\n- **Domain Registration:** Paying a registrar to reserve a domain name for a period of time. The registrar updates the global DNS registry.\n- **[[DNS]] Resolution:** When a user types a domain name, DNS resolves it to an IP address. See [[DNS]] for the full process.\n- **Domain Expiration:** Failing to renew a domain allows it to expire and potentially be registered by someone else — a risk for organizations.\n\n## Why It Matters\nDomain names are the foundation of web presence and internet communication. IT professionals register and manage domain names for their organizations, configure DNS records for those domains, troubleshoot resolution issues, and must understand the relationship between domain names, DNS, and IP addresses. In [[Active Directory]] environments, the domain name also serves as the identity namespace for the Windows domain.\n\n## Related Topics\n- [[DNS]]\n- [[DNS Record]]\n- [[FQDN]]\n- [[IP Address]]\n- [[Domain]]\n- [[Web Server]]"},{"id":"Terms and Concepts/Domains","title":"Domains","section":"Terms and Concepts","domain":"Networking","description":"A logical grouping of computers, users, and resources in a network that share common administrative control and security policies.","tags":["IT","IT/IAM","IT/Networking","Level/Intermediate"],"content":"# Domains\n\n> A logical grouping of computers, users, and resources in a network that share common administrative control and security policies.\n\n## Overview\nIn IT, a domain is most commonly associated with Windows [[Active Directory]] — a centralized system where one or more domain controllers manage authentication, group policies, and access to shared resources. Every device and user account joined to the domain is subject to its policies, which makes domains the backbone of enterprise network administration.\n\nDomains use the [[DNS|Domain Name System]] for naming and lookup. Each domain has a name (like `company.local` or `company.com`) and a hierarchy — domains can be grouped into trees, and multiple trees form a forest. This structure enables organizations to delegate administration, apply policies granularly, and establish controlled access between different parts of the organization.\n\nBeyond Active Directory, \"domain\" also refers to internet domains (like `google.com`), but in an IT administration context it almost always means an AD domain.\n\n## Key Concepts\n\n- **Domain Controller (DC):** The server that runs Active Directory and handles authentication and policy enforcement for the domain.\n- **[[DNS]]:** Domains are identified by name; DNS resolves those names to IP addresses so devices can locate resources.\n- **Trust Relationships:** Domains can trust each other, allowing users in one domain to access resources in another — essential in multi-domain organizations.\n- **Domain Name Space / FQDN:** Every object in a domain has a Fully Qualified Domain Name (e.g., `pc01.sales.company.com`) that places it within the hierarchy.\n- **Trees and Forests:** Multiple domains sharing a namespace form a tree; multiple trees sharing a schema form a forest.\n- **Group Policy:** Administrators apply settings (security rules, software installs, desktop restrictions) to users and computers across the domain via Group Policy Objects (GPOs).\n\n## Why It Matters\nDomains are fundamental to enterprise IT. Nearly every organization of meaningful size uses an Active Directory domain to manage its users, computers, and security policies from a central point. As an IT professional, you'll join machines to domains, troubleshoot authentication issues, manage user accounts, and apply group policies — all domain operations. Understanding how domains work is essential for roles in help desk, sysadmin, and network administration.\n\n## Related Topics\n- [[Active Directory]]\n- [[Active Directory Domain Services]]\n- [[DNS]]\n- [[Authentication]]\n- [[Group Policy]]\n- [[Domain and Forest Functionality]]"},{"id":"Terms and Concepts/Drivers","title":"Drivers","section":"Terms and Concepts","domain":"Networking","description":"Software components that allow the operating system to communicate with and control specific hardware devices.","tags":["IT","IT/OS","IT/Hardware","Level/Foundational"],"content":"# Drivers\n\n> Software components that allow the operating system to communicate with and control specific hardware devices.\n\n## Overview\nA driver (device driver) is a small, specialized software program that acts as a translator between an operating system and a hardware component. Hardware devices — graphics cards, network adapters, printers, sound cards, USB controllers — all speak their own low-level language. The OS doesn't natively understand each device; drivers provide that translation layer.\n\nWhen you plug in a new printer or install a new graphics card, Windows searches for the appropriate driver — either locally, through Windows Update, or from the manufacturer's website. Without the correct driver, the device either won't work at all or won't work correctly.\n\nDrivers run in kernel mode, meaning they have deep access to the OS and hardware. A buggy or corrupted driver can cause system instability, performance issues, or [[BSOD]] errors.\n\n## Key Concepts\n\n- **Device Driver:** A driver specific to a hardware device — graphics driver for a GPU, NIC driver for a network adapter, printer driver for a printer.\n- **Kernel Mode vs. User Mode:** Most drivers run in kernel mode, with direct access to hardware and OS internals. This is why a faulty driver can crash the entire system.\n- **Driver Signing:** Windows requires drivers to be digitally signed by Microsoft to help prevent malicious or corrupt drivers from being installed. Unsigned drivers trigger warnings.\n- **INF File:** A text file that tells Windows how to install a driver — what files to copy, what registry entries to create.\n- **Driver Updates:** Keeping drivers current is important for security patches, bug fixes, and hardware compatibility. Especially critical for graphics and network adapter drivers.\n- **[[BSOD]] and Drivers:** A large percentage of Windows crash (BSOD) events are caused by faulty, outdated, or incompatible drivers. Reviewing recent driver installs is a key troubleshooting step.\n- **Device Manager:** The Windows tool for viewing, updating, rolling back, and disabling drivers. Yellow exclamation marks indicate device/driver problems.\n- **Driver Rollback:** Windows allows rolling back to the previously installed driver version — useful when a driver update causes problems.\n\n## Why It Matters\nDriver issues are among the most common hardware-related support tickets. IT professionals must know how to install, update, roll back, and troubleshoot drivers using Device Manager and manufacturer tools. They must also understand the security implications — driver vulnerabilities are sometimes exploited in attacks, and improperly signed drivers are a malware vector.\n\n## Related Topics\n- [[Hardware]]\n- [[Operating System]]\n- [[BSOD]]\n- [[Computer]]\n- [[GPU]]\n- [[NIC]]"},{"id":"Terms and Concepts/DxDiag","title":"DxDiag","section":"Terms and Concepts","domain":"Networking","description":"A built-in Windows utility that provides detailed system information about hardware, drivers, and DirectX components — used for troubleshooting display, audio, and multimedia issues.","tags":["IT","IT/Hardware","IT/OS","Level/Intermediate"],"content":"# DxDiag (DirectX Diagnostic Tool)\n\n> A built-in Windows utility that provides detailed system information about hardware, drivers, and DirectX components — used for troubleshooting display, audio, and multimedia issues.\n\n## Overview\nDxDiag (DirectX Diagnostic Tool) is a free diagnostic utility built into Windows. It collects and displays detailed information about your computer's hardware — particularly the components involved in graphics, sound, and input — along with their installed driver versions and any detected problems. It is especially useful for diagnosing issues with games, video playback, and multimedia applications that use DirectX.\n\nWhen users report graphics glitches, audio problems, or application crashes in DirectX-dependent software, DxDiag is one of the first tools support staff use to gather diagnostic information. Its \"Save All Information\" feature generates a text report that can be shared with support teams or software vendors.\n\n## Key Concepts\n\n- **DirectX:** Microsoft's collection of APIs for handling multimedia tasks — graphics (Direct3D), audio (DirectSound), input (DirectInput) — primarily for games and multimedia applications on Windows.\n- **Launching DxDiag:** Press `Win + R`, type `dxdiag`, press Enter. Or search \"dxdiag\" in the Start menu.\n- **System Tab:** Shows OS version, processor model, installed RAM, and system manufacturer. Useful for quickly capturing system specs.\n- **Display Tab:** Shows the GPU model, driver version, driver date, display memory (VRAM), and current resolution. Indicates if Direct3D/DirectDraw are available and flags driver issues.\n- **Sound Tab:** Lists audio devices, their drivers, and status. Useful for diagnosing audio hardware and driver problems.\n- **Input Tab:** Lists connected input devices (keyboards, mice, game controllers) and their driver status.\n- **Save All Information:** Exports all DxDiag data to a `.txt` file for sharing with support personnel or vendors.\n- **Driver Version and Date:** Particularly useful for identifying whether outdated graphics or audio drivers are causing issues.\n\n## Why It Matters\nDxDiag is a quick, zero-install tool that gives IT support professionals a snapshot of hardware and driver status in seconds. When users report gaming issues, display problems, or crashes, DxDiag output is a standard diagnostic artifact. It is also useful for quickly capturing system specifications (CPU, RAM, GPU, OS version) without needing to navigate through multiple system settings pages.\n\n## Related Topics\n- [[Drivers]]\n- [[GPU]]\n- [[Hardware]]\n- [[BSOD]]\n- [[Troubleshooting Process]]\n- [[Windows Operating Systems]]"},{"id":"Terms and Concepts/EAP","title":"EAP","section":"Terms and Concepts","domain":"Networking","description":"An authentication framework used in network access scenarios that supports multiple authentication methods, commonly used in Wi-Fi and VPN deployments.","tags":["IT","IT/Networking","IT/Security","Level/Intermediate"],"content":"# EAP (Extensible Authentication Protocol)\n\n> An authentication framework used in network access scenarios that supports multiple authentication methods, commonly used in Wi-Fi and VPN deployments.\n\n## Overview\nExtensible Authentication Protocol (EAP) is not a single authentication method but a framework that allows various authentication methods to be plugged in. This \"extensibility\" is the key — rather than hardcoding one way to authenticate, EAP supports dozens of methods (called EAP types), letting organizations choose the approach that fits their security requirements and infrastructure.\n\nEAP is most commonly encountered in 802.1X network access control for Wi-Fi and wired networks, and in VPN authentication. When a corporate laptop connects to the office Wi-Fi, EAP (typically EAP-TLS or PEAP) is the protocol performing authentication against the [[RADIUS]] server.\n\nEAP operates between three parties: the supplicant (the client device), the authenticator (the switch or wireless access point), and the authentication server (usually a [[RADIUS]] server).\n\n## Key Concepts\n\n- **Supplicant:** The device requesting network access (e.g., a laptop or phone).\n- **Authenticator:** The network access point — a wireless controller, switch, or VPN gateway — that relays authentication between the supplicant and the server.\n- **Authentication Server:** Usually a [[RADIUS]] server that validates credentials and makes the access decision.\n- **802.1X:** The IEEE standard that uses EAP for port-based network access control. When a device connects to an 802.1X-enabled switch or Wi-Fi, it must authenticate via EAP before being granted network access.\n- **EAP-TLS:** The most secure EAP type — uses client and server digital certificates for mutual authentication. Requires a PKI infrastructure. Common in enterprise Wi-Fi.\n- **PEAP (Protected EAP):** Wraps EAP in a TLS tunnel to protect credentials. Often used with MS-CHAPv2 (PEAP-MSCHAPv2) for username/password authentication over a secure tunnel. Common in corporate Wi-Fi.\n- **EAP-TTLS:** Similar to PEAP but supports a wider range of inner authentication methods.\n- **EAP vs. CHAP/PAP:** EAP is a more modern, flexible framework that supports far stronger authentication methods than the older [[CHAP]] and [[PAP]] protocols.\n\n## Why It Matters\nEAP is the authentication backbone of enterprise wireless and wired network access. IT professionals configuring 802.1X for secure Wi-Fi, setting up VPN authentication, or troubleshooting network access failures need to understand EAP types, how they interact with RADIUS, and how certificates are involved. It is tested on CompTIA Network+ and Security+, and is a daily reality in enterprise network administration.\n\n## Related Topics\n- [[RADIUS]]\n- [[Authentication]]\n- [[CHAP]]\n- [[PAP]]\n- [[VPN]]\n- [[Wi-Fi]]\n- [[Public Key Infrastructure]]"},{"id":"Terms and Concepts/Encapsulation","title":"Encapsulation","section":"Terms and Concepts","domain":"Networking","description":"The process of wrapping data with protocol-specific headers (and sometimes trailers) as it passes down through the layers of a network protocol stack, preparing it for transmission.","tags":["IT","IT/Networking","Level/Intermediate"],"content":"# Encapsulation\n\n> The process of wrapping data with protocol-specific headers (and sometimes trailers) as it passes down through the layers of a network protocol stack, preparing it for transmission.\n\n## Overview\nEncapsulation is a fundamental concept in both networking and object-oriented programming. In networking, it describes what happens to data as it moves down through the layers of the [[OSI Model]] or [[TCP IP Model]] — each layer wraps the data from the layer above with its own header (and sometimes trailer), adding the control information that layer needs to do its job.\n\nWhen you send an email, your data starts at the Application Layer as an email message. As it moves down the stack, the Transport Layer wraps it in a TCP segment (adding port numbers), the Network Layer wraps that in an IP packet (adding IP addresses), and the Data Link Layer wraps it in an Ethernet frame (adding MAC addresses). At the receiving end, each layer strips its own header — this is called decapsulation — until the original email message is recovered.\n\n## Key Concepts\n\n- **Headers:** Control information added at the front of data at each layer. Contains source/destination addresses, protocol type, sequence numbers, and other metadata needed by that layer.\n- **Trailers:** Some layers (like the Data Link Layer) add a trailer after the data — typically for error detection (CRC).\n- **PDU (Protocol Data Unit):** What the data is called at each layer. Application data → segment (Transport) → packet (Network) → frame (Data Link) → bits (Physical).\n- **Decapsulation:** The reverse process — each layer at the receiving end removes its header before passing data up to the next layer.\n- **Layered Model:** Encapsulation enables the layered architecture of networking — each layer operates independently and only understands its own header. The layers above and below are abstracted away.\n- **Tunneling:** A form of encapsulation used in [[VPN]] and [[GRE]] — one protocol is wrapped inside another. An IP packet might be encapsulated inside another IP packet to create an encrypted tunnel.\n- **OOP Encapsulation:** In programming (like [[C++]] or Java), encapsulation means hiding an object's internal data and exposing only necessary methods — keeping internal workings private. A related but distinct concept from network encapsulation.\n\n## How It Works (OSI Example)\n\n| Layer | PDU | What's Added |\n|-------|-----|-------------|\n| 7 – Application | Data | — |\n| 4 – Transport | Segment | TCP/UDP header (ports, seq numbers) |\n| 3 – Network | Packet | IP header (source/dest IP) |\n| 2 – Data Link | Frame | MAC addresses, CRC trailer |\n| 1 – Physical | Bits | Electrical/optical signal |\n\n## Why It Matters\nEncapsulation is the mechanism that makes the layered networking model work. Understanding it helps IT professionals and network engineers troubleshoot connectivity issues at the right layer — is the problem a MAC address issue (Layer 2)? An IP routing issue (Layer 3)? A port configuration issue (Layer 4)? Wireshark shows encapsulated packets, and understanding what each layer contains is essential for interpreting captures.\n\n## Related Topics\n- [[OSI Model]]\n- [[TCP IP Model]]\n- [[Data Link Layer]]\n- [[Network Layer]]\n- [[Transport Layer]]\n- [[VPN]]\n- [[GRE]]"},{"id":"Terms and Concepts/Encryption","title":"Encryption","section":"Terms and Concepts","domain":"Networking","description":"The process of converting readable data (plaintext) into an unreadable format (ciphertext) using a mathematical algorithm and key, so that only authorized parties with the correct key can decrypt and read it.","tags":["IT","IT/Security","Level/Foundational"],"content":"# Encryption\n\n> The process of converting readable data (plaintext) into an unreadable format (ciphertext) using a mathematical algorithm and key, so that only authorized parties with the correct key can decrypt and read it.\n\n## Overview\nEncryption is the most fundamental technical control for protecting data confidentiality. When data is encrypted, anyone who intercepts it — on the network, on a stolen hard drive, in a cloud storage breach — sees only meaningless ciphertext. Without the decryption key, the data is useless to an attacker.\n\nEncryption is used everywhere: HTTPS encrypts web traffic, encrypted email protects sensitive communications, BitLocker encrypts hard drives, and cloud storage encrypts data at rest. It is the primary mechanism for implementing the Confidentiality pillar of the [[CIA Triad]].\n\nThe two main categories are symmetric encryption (one key for both encryption and decryption) and asymmetric encryption (two mathematically related keys — a public key for encryption and a private key for decryption). Modern secure communications typically use both — asymmetric encryption to exchange a symmetric key, then symmetric encryption for the bulk data transfer.\n\n## Key Concepts\n\n- **Plaintext:** The original, readable data before encryption.\n- **Ciphertext:** The scrambled, unreadable output of encryption.\n- **Key:** A string of bits used by the encryption algorithm to transform plaintext into ciphertext (and back). Key length affects strength — longer keys are harder to break.\n- **Symmetric Encryption:** The same key encrypts and decrypts. Fast and efficient for large data. Key challenge: securely sharing the key. Examples: AES-256, AES-128.\n- **Asymmetric Encryption:** Uses a key pair — a public key (shareable with anyone) for encryption, a private key (kept secret) for decryption. Used for key exchange and digital signatures. Examples: RSA, ECC.\n- **AES (Advanced Encryption Standard):** The current gold standard for symmetric encryption. AES-256 is used in most enterprise security products.\n- **[[TLS]] (Transport Layer Security):** The protocol that encrypts data in transit — what makes HTTPS secure. Uses a combination of asymmetric and symmetric encryption.\n- **[[Hashing]]:** Related but different from encryption — a one-way transformation that can't be reversed. Used for password storage and data integrity verification.\n- **End-to-End Encryption (E2EE):** Encryption where only the sender and recipient can decrypt — even the service provider cannot read the data. Used in Signal, WhatsApp.\n- **Encryption at Rest vs. In Transit:** Data should be encrypted both when stored (at rest) and when moving over a network (in transit).\n\n## Why It Matters\nEncryption is the backbone of data security. Without it, any intercepted network traffic reveals passwords and data, any stolen drive exposes all its contents, and any cloud breach compromises customer information. IT professionals configure encryption for Wi-Fi (WPA3), disk encryption (BitLocker, FileVault), TLS certificates, email (S/MIME), and more. Understanding encryption concepts is tested on every security certification.\n\n## Related Topics\n- [[TLS]]\n- [[SSL]]\n- [[Hashing]]\n- [[Public Key Infrastructure]]\n- [[End-to-End Encryption]]\n- [[CIA Triad]]\n- [[Confidentiality]]"},{"id":"Terms and Concepts/End of Life","title":"End of Life","section":"Terms and Concepts","domain":"Security","description":"The point at which a vendor stops providing updates, security patches, and technical support for a software product or hardware device.","tags":["IT","IT/OS","Level/Foundational"],"content":"# End of Life (EOL)\n\n> The point at which a vendor stops providing updates, security patches, and technical support for a software product or hardware device.\n\n## Overview\nEnd of Life (EOL) marks the final phase in a product's lifecycle — when the manufacturer officially stops supporting it. For software, this means no more security patches, bug fixes, or feature updates. For hardware, it means no more driver updates or manufacturer support.\n\nEOL is a significant security event. Once a product reaches EOL, newly discovered vulnerabilities will never be patched — leaving systems permanently exposed to any exploits targeting those vulnerabilities. Running EOL software in a production environment is a risk management problem, a compliance issue, and a security liability.\n\nWell-known examples: Windows XP (EOL 2014), Windows 7 (EOL 2020), PHP 7.4 (EOL 2022). Organizations that failed to migrate away from Windows XP found themselves running unpatched systems during the WannaCry ransomware outbreak in 2017 — which specifically exploited an unpatched Windows vulnerability.\n\n## Key Concepts\n\n- **EOL vs. End of Support:** Some vendors distinguish between \"End of Mainstream Support\" (no new features) and \"End of Extended Support\" (no security patches). The extended support date is the critical security cutoff.\n- **Windows Support Lifecycle:** Microsoft typically provides 5 years of mainstream support + 5 years of extended support for Windows Server and desktop OS versions. These dates are published at microsoft.com/lifecycle.\n- **Security Patches:** Once a product is EOL, no security patches will be released for newly discovered vulnerabilities — even critical ones.\n- **Compliance Implications:** Many regulatory frameworks ([[PCI DSS]], [[HIPAA]], NIST) require running supported software. Using EOL software may constitute a compliance violation.\n- **[[Lifecycle Management]]:** The practice of proactively tracking software and hardware lifecycle dates to plan upgrades before EOL is reached.\n- **Migration Planning:** Transitioning away from EOL products requires planning — testing compatibility, budgeting for licenses or hardware, training users, and scheduling deployments.\n\n## Why It Matters\nEOL management is a core IT responsibility. Allowing EOL software or hardware to remain in production creates known, permanent security vulnerabilities that attackers actively target. IT professionals must track lifecycle dates, advocate for timely upgrades, and execute migrations before EOL dates arrive. This is particularly important for operating systems, browsers, servers, network equipment, and security tools.\n\n## Related Topics\n- [[Patch mangement]]\n- [[Lifecycle Management]]\n- [[Software]]\n- [[Operating System]]\n- [[Windows Operating Systems]]\n- [[Security Assessments]]"},{"id":"Terms and Concepts/End-to-End Encryption","title":"End-to-End Encryption","section":"Terms and Concepts","domain":"Security","description":"A communication security method where data is encrypted on the sender's device and can only be decrypted by the intended recipient — no intermediary, including the service provider, can read the content.","tags":["IT","IT/Security","Level/Intermediate"],"content":"# End-to-End Encryption (E2EE)\n\n> A communication security method where data is encrypted on the sender's device and can only be decrypted by the intended recipient — no intermediary, including the service provider, can read the content.\n\n## Overview\nEnd-to-End Encryption (E2EE) is the strongest form of communication privacy — it ensures that even if a message travels through third-party servers (as most internet communications do), those servers see only encrypted ciphertext they cannot read. Only the sender and recipient hold the keys.\n\nThis is distinct from transport encryption (like [[TLS]]), where data is encrypted between you and a server, but the server can read it. In a standard HTTPS connection to Gmail, Google can read your emails. With E2EE, even the service provider is mathematically locked out.\n\nE2EE is used in messaging apps (Signal, WhatsApp, iMessage), secure file sharing services, and increasingly in enterprise communications. It is particularly important for protecting sensitive communications from surveillance, data breaches, and insider threats at the provider level.\n\n## Key Concepts\n\n- **Key Generation:** Each user generates a cryptographic key pair — a public key (shared openly) and a private key (kept on their device, never shared).\n- **Encryption:** The sender encrypts the message using the recipient's public key.\n- **Decryption:** Only the recipient's private key (which never leaves their device) can decrypt the message.\n- **No Provider Access:** Because the provider never has access to private keys, they cannot read messages — even if compelled by law enforcement or breached by attackers.\n- **Signal Protocol:** The gold standard E2EE protocol used by Signal, WhatsApp, and others. Combines asymmetric and symmetric key exchange for forward secrecy.\n- **Forward Secrecy:** A property where session keys are derived fresh for each session — even if a long-term key is compromised later, past messages remain secure.\n- **E2EE vs. TLS:** TLS encrypts the connection between client and server (the wire). E2EE encrypts the content so even the server can't read it. Both can coexist — TLS protects the transmission of already-E2EE-encrypted data.\n- **Trade-offs:** E2EE prevents even providers from scanning for malware or illegal content — a policy tension between privacy and safety.\n\n## Why It Matters\nE2EE is the highest standard of communication privacy. IT and security professionals encounter it when evaluating secure messaging tools for organizations, configuring secure file sharing, or explaining privacy trade-offs to stakeholders. Understanding how E2EE works — especially the key exchange mechanics — also deepens understanding of [[Public Key Infrastructure]] and asymmetric [[Encryption]] more broadly.\n\n## Related Topics\n- [[Encryption]]\n- [[Public Key Infrastructure]]\n- [[TLS]]\n- [[Private Key]]\n- [[Public Key]]\n- [[Confidentiality]]\n- [[CIA Triad]]"},{"id":"Terms and Concepts/Ethernet","title":"Ethernet","section":"Terms and Concepts","domain":"Networking","description":"The dominant wired networking technology for local area networks, using cable connections and MAC addresses to transmit data frames between devices.","tags":["IT","IT/Networking","IT/Hardware","Level/Foundational"],"content":"# Ethernet\n\n> The dominant wired networking technology for local area networks, using cable connections and MAC addresses to transmit data frames between devices.\n\n## Overview\nEthernet is the standard technology for wired local area networking. Defined by the IEEE 802.3 standard, it specifies how data is formatted into frames, how devices share the physical medium, and how errors are detected. Since its development in the 1970s at Xerox PARC, Ethernet has evolved from 10 Mbps over coaxial cable to multi-gigabit speeds over fiber-optic cable — but the core principles remain the same.\n\nModern Ethernet primarily runs over unshielded twisted pair (UTP) cable with RJ-45 connectors, or fiber-optic cable for longer distances and higher speeds. Data center and enterprise backbones increasingly use 10/40/100 Gbps Ethernet over fiber. Ethernet switches connect multiple devices and forward frames based on MAC addresses.\n\nEthernet is the foundation of nearly all wired office and data center networks — from the cable connecting a workstation to a wall jack, to the high-speed links connecting data center switches.\n\n## Key Concepts\n\n- **Frames:** The fundamental unit of Ethernet data — a structured packet containing source and destination [[MAC]] addresses, an EtherType field (identifying the Layer 3 protocol), the payload, and a CRC trailer for error detection.\n- **[[MAC]] Address:** A 48-bit hardware identifier assigned to each network interface. Ethernet uses MACs to deliver frames within a local network segment.\n- **[[Switch]]:** The device that forwards Ethernet frames between connected devices, building a MAC address table to make intelligent forwarding decisions.\n- **CSMA/CD:** Carrier Sense Multiple Access with Collision Detection — the access control mechanism for older shared Ethernet. Devices listen before transmitting and detect collisions. Modern switched Ethernet uses full-duplex and has eliminated collisions.\n- **Cable Categories:** Cat5e (1 Gbps), Cat6 (10 Gbps short distance), Cat6a (10 Gbps up to 100m), Cat8 (40 Gbps data center). Fiber optic for longer runs.\n- **Speed Standards:** 10BASE-T (10 Mbps), 100BASE-TX (Fast Ethernet, 100 Mbps), 1000BASE-T (Gigabit Ethernet, 1 Gbps), 10GBASE-T (10 Gbps).\n- **PoE (Power over Ethernet):** Delivers electrical power along with data through Ethernet cable — used for VoIP phones, wireless access points, cameras, and IoT devices.\n\n## Why It Matters\nEthernet is the physical foundation of most enterprise networks. IT professionals run cables, configure switches, troubleshoot connectivity, and interpret Ethernet frames in packet captures daily. Understanding Ethernet cabling standards, speeds, duplex settings, and switching is fundamental for CompTIA A+ and Network+ certifications and for any networking role.\n\n## Related Topics\n- [[MAC]]\n- [[Switch]]\n- [[Data Link Layer]]\n- [[ARP]]\n- [[VLAN]]\n- [[LAN]]\n- [[NIC]]"},{"id":"Terms and Concepts/Ethical Hacking","title":"Ethical Hacking","section":"Terms and Concepts","domain":"Networking","description":"The authorized practice of testing computer systems, networks, and applications using the same techniques as malicious hackers, with the goal of identifying and reporting security vulnerabilities before attackers can exploit them.","tags":["IT","IT/Security","Level/Advanced"],"content":"# Ethical Hacking\n\n> The authorized practice of testing computer systems, networks, and applications using the same techniques as malicious hackers, with the goal of identifying and reporting security vulnerabilities before attackers can exploit them.\n\n## Overview\nEthical hacking (also called penetration testing or pen testing) is a formalized security assessment in which a skilled professional — with explicit permission from the system owner — attempts to breach defenses the same way an attacker would. The goal is to discover vulnerabilities before malicious actors do, and to provide actionable recommendations for remediation.\n\nEthical hackers are sometimes called \"white hat\" hackers, in contrast to malicious \"black hat\" hackers. They operate within a carefully defined scope, follow legal and ethical rules, and report every finding to the organization.\n\nMajor certifications in this field include Certified Ethical Hacker (CEH), Offensive Security Certified Professional (OSCP), and CompTIA PenTest+.\n\n## Key Concepts\n\n- **Scope and Rules of Engagement:** Every pen test begins with a formal agreement defining which systems can be tested, what methods are permitted, timing, and notification requirements. Testing outside scope is illegal.\n- **Black Box / White Box / Gray Box:** Black box = no prior knowledge of the target (simulates an outsider). White box = full knowledge (simulates an insider or code reviewer). Gray box = partial knowledge (most common).\n- **Reconnaissance:** Gathering information about the target using OSINT, DNS enumeration, network scanning, and other passive/active techniques.\n- **Vulnerability Scanning:** Using tools like [[NMAP]], Nessus, or OpenVAS to identify open ports, services, and known vulnerabilities.\n- **Exploitation:** Attempting to exploit discovered vulnerabilities to gain unauthorized access. Common tools: [[Metasploit]].\n- **Post-Exploitation:** After gaining access, assessing what an attacker could do — moving laterally, escalating privileges, accessing data.\n- **Reporting:** Documenting all findings with severity ratings, evidence, and remediation recommendations. The report is the deliverable.\n- **Bug Bounty Programs:** Companies like Microsoft, Google, and Apple pay security researchers who responsibly disclose vulnerabilities — a form of crowdsourced ethical hacking.\n\n## Why It Matters\nEthical hacking provides organizations with an attacker's perspective on their defenses — which is impossible to get any other way. A pen test reveals vulnerabilities that automated scanners miss, tests whether security controls actually work, and helps prioritize remediation. IT and security professionals must understand ethical hacking principles for security certifications and for evaluating or conducting security assessments.\n\n## Related Topics\n- [[Security Assessments]]\n- [[NMAP]]\n- [[Metasploit]]\n- [[Exploited Vulnerablties]]\n- [[CVE]]\n- [[CyberOps]]\n- [[Social Engineering]]"},{"id":"Terms and Concepts/Exploited Vulnerablties","title":"Exploited Vulnerablties","section":"Terms and Concepts","domain":"Security","description":"Security flaws in software, hardware, or systems that attackers actively take advantage of to gain unauthorized access, cause damage, or steal data.","tags":["IT","IT/Security","Level/Intermediate"],"content":"# Exploited Vulnerabilities\n\n> Security flaws in software, hardware, or systems that attackers actively take advantage of to gain unauthorized access, cause damage, or steal data.\n\n## Overview\nA vulnerability is a weakness — a bug, misconfiguration, or design flaw — in a system. An exploited vulnerability is one that has been discovered and actively used by attackers to cause harm. Not all vulnerabilities are equally dangerous: the risk depends on whether an exploit exists, how widely it is used, and what an attacker can achieve with it.\n\nCISA (Cybersecurity and Infrastructure Security Agency) maintains the Known Exploited Vulnerabilities (KEV) catalog — a list of vulnerabilities that have been confirmed as actively exploited in the wild. This catalog is a critical resource for IT and security teams prioritizing patching.\n\nVulnerabilities are identified by [[CVE]] numbers and scored using CVSS (Common Vulnerability Scoring System). Critical vulnerabilities (CVSS 9.0–10.0) that are actively exploited represent the highest-priority patching targets.\n\n## Key Concepts\n\n- **[[CVE]] (Common Vulnerabilities and Exposures):** The standardized identifier for a specific vulnerability. When a vulnerability is exploited, its CVE number becomes the common reference.\n- **CVSS Score:** A 0–10 severity rating. Scores of 9.0+ are Critical; 7.0–8.9 are High. Exploited vulnerabilities with high CVSS scores warrant immediate response.\n- **[[Zero Day]]:** A vulnerability that is exploited before the vendor knows about it or has issued a patch. No defense is available at the time of exploitation.\n- **Exploit:** The code, technique, or tool that takes advantage of a vulnerability to achieve a specific unauthorized action (code execution, privilege escalation, data exfiltration).\n- **[[Patch mangement|Patch Management]]:** The practice of applying security patches to close vulnerabilities before they can be exploited.\n- **Attack Surface:** The sum of all points where an attacker could attempt to exploit a vulnerability. Reducing the attack surface (disabling unnecessary services, removing unused software) reduces risk.\n- **Real-World Examples:**\n  - EternalBlue (CVE-2017-0144): SMBv1 exploit used in WannaCry ransomware\n  - Log4Shell (CVE-2021-44228): Remote code execution in Log4j, affecting millions of systems\n  - ProxyLogon (CVE-2021-26855): Microsoft Exchange Server compromise\n\n## Why It Matters\nExploited vulnerabilities are the mechanism behind most successful cyberattacks. Understanding what makes a vulnerability exploitable, how quickly organizations must respond after public disclosure, and how to prioritize patching based on exploitation status and severity is a core competency for any security or IT operations role. CISA's KEV catalog and CVSS scores are practical tools used daily in vulnerability management programs.\n\n## Related Topics\n- [[CVE]]\n- [[CWE]]\n- [[Zero Day]]\n- [[Patch mangement]]\n- [[Security Assessments]]\n- [[Ethical Hacking]]\n- [[Malware]]"},{"id":"Terms and Concepts/FAT32","title":"FAT32","section":"Terms and Concepts","domain":"Hardware","description":"A legacy file system widely used on USB drives and removable media due to its cross-platform compatibility, though limited to 4GB maximum file size.","tags":["IT","IT/OS","Level/Intermediate"],"content":"# FAT32 (File Allocation Table 32)\n\n> A legacy file system widely used on USB drives and removable media due to its cross-platform compatibility, though limited to 4GB maximum file size.\n\n## Overview\nFAT32 (File Allocation Table 32) is a file system developed by Microsoft that has been in use since Windows 95 OSR2 (1996). While it's been largely superseded by [[NTFS]] on Windows computers and [[APFS]] on Apple devices, FAT32 remains the go-to file system for USB drives, SD cards, and removable storage because virtually every device and operating system can read and write it.\n\nFAT32 works by maintaining a File Allocation Table — a map tracking which clusters (storage units) on the drive are used, free, or part of which files. \"32\" refers to the 32-bit cluster addressing, which enables larger volumes than the earlier FAT16.\n\nThe critical limitation of FAT32 is the **4GB maximum file size per file**. A video file larger than 4GB cannot be stored on a FAT32 drive, regardless of available space. For this reason, large external drives often use exFAT (which lifts this limit while maintaining compatibility) or [[NTFS]].\n\n## Key Concepts\n\n- **Maximum File Size: 4GB** — the most important limitation. Cannot store any single file larger than 4,294,967,295 bytes (~4GB).\n- **Maximum Volume Size:** Up to 2TB (theoretical), though Windows formats FAT32 volumes only up to 32GB. Linux tools can format larger volumes.\n- **Cross-Platform Compatibility:** FAT32 is readable/writable by Windows, macOS, Linux, game consoles (PS4, Xbox), cameras, and virtually every device with USB support.\n- **No File Permissions:** Unlike [[NTFS]], FAT32 has no concept of file ownership or permissions — every user has full access to every file.\n- **No Journaling:** FAT32 doesn't track incomplete operations, making it more prone to corruption on improper removal (though modern drives handle this better).\n- **exFAT:** Microsoft's modern replacement for FAT32 on removable media. Same cross-platform compatibility but no 4GB file size limit. Supported natively by all modern OSes.\n- **When to Use FAT32:** USB drives shared between devices (cameras, TVs, game consoles, older systems) where exFAT may not be supported.\n\n## Why It Matters\nIT professionals regularly work with FAT32 when formatting USB drives, troubleshooting file transfer failures (often caused by the 4GB limit), and preparing bootable media. Understanding which file system to use for what purpose — FAT32 vs. exFAT vs. NTFS — is practical knowledge for both helpdesk support and system administration.\n\n## Related Topics\n- [[File System]]\n- [[NTFS]]\n- [[APFS]]\n- [[Storage]]\n- [[USB]]\n- [[Operating System]]"},{"id":"Terms and Concepts/FCRA","title":"FCRA","section":"Terms and Concepts","domain":"Security","description":"A U.S. federal law that regulates the collection, use, and sharing of consumer credit information by credit reporting agencies and those who access credit data.","tags":["IT","IT/Compliance","Level/Intermediate"],"content":"# FCRA (Fair Credit Reporting Act)\n\n> A U.S. federal law that regulates the collection, use, and sharing of consumer credit information by credit reporting agencies and those who access credit data.\n\n## Overview\nThe Fair Credit Reporting Act (FCRA) was enacted in 1970 and governs how consumer credit information is collected, used, and shared. It applies to consumer reporting agencies (CRAs) — like Equifax, Experian, and TransUnion — as well as anyone who accesses that information for employment screening, credit decisions, insurance, or other permissible purposes.\n\nFrom an IT perspective, FCRA is relevant when organizations access credit reports as part of background checks, when building systems that use or store credit data, and when responding to consumer requests for their information. Data security requirements under FCRA mean organizations must protect any credit information they hold.\n\n## Key Concepts\n\n- **Consumer Reporting Agency (CRA):** An organization that collects and sells consumer credit data. The major three are Equifax, Experian, and TransUnion.\n- **Permissible Purpose:** The FCRA limits who can access a credit report and why — creditors evaluating applications, employers (with consent), landlords (with consent), and certain government agencies.\n- **Free Annual Credit Report:** Consumers are entitled to one free credit report per year from each major CRA at AnnualCreditReport.com.\n- **Dispute Rights:** Consumers can dispute inaccurate information. The CRA must investigate and correct or remove inaccurate data.\n- **Adverse Action Notice:** If a business denies credit, employment, or housing based on a credit report, they must notify the consumer and identify the CRA that provided the report.\n- **Fraud Alerts and Credit Freezes:** The FCRA gives consumers the right to place fraud alerts or security freezes on their credit files to prevent new accounts from being opened in their name.\n- **Data Security:** Organizations handling credit information must implement reasonable security measures to protect it from unauthorized access — FCRA requires responsible data stewardship.\n\n## Why It Matters\nIT professionals working in HR systems, background check platforms, financial services applications, or any system that processes credit data must ensure those systems comply with FCRA requirements for data accuracy, access control, and security. Non-compliance can result in civil penalties and lawsuits. FCRA also appears in the context of [[PII]] protection and [[Data Privacy Laws]] education.\n\n## Related Topics\n- [[Data Privacy Laws]]\n- [[PII]]\n- [[GDPR]]\n- [[Confidentiality]]\n- [[Data Breach]]"},{"id":"Terms and Concepts/File","title":"File","section":"Terms and Concepts","domain":"Hardware","description":"A named unit of data stored on a computer's storage system, containing information in a specific format that can be created, opened, edited, moved, copied, or deleted.","tags":["IT","IT/OS","Level/Foundational"],"content":"# File\n\n> A named unit of data stored on a computer's storage system, containing information in a specific format that can be created, opened, edited, moved, copied, or deleted.\n\n## Overview\nA file is the fundamental unit of data storage in computing. Whether it's a document, image, video, program, or configuration setting — if it's stored on a computer, it lives in a file. Every file has a name (including a [[File Extension]] indicating its type), a location in the [[File System]], a size, and metadata like creation and modification dates.\n\nFiles are organized within [[Directory|directories]] (folders) in a hierarchical tree structure. The operating system's [[File System]] determines how files are physically stored on the storage device and how they're accessed.\n\nUnderstanding what files are, how they're named, what formats they use, and how to manage them is foundational to all IT work.\n\n## Key Concepts\n\n- **File Name:** The human-readable label for a file. Operating systems have rules about allowed characters and maximum length. Windows is case-insensitive; Linux/Unix are case-sensitive.\n- **[[File Extension]]:** The suffix after the last dot in a filename (`.pdf`, `.exe`, `.txt`) that identifies the file type and tells the OS which application to use to open it.\n- **File Format:** The internal structure of a file — how its data is organized. A `.jpg` is encoded differently than a `.png` even if both contain images.\n- **File Size:** Measured in bytes (KB, MB, GB, TB). Affects storage requirements, transfer times, and sometimes processing time.\n- **Metadata:** Information about the file stored separately from its content — creation date, modification date, owner, permissions, and file attributes.\n- **File Path:** The address of a file in the directory tree. Absolute path: `C:\\Users\\Ryan\\Documents\\report.docx`. Relative path: `Documents\\report.docx` (relative to current location).\n- **Hidden Files:** Files that are not shown in standard directory listings. On Windows, hidden via file attributes. On Linux/Unix, files beginning with `.` are hidden.\n- **File [[Integrity]]:** Verifying a file hasn't been modified — done by comparing [[Hashing|hash]] values (SHA-256, MD5).\n\n## Why It Matters\nFiles are the primary way data is stored, transmitted, and processed in IT. IT professionals work with files constantly — deploying scripts, configuring software, managing user documents, analyzing logs, and responding to incidents. Understanding file types, paths, permissions, and format compatibility is essential for every IT role.\n\n## Related Topics\n- [[File Extension]]\n- [[File System]]\n- [[Directory]]\n- [[File Permission]]\n- [[File Management]]\n- [[Hashing]]"},{"id":"Terms and Concepts/File Extension","title":"File Extension","section":"Terms and Concepts","domain":"Security","description":"The suffix at the end of a filename (after the final dot) that indicates the file's format and tells the operating system which application should open it.","tags":["IT","IT/OS","Level/Foundational"],"content":"# File Extension\n\n> The suffix at the end of a filename (after the final dot) that indicates the file's format and tells the operating system which application should open it.\n\n## Overview\nA file extension is a short string of characters (typically 2–5 characters) appended after the final dot in a filename — for example, `.txt`, `.pdf`, `.exe`, `.xlsx`. It signals to the operating system and users what type of content the file contains and which application is capable of opening it.\n\nOperating systems use file extensions to determine default program associations — when you double-click a `.docx` file, Windows knows to open it in Word because of the extension. Users can override this by changing the association, and can even change the extension manually — though this doesn't change the actual file format, only the label.\n\nFrom a security perspective, file extensions are also a risk vector — malware is often disguised by giving it an innocent-looking extension (e.g., `invoice.pdf.exe`), which may look like a PDF but is actually an executable.\n\n## Key Concepts\n\n- **Operating System Association:** The OS maintains a registry of which application handles each extension. Users and admins can modify these associations.\n- **Hiding Extensions:** Windows hides known file extensions by default — a dangerous setting that makes it easier to disguise malicious files. IT professionals typically enable \"Show file extensions\" in Folder Options.\n- **MIME Types:** On the web, file types are identified by MIME types (e.g., `application/pdf`) rather than extensions. Browsers use MIME types to handle file downloads correctly.\n\n## Common File Extensions\n\n| Extension | Type |\n|-----------|------|\n| `.txt` | Plain text |\n| `.docx` | Microsoft Word document |\n| `.pdf` | Portable Document Format |\n| `.xlsx` | Microsoft Excel spreadsheet |\n| `.pptx` | Microsoft PowerPoint presentation |\n| `.jpg`, `.png`, `.gif` | Image formats |\n| `.mp3`, `.wav` | Audio formats |\n| `.mp4`, `.avi`, `.mov` | Video formats |\n| `.zip`, `.rar`, `.7z` | Compressed archive |\n| `.exe` | Windows executable |\n| `.bat`, `.ps1` | Script files (Windows Batch, PowerShell) |\n| `.sh` | Shell script (Linux/macOS) |\n| `.html`, `.css`, `.js` | Web files |\n| `.csv` | Comma-separated values |\n| `.iso` | Disk image |\n| `.log` | Log file |\n\n## Why It Matters\nIT professionals use file extensions constantly — identifying file types, configuring application associations, troubleshooting \"file won't open\" issues, and recognizing potentially malicious files. The security implication (hidden extensions hiding `.exe` files disguised as PDFs) is a real-world threat that every IT professional must be aware of and guard against.\n\n## Related Topics\n- [[File]]\n- [[File System]]\n- [[File Management]]\n- [[Operating System]]\n- [[Malware]]"},{"id":"Terms and Concepts/File Management","title":"File Management","section":"Terms and Concepts","domain":"Networking","description":"The practice of organizing, storing, naming, and maintaining files and folders on a computer or network storage system in a way that makes data easy to find, protect, and manage.","tags":["IT","IT/OS","Level/Foundational"],"content":"# File Management\n\n> The practice of organizing, storing, naming, and maintaining files and folders on a computer or network storage system in a way that makes data easy to find, protect, and manage.\n\n## Overview\nFile management encompasses everything involved in keeping digital files organized and accessible. This includes creating logical folder structures, using clear naming conventions, applying permissions, performing regular backups, and cleaning up outdated files. Poor file management leads to cluttered drives, duplicate files, difficulty finding information, and increased risk of data loss.\n\nIn enterprise environments, file management extends beyond individual computers to shared network drives, file servers, [[NAS]] devices, [[SharePoint]], and cloud storage. IT professionals are responsible for configuring file shares, setting permissions, managing storage quotas, and ensuring backup coverage for critical data.\n\n## Key Concepts\n\n- **Folder Structure:** A logical hierarchy of [[Directory|directories]] organizing files by project, department, year, or other categories. A well-designed structure makes files findable without search.\n- **Naming Conventions:** Standardized file naming rules that make files self-describing and sortable. Example: `2024-01-15_Project-Report_v2.docx`.\n- **File Permissions:** Controls who can read, write, or execute files. In Windows, managed via [[NTFS]] permissions. In Linux, via Unix permissions (`chmod`).\n- **File Sharing:** Making files accessible to multiple users via network shares ([[SMB]]/[[CIFS]]), cloud storage, or collaboration platforms.\n- **[[Backups]]:** Regular copies of important files to protect against accidental deletion, hardware failure, or ransomware.\n- **Storage Quotas:** Limits on how much storage each user or group can use — prevents any one user from filling shared storage.\n- **Archiving:** Moving infrequently accessed files to cheaper storage ([[Cold Storage]]) while keeping them available if needed.\n- **Version Control:** Systems like Git track changes to files over time, allowing rollback to previous versions. Critical for code; increasingly used for documents.\n- **Metadata:** Information about files beyond their content — creation date, author, size, last modified date. Useful for searching and organizing.\n\n## Why It Matters\nEffective file management is a foundational IT skill. Helpdesk technicians configure file shares and fix permission issues. Sysadmins manage storage capacity and backup systems. Security professionals audit file permissions to enforce least privilege. Poor file management creates operational problems (can't find files), security risks (excessive permissions, no backups), and compliance issues (required records not retained or not properly protected).\n\n## Related Topics\n- [[File System]]\n- [[File Permission]]\n- [[Directory]]\n- [[NTFS]]\n- [[Backups]]\n- [[Sharing]]\n- [[Cloud Storage]]"},{"id":"Terms and Concepts/File Permission","title":"File Permission","section":"Terms and Concepts","domain":"Security","description":"Access control rules that determine what actions (read, write, execute) specific users or groups can perform on a file or directory.","tags":["IT","IT/OS","IT/Security","Level/Intermediate"],"content":"# File Permission\n\n> Access control rules that determine what actions (read, write, execute) specific users or groups can perform on a file or directory.\n\n## Overview\nFile permissions are a fundamental security mechanism built into every modern operating system. They enforce who can do what with each file or folder — preventing unauthorized users from reading sensitive data, modifying configuration files, or running scripts they shouldn't have access to.\n\nPermissions are the technical implementation of the [[Principle of least Privilege]] at the file level — each user should have only the access they need to do their job. Understanding file permissions is essential for both security (preventing unauthorized access) and administration (troubleshooting access denied errors).\n\n## Key Concepts\n\n**Linux/Unix Permission Model:**\nPermissions are assigned to three categories: **owner** (the file's creator), **group** (a defined set of users), and **others** (everyone else). Each category gets three bits: read (r), write (w), execute (x).\n\n- **Symbolic notation:** `rwxr-xr--` — owner has rwx, group has r-x, others have r--\n- **Numeric (octal) notation:** Each permission has a value: read=4, write=2, execute=1. Sum them for each category.\n  - `chmod 755` = owner: rwx (7), group: r-x (5), others: r-x (5)\n  - `chmod 644` = owner: rw- (6), group: r-- (4), others: r-- (4)\n- **`chmod`:** The command used to change permissions. `chmod 755 script.sh`\n- **`chown`:** Changes file ownership. `chown user:group file`\n\n**Windows NTFS Permission Model:**\nMore granular than Linux — permissions include Full Control, Modify, Read & Execute, Read, Write, and special permissions. Permissions are assigned to users and groups and can be applied explicitly or inherited from parent folders.\n\n- **Inheritance:** NTFS permissions flow down from parent directories unless explicitly overridden.\n- **Allow vs. Deny:** Permissions can be explicitly allowed or denied. Explicit Deny overrides Allow.\n- **Effective Permissions:** The combined result of all permissions a user has from direct assignment and group membership.\n\n## Why It Matters\nFile permission issues are among the most common support tickets — \"access denied,\" \"can't open the file,\" \"can't run the script.\" IT professionals must know how to read, set, and troubleshoot permissions on both Windows ([[NTFS]]) and Linux systems. Permission misconfiguration is also a security risk — world-writable directories, sensitive files readable by all users, and executable files in wrong locations are all exploitable vulnerabilities.\n\n## Related Topics\n- [[File System]]\n- [[NTFS]]\n- [[Access Control]]\n- [[Principle of least Privilege]]\n- [[BASH]]\n- [[Linux]]\n- [[Active Directory]]"},{"id":"Terms and Concepts/File Server","title":"File Server","section":"Terms and Concepts","domain":"Networking","description":"A dedicated server that stores and shares files over a network, providing a central repository that multiple users and devices can access.","tags":["IT","IT/OS","IT/Networking","Level/Intermediate"],"content":"# File Server\n\n> A dedicated server that stores and shares files over a network, providing a central repository that multiple users and devices can access.\n\n## Overview\nA file server is a networked computer or appliance dedicated to storing files and making them accessible to users across an organization. Rather than storing work documents on individual workstations, organizations use file servers to provide a central location — ensuring files are backed up, accessible from any device on the network, and subject to controlled permissions.\n\nFile servers are one of the oldest and most common server roles in enterprise IT. They can run on Windows Server (using [[SMB]]/[[CIFS]] for sharing), Linux (using Samba), or purpose-built [[NAS]] devices. Cloud equivalents include SharePoint, OneDrive for Business, Google Drive, and AWS EFS.\n\n## Key Concepts\n\n- **File Share / Network Share:** A folder on the file server made accessible over the network. Users map network drives (e.g., `\\\\server\\share`) to access it as if it were a local drive.\n- **[[SMB]]/[[CIFS]]:** The protocol Windows uses for file sharing. Most enterprise file servers use SMB3 for performance and security.\n- **Samba:** Open-source implementation of SMB for Linux/Unix servers, allowing them to serve files to Windows clients.\n- **[[NTFS]] + Share Permissions:** Windows file servers use two layers of permissions — NTFS permissions (on the file system itself) and share permissions (controlling access to the share). The more restrictive of the two applies.\n- **[[NAS]] (Network-Attached Storage):** A purpose-built device that functions as a file server, often with built-in RAID for redundancy. Common brands: Synology, QNAP, NetApp.\n- **[[DFS]] (Distributed File System):** A Microsoft feature that presents multiple file shares under a single unified namespace. Enables load balancing and redundancy across multiple servers without users knowing which physical server holds the files.\n- **Quotas:** Storage limits applied per user or group to prevent any one user from consuming all available space.\n- **File [[Auditing]]:** Logging who accessed or modified which files — important for compliance and security incident investigation.\n\n## Why It Matters\nFile servers are central to how organizations store and share information. IT professionals configure shares, manage permissions, troubleshoot access issues, monitor storage capacity, and ensure backups cover file server data. Understanding [[SMB]] permissions, DFS, and file auditing is tested on Windows Server certifications and is a daily reality in enterprise sysadmin roles.\n\n## Related Topics\n- [[SMB]]\n- [[CIFS]]\n- [[NTFS]]\n- [[NAS]]\n- [[File Permission]]\n- [[Active Directory]]\n- [[Sharing]]"},{"id":"Terms and Concepts/File System","title":"File System","section":"Terms and Concepts","domain":"Security","description":"The method an operating system uses to organize, store, retrieve, and manage files on storage devices — defining how data is structured on disk.","tags":["IT","IT/OS","Level/Foundational"],"content":"# File System\n\n> The method an operating system uses to organize, store, retrieve, and manage files on storage devices — defining how data is structured on disk.\n\n## Overview\nA file system is the organizational layer between an operating system and a storage device. It defines how files are named, where they're stored on disk, how they're found again, and what metadata (permissions, timestamps, attributes) is tracked alongside them. Without a file system, a hard drive or SSD is just a sea of raw bytes with no structure.\n\nDifferent operating systems use different file systems by default: Windows uses [[NTFS]], macOS uses [[APFS]], Linux commonly uses ext4, and removable media often uses [[FAT32]] or exFAT for cross-platform compatibility. The choice of file system affects performance, maximum file/volume sizes, security features, and what operating systems can read the drive.\n\n## Key Concepts\n\n- **[[NTFS]] (New Technology File System):** The default Windows file system. Supports large files, [[File Permission|permissions]], encryption, journaling, and compression. Required for Windows system drives.\n- **[[FAT32]] (File Allocation Table 32):** Legacy file system with wide compatibility across all OS and devices. Maximum 4GB file size — a significant limitation.\n- **exFAT:** Modern Microsoft file system for removable media. Removes FAT32's 4GB limit while maintaining cross-platform compatibility.\n- **ext4:** The most common Linux file system. Reliable, performant, supports large files and journaling.\n- **[[APFS]] (Apple File System):** Default on modern Apple devices (macOS 10.13+, iOS 10.3+). Optimized for SSDs, with snapshots, encryption, and space sharing.\n- **Journaling:** A file system feature that logs pending changes before writing them. If the system crashes mid-write, the journal allows recovery without full disk scanning. Used by NTFS, ext4, APFS.\n- **Clusters/Blocks:** Storage is allocated in fixed-size units. The cluster size affects efficiency — large clusters waste space on small files; small clusters create overhead on large files.\n- **Formatting:** The process of preparing a storage device with a file system. Erases existing data and creates the file system structure.\n- **Mount Point:** In Linux/Unix, a location in the directory tree where a file system is attached and made accessible.\n\n## Why It Matters\nIT professionals choose file systems when formatting drives, troubleshoot compatibility issues (e.g., a drive formatted NTFS won't write on macOS by default), and understand why certain operations succeed or fail based on file system features. File system knowledge is tested on CompTIA A+ and is essential for storage administration, OS deployment, and forensics.\n\n## Related Topics\n- [[NTFS]]\n- [[FAT32]]\n- [[APFS]]\n- [[Storage]]\n- [[Operating System]]\n- [[File Management]]\n- [[File Permission]]"},{"id":"Terms and Concepts/FinTech","title":"FinTech","section":"Terms and Concepts","domain":"Security","description":"The application of technology and software to deliver or improve financial services — including payments, banking, lending, investing, insurance, and regulatory compliance.","tags":["IT","IT/Fundamentals","Level/Advanced"],"content":"# FinTech (Financial Technology)\n\n> The application of technology and software to deliver or improve financial services — including payments, banking, lending, investing, insurance, and regulatory compliance.\n\n## Overview\nFinTech (Financial Technology) encompasses any technology that improves or disrupts traditional financial services. It ranges from mobile payment apps (Venmo, Apple Pay) and digital banks (Chime, Revolut) to algorithmic trading platforms, peer-to-peer lending, cryptocurrency exchanges, and AI-driven fraud detection.\n\nFinTech companies challenge traditional financial institutions by offering faster, cheaper, more convenient alternatives. They leverage [[Cloud Computing]], [[AI]], [[Blockchain]], and mobile technology to deliver services that once required physical branches or complex manual processes.\n\nFor IT professionals, FinTech is relevant because financial systems are high-value targets for cyberattacks, subject to strict compliance requirements ([[PCI DSS]], SOX, AML regulations), and drive demand for specialized security, cloud infrastructure, and API integration skills.\n\n## Key Concepts\n\n- **Digital Payments:** Mobile apps and contactless payments that enable transactions without cash or physical cards. Examples: Apple Pay, Google Pay, Venmo, Zelle.\n- **Open Banking / APIs:** Regulations (in the UK and EU) and business trends requiring banks to expose their data through [[API|APIs]], enabling third-party apps to build financial services on top of banking infrastructure.\n- **[[Blockchain]] and Crypto:** Distributed ledger technology enabling cryptocurrencies (Bitcoin, Ethereum) and smart contracts. Increasingly integrated into mainstream finance.\n- **Robo-Advisors:** AI-driven investment platforms that provide automated portfolio management without human financial advisors.\n- **RegTech:** Regulatory technology — using software to automate compliance monitoring, KYC (Know Your Customer) checks, AML (Anti-Money Laundering) screening, and regulatory reporting.\n- **[[PCI DSS]]:** The security standard that governs any organization processing payment card data. Central to FinTech security compliance.\n- **Cybersecurity in FinTech:** Financial systems are prime targets for fraud, data theft, and account takeover. Multi-factor authentication, fraud detection AI, and encryption are critical.\n\n## Why It Matters\nFinTech is one of the fastest-growing sectors in IT. IT professionals working in or adjacent to financial services — whether supporting payment systems, managing cloud infrastructure for a bank, or implementing security controls — need to understand FinTech concepts, the regulatory environment, and the unique security challenges of handling financial data.\n\n## Related Topics\n- [[Blockchain]]\n- [[Tokenization]]\n- [[PCI DSS]]\n- [[API]]\n- [[Encryption]]\n- [[Cloud Computing]]\n- [[Data Privacy Laws]]"},{"id":"Terms and Concepts/Firewall","title":"Firewall","section":"Terms and Concepts","domain":"Networking","description":"A network security system that monitors and controls incoming and outgoing network traffic based on defined security rules, acting as a barrier between trusted and untrusted networks.","tags":["IT","IT/Security","IT/Networking","Level/Foundational"],"content":"# Firewall\n\n> A network security system that monitors and controls incoming and outgoing network traffic based on defined security rules, acting as a barrier between trusted and untrusted networks.\n\n## Overview\nA firewall is the first and most fundamental layer of network defense. It sits at the boundary between networks (typically between the internet and an internal network, or between network segments) and enforces rules about which traffic is allowed to pass and which is blocked. Every organization, from a home user's router to a multi-national corporation, relies on firewalls.\n\nFirewalls have evolved significantly over time — from simple packet filters that check IP addresses and ports, to stateful firewalls that track connection state, to modern Next-Generation Firewalls (NGFWs) that perform deep packet inspection, application identification, and integrate with threat intelligence.\n\nA firewall that's well-configured and regularly updated is a critical security control. One that's misconfigured — with overly permissive rules — provides false security while leaving real exposure.\n\n## Key Concepts\n\n- **Packet Filtering Firewall:** Examines each packet individually against allow/deny rules based on source/destination IP, port, and protocol. Fast but limited — doesn't track connection state.\n- **Stateful Inspection Firewall:** Tracks active connections (state table). Knows whether a packet belongs to an established session — much more accurate than simple packet filtering.\n- **Application-Layer Firewall (Proxy Firewall):** Operates at Layer 7. Can inspect application-specific content (HTTP methods, FTP commands, DNS queries). More resource-intensive but far more granular.\n- **Next-Generation Firewall (NGFW):** Combines stateful inspection, deep packet inspection, application identification, [[IPS]], SSL/TLS inspection, and threat intelligence in a single platform. Examples: Palo Alto, Fortinet, Cisco Firepower.\n- **ACL (Access Control List):** The set of rules on the firewall defining what's allowed or denied. Rules are processed top-down; first match wins.\n- **Implicit Deny:** A critical security principle — any traffic not explicitly allowed is denied. Well-configured firewalls end with a \"deny all\" rule.\n- **Host-Based Firewall:** Software firewall running on an individual device (Windows Defender Firewall, iptables on Linux). Complements network firewalls.\n- **[[DMZ]]:** A network segment between two firewall tiers, housing public-facing servers.\n\n## Why It Matters\nFirewalls are a foundational IT security control present in every enterprise environment. IT professionals configure firewall rules, troubleshoot connectivity blocked by firewalls, and understand where different traffic flows are permitted or denied. Understanding firewall types and rule logic is tested on CompTIA Network+ and Security+ and is a daily reality in network administration and security roles.\n\n## Related Topics\n- [[ACL]]\n- [[IDS]]\n- [[IPS]]\n- [[DMZ]]\n- [[Network]]\n- [[Cyber Attacks]]\n- [[DDoS]]"},{"id":"Terms and Concepts/FISMA","title":"FISMA","section":"Terms and Concepts","domain":"Security","description":"A U.S. federal law requiring government agencies to develop, document, and implement information security programs to protect federal information systems.","tags":["IT","IT/Compliance","Level/Intermediate"],"content":"# FISMA (Federal Information Security Management Act)\n\n> A U.S. federal law requiring government agencies to develop, document, and implement information security programs to protect federal information systems.\n\n## Overview\nThe Federal Information Security Management Act (FISMA) was enacted in 2002 (and modernized by FISMA 2014) to establish a comprehensive framework for securing federal government information systems and the sensitive data they hold. It applies to all federal agencies and contractors that operate information systems on behalf of the government.\n\nFISMA requires agencies to categorize their information systems by risk level, implement security controls based on [[NIST]] standards, conduct regular security assessments, and report their security posture annually. This continuous, risk-based approach is embodied in NIST's Risk Management Framework (RMF).\n\nFor IT professionals working with or for the federal government, FISMA compliance is a foundational requirement — not optional. Contractors handling government data must also meet FISMA requirements, making it relevant to private sector IT professionals in defense, healthcare, finance, and cloud services.\n\n## Key Concepts\n\n- **Risk Management Framework (RMF):** The NIST-developed process for implementing FISMA — categorize systems, select controls, implement controls, assess controls, authorize systems, and continuously monitor.\n- **FIPS 199 Categorization:** Systems are categorized as Low, Moderate, or High impact based on the potential harm from a security breach. Higher impact = more stringent controls.\n- **[[NIST]] SP 800-53:** The comprehensive catalog of security and privacy controls for federal information systems. Agencies select applicable controls based on their system's impact level.\n- **Continuous Monitoring:** FISMA requires ongoing monitoring of security controls — not just periodic assessments. This means automated scanning, log review, and real-time alerting.\n- **Authorization to Operate (ATO):** Formal approval to operate an information system after it has been assessed and found to meet security requirements. Must be renewed periodically.\n- **FedRAMP:** FISMA's cloud equivalent — a standardized authorization program for cloud services used by federal agencies. Cloud providers must be FedRAMP-authorized to serve the government.\n- **CISA:** The Cybersecurity and Infrastructure Security Agency oversees FISMA implementation across civilian agencies and coordinates federal incident response.\n\n## Why It Matters\nFISMA shaped the entire approach to federal IT security and influenced commercial security frameworks through its adoption of NIST standards. IT professionals working in or with the U.S. government must understand FISMA requirements, how to navigate the RMF process, and what controls are required. The principles — risk categorization, control selection, continuous monitoring — are also sound practices for any organization regardless of regulatory requirements.\n\n## Related Topics\n- [[NIST Cybersecurity Framework]]\n- [[NIST]]\n- [[Security Assessments]]\n- [[Auditing]]\n- [[CIA Triad]]\n- [[Data Privacy Laws]]"},{"id":"Terms and Concepts/Five Nines","title":"Five Nines","section":"Terms and Concepts","domain":"Security","description":"A high-availability benchmark indicating that a system or service is operational 99.999% of the time, allowing less than ~5.26 minutes of downtime per year.","tags":["IT","IT/Security","Level/Intermediate"],"content":"# Five Nines (99.999% Availability)\n\n> A high-availability benchmark indicating that a system or service is operational 99.999% of the time, allowing less than ~5.26 minutes of downtime per year.\n\n## Overview\n\"Five Nines\" (99.999%) is the gold standard for system availability in critical environments. The term comes from the number of nines in the availability percentage — a useful shorthand for comparing reliability tiers. The number of nines directly corresponds to how much downtime is acceptable per year.\n\nFive Nines is not achieved by accident — it requires redundant hardware, automatic failover, geographic distribution, rigorous monitoring, and careful change management. Any single component that can fail without automatic recovery is a threat to this target.\n\nThis standard is relevant in financial services, telecommunications, healthcare, and emergency systems — environments where even minutes of downtime translate to significant financial loss, safety risks, or regulatory violations.\n\n## Key Concepts\n\n| Availability | Downtime per Year | Downtime per Month |\n|-------------|------------------|--------------------|\n| 99% | ~3.65 days | ~7.3 hours |\n| 99.9% (Three Nines) | ~8.76 hours | ~43.8 minutes |\n| 99.99% (Four Nines) | ~52.6 minutes | ~4.4 minutes |\n| 99.999% (Five Nines) | ~5.26 minutes | ~26 seconds |\n| 99.9999% (Six Nines) | ~31.5 seconds | ~2.6 seconds |\n\n- **[[Redundancy]]:** Eliminating single points of failure through duplicate components — redundant power supplies, network links, servers, data centers.\n- **Failover:** Automatic switching to a backup system when the primary fails. Hot standby systems enable immediate failover with minimal service interruption.\n- **Geographic Distribution:** Spreading infrastructure across multiple data centers or availability zones — a failure in one region doesn't take down the service globally.\n- **[[SLA]] (Service Level Agreement):** Formal commitments on availability. Cloud providers publish [[SLA|SLAs]] defining what they guarantee and what credits customers receive if commitments aren't met.\n- **Planned vs. Unplanned Downtime:** Five Nines accounts for all downtime — including planned maintenance windows. High-availability architectures must support zero-downtime deployments and upgrades.\n- **MTTR and MTBF:** Mean Time to Recovery (how fast you recover from failure) and Mean Time Between Failures (how often failures occur) are the engineering metrics behind availability numbers.\n\n## Why It Matters\nAvailability targets drive infrastructure design decisions. When specifying systems, IT architects must translate availability requirements (defined by business stakeholders) into technical architecture — how many servers, what redundancy, what monitoring, what failover. Understanding the availability tiers and what's required to achieve them is essential for infrastructure design and for evaluating cloud provider [[SLA|SLAs]].\n\n## Related Topics\n- [[Availability]]\n- [[Redundancy]]\n- [[Disaster Recovery]]\n- [[SLA]]\n- [[Backups]]\n- [[Cloud Computing]]"},{"id":"Terms and Concepts/Flood Guards","title":"Flood Guards","section":"Terms and Concepts","domain":"Networking","description":"Security mechanisms that detect and mitigate flooding attacks by monitoring traffic rates, identifying abnormal patterns, and blocking or rate-limiting excessive traffic.","tags":["IT","IT/Security","IT/Networking","Level/Intermediate"],"content":"# Flood Guards\n\n> Security mechanisms that detect and mitigate flooding attacks by monitoring traffic rates, identifying abnormal patterns, and blocking or rate-limiting excessive traffic.\n\n## Overview\nFlood guards are security controls designed to protect network devices and servers from flooding attacks — attacks that overwhelm a target by sending it an enormous volume of traffic or connection requests. SYN floods, UDP floods, ICMP floods, and HTTP floods are common examples that can exhaust resources and cause denial of service.\n\nFlood guards work by monitoring incoming traffic and comparing it against baseline or threshold values. When traffic from a source or of a particular type exceeds defined limits, the flood guard activates protective measures — blocking the source, rate-limiting the traffic, or diverting it for further analysis.\n\nFlood guards can be implemented at multiple layers: on firewalls, routers, load balancers, [[IPS]] systems, and dedicated [[DDoS]] mitigation appliances. They are a key component of an availability-focused security architecture.\n\n## Key Concepts\n\n- **SYN Flood:** Attackers send rapid TCP SYN packets without completing the handshake, exhausting the server's connection table. SYN cookies and rate limiting are common defenses.\n- **UDP Flood:** High-volume UDP packets are sent to random ports, causing the system to repeatedly check and respond with ICMP \"Destination Unreachable\" messages.\n- **ICMP Flood (Ping Flood):** Overwhelming a host with ICMP echo requests, consuming bandwidth and CPU.\n- **Rate Limiting:** Restricts the number of packets or connections from a source within a time window. Simple but effective against basic floods.\n- **Traffic Thresholds:** Flood guards define normal traffic baselines; deviations trigger protective actions.\n- **Automatic Blocking:** When a source exceeds defined thresholds, the flood guard blocks that IP temporarily or permanently.\n- **[[DDoS]] Mitigation:** For large-scale distributed floods, specialized DDoS mitigation services (Cloudflare, AWS Shield, Akamai) provide scrubbing infrastructure that handles volumes beyond what local flood guards can manage.\n- **[[IPS]] Integration:** Intrusion Prevention Systems often include flood detection and can automatically update firewall rules to block sources.\n\n## Why It Matters\nFlood attacks are a constant threat to internet-facing systems. Flood guards are a foundational availability control for any organization running public-facing infrastructure. IT professionals configuring firewalls, routers, and load balancers need to understand flood protection features and how to configure thresholds appropriately. Over-aggressive settings block legitimate traffic; under-aggressive settings fail to stop attacks.\n\n## Related Topics\n- [[DDoS]]\n- [[IPS]]\n- [[Firewall]]\n- [[Availability]]\n- [[Network Traffic]]\n- [[Cyber Attacks]]"},{"id":"Terms and Concepts/Folder","title":"Folder","section":"Terms and Concepts","domain":"Cloud","description":"A virtual container in a file system used to organize and group related files and other folders, synonymous with \\\"directory\\\" in most modern contexts.","tags":["IT","IT/OS","Level/Foundational"],"content":"# Folder\n\n> A virtual container in a file system used to organize and group related files and other folders, synonymous with \"directory\" in most modern contexts.\n\n## Overview\nA folder (also called a [[Directory]]) is the organizational unit that gives file systems their hierarchical structure. Folders contain files and can contain other folders (called subfolders), creating a tree structure that allows data to be organized logically — by project, date, user, type, or any other classification scheme.\n\nThe term \"folder\" is primarily used in graphical environments (like Windows Explorer and macOS Finder), while \"directory\" is the traditional term used in command-line environments and technical documentation. They refer to the same concept.\n\nEvery file system has a root folder — the top of the hierarchy. On Windows this is typically `C:\\`; on Linux/macOS it is `/`. Every file and folder on the system lives somewhere in this tree.\n\n## Key Concepts\n\n- **Root Folder:** The top-level folder from which all others branch. Cannot be deleted or moved.\n- **Subfolder:** A folder inside another folder. `Documents\\Projects\\2024` has `Documents` → `Projects` → `2024` as nested subfolders.\n- **Path:** The address of a folder in the hierarchy. `C:\\Users\\Ryan\\Documents` is an absolute path; `Documents\\Reports` is relative.\n- **Hidden Folders:** Folders configured to be invisible in normal directory listings. On Windows, set via file attributes. On Linux, folder names beginning with `.` are hidden.\n- **Folder Permissions:** Folders have [[File Permission|permissions]] controlling who can view, modify, or create files within them. Permissions often inherit from parent folders.\n- **Special Folders:** Operating systems create standard folders for specific purposes — `Desktop`, `Documents`, `Downloads`, `AppData` (Windows), `/etc`, `/var`, `/home` (Linux).\n- **Folder vs. Directory:** Functionally identical. \"Folder\" is GUI-centric; \"directory\" is used in technical and command-line contexts.\n\n## Why It Matters\nFolders are how data is organized on every computer system. IT professionals navigate, create, move, and manage folders constantly — whether organizing files on a server, setting up home directories for users, configuring profile paths in [[Active Directory]], or troubleshooting file access issues. Understanding folder structure, paths, and permissions is foundational to all IT support and administration work.\n\n## Related Topics\n- [[Directory]]\n- [[File System]]\n- [[File Management]]\n- [[File Permission]]\n- [[Operating System]]\n- [[BASH]]"},{"id":"Terms and Concepts/Forest","title":"Forest","section":"Terms and Concepts","domain":"Security","description":"The highest-level structure in Active Directory — a collection of one or more domain trees that share a common schema, configuration, and Global Catalog.","tags":["IT","IT/IAM","Level/Intermediate"],"content":"# Forest (Active Directory)\n\n> The highest-level structure in Active Directory — a collection of one or more domain trees that share a common schema, configuration, and Global Catalog.\n\n## Overview\nIn [[Active Directory]], a forest is the top-most administrative boundary. It contains one or more [[Domain|domains]] organized into trees, all sharing a common schema (the blueprint for all AD objects) and a Global Catalog (a searchable index of objects across all domains).\n\nThe first domain created in a forest becomes the **forest root domain** — it holds a special role and cannot be demoted. Large organizations may have multiple domains within a forest (e.g., `corp.contoso.com` and `sales.contoso.com`), or even multiple forests if they require complete administrative separation (e.g., after a merger or for security isolation).\n\nForests are relevant to IT professionals managing complex Active Directory environments — particularly those working in enterprise environments, doing AD troubleshooting, or studying for Microsoft certifications.\n\n## Key Concepts\n\n- **Forest Root Domain:** The first domain in the forest. Holds the Schema Master and Domain Naming Master FSMO roles. All trusts between domains in the forest ultimately trace back here.\n- **Schema:** A forest-wide definition of every object type and attribute that can exist in Active Directory (e.g., what attributes a \"User\" object has). Shared across all domains in the forest. Schema changes are rare and irreversible.\n- **[[Global Catalog]]:** A distributed data repository that stores a partial replica of every object in every domain in the forest. Enables users to search for objects across all domains without knowing which domain they're in.\n- **Domain Tree:** A collection of domains with a contiguous DNS namespace (e.g., `contoso.com`, `corp.contoso.com`, `sales.contoso.com`). Trees share the same forest.\n- **Transitive Trust:** All domains in a forest automatically trust each other transitively — a user in `sales.contoso.com` can access resources in `corp.contoso.com` if given permission.\n- **Forest Trust:** A trust relationship between two separate forests. Required if organizations with separate forests need to share resources.\n- **Single Forest vs. Multiple Forests:** Most organizations use a single forest. Multiple forests are used for strict security separation (military, some enterprises) or after M&A before migration.\n\n## Why It Matters\nUnderstanding forest architecture is essential for advanced Active Directory administration, troubleshooting authentication across domains, and planning AD infrastructure. Forest-level concepts (schema, Global Catalog, forest trusts) appear in Microsoft certification exams and in real-world AD troubleshooting scenarios.\n\n## Related Topics\n- [[Active Directory]]\n- [[Domain]]\n- [[Global Catalog]]\n- [[Active Directory Domain Services]]\n- [[Domain and Forest Functionality]]\n- [[Replication]]"},{"id":"Terms and Concepts/Form Factor","title":"Form Factor","section":"Terms and Concepts","domain":"Networking","description":"The physical size, shape, and layout specification of a computer component — particularly motherboards, cases, and drives — that determines compatibility between components.","tags":["IT","IT/Hardware","Level/Foundational"],"content":"# Form Factor\n\n> The physical size, shape, and layout specification of a computer component — particularly motherboards, cases, and drives — that determines compatibility between components.\n\n## Overview\nForm factor is a standardized specification describing the physical dimensions, mounting hole positions, power connector locations, and expansion slot placements of computer components. By adhering to form factor standards, components from different manufacturers can be combined in a single system — an ATX motherboard from ASUS fits in an ATX case from Corsair, powered by a PSU from Seasonic, all because they follow the same form factor specification.\n\nThe most common form factor decisions in IT involve motherboards (ATX, Micro-ATX, Mini-ITX), cases (tower, mini-tower, rack-mount), drives (3.5\", 2.5\", M.2), and power supplies (ATX, SFX).\n\n## Key Concepts\n\n**Motherboard Form Factors:**\n\n| Form Factor | Size | Use Case |\n|-------------|------|----------|\n| ATX | 305 × 244 mm | Standard desktop, most expansion slots |\n| Micro-ATX | 244 × 244 mm | Compact desktop, fewer slots |\n| Mini-ITX | 170 × 170 mm | Small form factor PCs, HTPCs |\n| E-ATX | 305 × 330 mm | High-end workstations, servers |\n\n**Drive Form Factors:**\n- **3.5\":** Standard desktop hard drives (HDD). Fits in full-size drive bays.\n- **2.5\":** Laptop hard drives and SSDs. Smaller, lower power.\n- **M.2:** Ultra-compact NVMe and SATA SSDs that plug directly into the motherboard. Multiple sizes: 2242, 2260, 2280 (length in mm).\n- **U.2:** Enterprise-class SSDs with a different connector. Used in servers.\n\n**Case Form Factors:**\n- Full Tower, Mid Tower, Mini Tower — for desktop builds\n- Rack Unit (1U, 2U, 4U) — for server rack mounting\n- Small Form Factor (SFF) — compact cases for mini-ITX builds\n\n- **PSU Compatibility:** Power supplies also follow form factors (ATX, SFX, SFX-L) that must match the case. An ATX PSU won't physically fit in an SFX case.\n\n## Why It Matters\nForm factor knowledge is essential when building, upgrading, or repairing computer systems. IT professionals must verify form factor compatibility before purchasing components — a motherboard that doesn't fit the case, or a drive that doesn't fit the bay, wastes money and time. This is tested on CompTIA A+ and is practical knowledge for any hardware support role.\n\n## Related Topics\n- [[Motherboard]]\n- [[Computer]]\n- [[Desktop]]\n- [[Server]]\n- [[Hardware]]\n- [[Storage]]"},{"id":"Terms and Concepts/FQDN","title":"FQDN","section":"Terms and Concepts","domain":"Networking","description":"The complete, unambiguous domain name that specifies an exact location in the DNS hierarchy — including the host name, all subdomain levels, and the top-level domain.","tags":["IT","IT/Networking","Level/Intermediate"],"content":"# FQDN (Fully Qualified Domain Name)\n\n> The complete, unambiguous domain name that specifies an exact location in the DNS hierarchy — including the host name, all subdomain levels, and the top-level domain.\n\n## Overview\nA Fully Qualified Domain Name (FQDN) is a domain name written out completely, with all levels specified from the specific host down to the root. It leaves no ambiguity about which host is being referenced — unlike a relative or partial name.\n\nFor example, `mail.example.com.` is an FQDN (the trailing dot represents the DNS root, usually implied but technically required for full qualification). It specifies: the host `mail`, within the domain `example`, within the top-level domain `com`. Each component is unambiguous.\n\nFQDNs are used extensively in [[Active Directory]], [[DNS]] configuration, SSL certificates, and server administration. When configuring a system's hostname for domain join, verifying a certificate's Common Name, or writing an MX record, you're working with FQDNs.\n\n## Key Concepts\n\n- **Structure:** `hostname.subdomain.domain.TLD.` (reading left to right, from most specific to root)\n- **Absolute vs. Relative:** An FQDN is an absolute name — it starts from the root. A relative name like `mail` is resolved relative to the current search domain.\n- **DNS Root Dot:** Technically, every FQDN ends with a dot (`.`) representing the root zone. In practice, this trailing dot is usually omitted in everyday use.\n- **Hostname:** The specific device or service identifier. `server1`, `mail`, `www`, `vpn`.\n- **Search Domain:** A local domain suffix configured on clients so they can resolve short names. If the search domain is `company.local`, typing `fileserver` resolves to `fileserver.company.local` — but the FQDN is the unambiguous version.\n- **SSL Certificates:** Certificates are issued to FQDNs. The Common Name (CN) or Subject Alternative Name (SAN) must match the FQDN of the server for the certificate to be trusted.\n- **[[Active Directory]]:** When joining a computer to a domain, the domain controller's FQDN is used. AD uses FQDNs throughout — `dc1.corp.contoso.com`.\n\n## Why It Matters\nFQDNs appear constantly in IT administration — DNS records, server configuration, certificate management, Active Directory, and network troubleshooting all use them. Understanding the structure of an FQDN and when to use the full name vs. a short name prevents configuration errors and DNS resolution failures.\n\n## Related Topics\n- [[DNS]]\n- [[Domain Name]]\n- [[Domain]]\n- [[Active Directory]]\n- [[SSL]]\n- [[TLS]]"},{"id":"Terms and Concepts/FTP","title":"FTP","section":"Terms and Concepts","domain":"Networking","description":"A network protocol used to transfer files between a client and a server over a TCP/IP network, operating on ports 20 (data) and 21 (control).","tags":["IT","IT/Networking","Level/Foundational"],"content":"# FTP (File Transfer Protocol)\n\n> A network protocol used to transfer files between a client and a server over a TCP/IP network, operating on ports 20 (data) and 21 (control).\n\n## Overview\nFile Transfer Protocol (FTP) is one of the oldest and most widely supported protocols for transferring files across networks. Defined in RFC 959, FTP uses a client-server model — a client connects to an FTP server, authenticates, and can then upload, download, list, rename, and delete files on the server.\n\nA fundamental limitation of traditional FTP is that it transmits data — including usernames and passwords — in plaintext. Anyone sniffing the network can capture credentials. For this reason, FTP has largely been replaced by its secure variants: **FTPS** (FTP over SSL/TLS) and **SFTP** (SSH File Transfer Protocol, which is unrelated to FTP but provides similar functionality over SSH).\n\nDespite its age and security limitations, FTP is still encountered in legacy systems, web hosting environments, and some industrial/IoT contexts.\n\n## Key Concepts\n\n- **Control Connection (Port 21):** Used for authentication and sending commands (list files, change directory, initiate transfer).\n- **Data Connection (Port 20 or dynamic):** Opened separately to transfer actual file data. Two modes: Active (server connects back to client — problematic with firewalls) and Passive (client initiates data connection — firewall-friendly).\n- **Active vs. Passive Mode:** Passive mode is almost always required in modern environments because firewalls typically block inbound connections to clients.\n- **Anonymous FTP:** Some FTP servers allow anonymous access — users connect with username \"anonymous\" and an email as password. Used for public file distribution.\n- **FTPS (FTP Secure):** FTP with TLS encryption added. Encrypts both the control and data channels. Uses explicit FTPS (starts unencrypted, then upgrades) or implicit FTPS (always encrypted).\n- **SFTP (SSH File Transfer Protocol):** Runs over [[SSH]] (port 22). Completely different protocol from FTP despite the similar name. Encrypted by default; the preferred replacement in most environments.\n- **Common FTP Commands:** `LIST` (list files), `GET`/`RETR` (download), `PUT`/`STOR` (upload), `CD`/`CWD` (change directory), `DEL`/`DELE` (delete).\n\n## Why It Matters\nFTP is foundational networking knowledge — it illustrates client-server communication, active vs. passive modes, and why plaintext protocols are insecure. IT professionals will encounter FTP servers in legacy environments and must understand when to use FTPS or SFTP instead. Port 21 is also a common firewall rule topic in networking certifications.\n\n## Related Topics\n- [[SSH]]\n- [[TFTP]]\n- [[Common Ports]]\n- [[Encryption]]\n- [[Network]]\n- [[Application Layer]]"},{"id":"Terms and Concepts/GCP","title":"GCP","section":"Terms and Concepts","domain":"Networking","description":"Google's cloud computing platform offering infrastructure, platform services, and data analytics capabilities — particularly known for its AI/ML tools, Kubernetes, and big data services.","tags":["IT","IT/Cloud","Level/Intermediate"],"content":"# GCP (Google Cloud Platform)\n\n> Google's cloud computing platform offering infrastructure, platform services, and data analytics capabilities — particularly known for its AI/ML tools, Kubernetes, and big data services.\n\n## Overview\nGoogle Cloud Platform (GCP) is the third-largest cloud platform after [[AWS]] and [[Azure]], operated by Google. It provides the same core cloud building blocks — virtual machines, object storage, managed databases, networking — plus specialized services where Google has particular strength: BigQuery (data warehousing), TensorFlow/Vertex AI (machine learning), and Google Kubernetes Engine (GKE, the managed Kubernetes service that arguably invented the modern container orchestration space).\n\nGCP runs on the same infrastructure that powers Google Search, YouTube, and Gmail — one of the world's largest and most reliable networks. This gives GCP genuine technical advantages in networking speed and global reach.\n\nFor IT professionals, GCP is increasingly relevant as organizations adopt multi-cloud strategies, as Google's AI and analytics services are best-in-class, and as GKE is widely used for Kubernetes deployments.\n\n## Key Concepts\n\n- **Compute Engine:** Virtual machine service (equivalent to AWS EC2, Azure VMs). Customizable machine types, persistent disk storage.\n- **GKE (Google Kubernetes Engine):** Managed Kubernetes service. Google invented Kubernetes and GKE remains a leading managed K8s platform.\n- **Cloud Storage:** Scalable object storage for files, backups, media. Multiple storage classes (Standard, Nearline, Coldline, Archive).\n- **BigQuery:** Serverless, highly scalable data warehouse. Used for analytics on massive datasets. SQL interface. No infrastructure to manage.\n- **Cloud SQL:** Managed relational databases (MySQL, PostgreSQL, SQL Server).\n- **Vertex AI:** Google's unified AI/ML platform integrating model training, deployment, and monitoring.\n- **Cloud Functions:** Serverless compute (equivalent to AWS Lambda, Azure Functions). Event-driven code execution.\n- **VPC (Virtual Private Cloud):** GCP's isolated virtual network, with subnets, firewall rules, and private connectivity options.\n- **Anthos:** GCP's hybrid and multi-cloud management platform — manage workloads across GCP, on-premises, and other clouds.\n- **Regions and Zones:** GCP infrastructure is organized into geographic Regions (e.g., `us-central1`) and Zones (e.g., `us-central1-a`) for redundancy.\n\n## Why It Matters\nGCP is a required skill set for organizations that heavily use Google Workspace, are focused on AI/ML workloads, or use Kubernetes at scale. The Google Cloud Associate Cloud Engineer and Professional Cloud Architect certifications are valued credentials. Understanding the three major cloud platforms — AWS, Azure, and GCP — gives IT professionals the flexibility to work in any enterprise cloud environment.\n\n## Related Topics\n- [[Cloud Computing]]\n- [[AWS]]\n- [[Azure]]\n- [[Containers]]\n- [[IaaS]]\n- [[Machine Learning]]\n- [[CSP]]"},{"id":"Terms and Concepts/GDPR","title":"GDPR","section":"Terms and Concepts","domain":"Cloud","description":"The European Union's comprehensive data privacy law that establishes strict rules for how organizations collect, process, and protect personal data of EU residents — and imposes severe penalties for non-compliance.","tags":["IT","IT/Compliance","Level/Intermediate"],"content":"# GDPR (General Data Protection Regulation)\n\n> The European Union's comprehensive data privacy law that establishes strict rules for how organizations collect, process, and protect personal data of EU residents — and imposes severe penalties for non-compliance.\n\n## Overview\nThe General Data Protection Regulation (GDPR) came into force on May 25, 2018, replacing the EU's 1995 Data Protection Directive. It is widely considered the world's most comprehensive privacy law and has become the global benchmark for data protection legislation, influencing laws in California ([[CCPA]]), Brazil (LGPD), and many other jurisdictions.\n\nGDPR applies to any organization — regardless of where it's based — that processes personal data of people in the EU. A company in the United States with EU customers must comply with GDPR. The regulation creates both rights for individuals and obligations for organizations, backed by significant enforcement power.\n\nFor IT professionals, GDPR has direct technical implications: systems that collect, store, or process personal data must be designed with privacy in mind, must implement appropriate security controls, must enable data subject rights, and must have processes for breach notification.\n\n## Key Concepts\n\n- **Personal Data:** Any information relating to an identified or identifiable person — names, email addresses, IP addresses, cookie identifiers, biometric data, health records.\n- **Data Controller:** The organization that determines the purposes and means of processing personal data. Bears primary GDPR responsibility.\n- **Data Processor:** An organization that processes data on behalf of a controller (e.g., a cloud provider, SaaS vendor).\n- **Lawful Basis for Processing:** Organizations must have a legal basis to process personal data — consent, contract, legal obligation, vital interests, public task, or legitimate interests.\n- **Data Subject Rights:** Individuals have the right to access, rectify, erase (\"right to be forgotten\"), restrict processing, data portability, and object to processing.\n- **72-Hour Breach Notification:** When a data breach poses risk to individuals, the organization must notify the relevant supervisory authority within 72 hours of becoming aware.\n- **Data Protection Officer (DPO):** Some organizations must appoint a DPO — a dedicated privacy expert responsible for ensuring GDPR compliance.\n- **Privacy by Design:** GDPR requires building privacy protections into systems and processes from the start, not as an afterthought.\n- **Penalties:** Up to €20 million or 4% of global annual turnover (whichever is higher) for the most serious violations.\n\n## Why It Matters\nGDPR compliance is a technical requirement, not just a legal one. IT professionals must design databases that support data deletion, implement appropriate [[Encryption]], configure access controls on personal data, create audit logs, and build breach detection and response capabilities. Non-compliance is not just a legal risk — fines in the billions have been levied against Google, Meta, and others.\n\n## Related Topics\n- [[Data Privacy Laws]]\n- [[PII]]\n- [[CCPA]]\n- [[HIPAA]]\n- [[Data Breach]]\n- [[Confidentiality]]\n- [[Encryption]]"},{"id":"Terms and Concepts/Global Catalog","title":"Global Catalog","section":"Terms and Concepts","domain":"Networking","description":"A distributed, read-only repository in Active Directory that stores a partial replica of all objects from every domain in the forest, enabling forest-wide searches and authentication without contacting each domain's controller individually.","tags":["IT","IT/IAM","Level/Advanced"],"content":"# Global Catalog\n\n> A distributed, read-only repository in Active Directory that stores a partial replica of all objects from every domain in the forest, enabling forest-wide searches and authentication without contacting each domain's controller individually.\n\n## Overview\nThe Global Catalog (GC) is a feature of [[Active Directory]] that solves a fundamental multi-domain challenge: how can a user in one domain quickly find resources (users, groups, printers) in another domain without having to separately query each domain's controller?\n\nThe answer is the Global Catalog — a subset of attributes from every object in every domain in the [[Forest|forest]], stored on designated domain controllers called Global Catalog Servers. When a user searches the directory or authenticates using universal groups, the GC provides the necessary information instantly without cross-domain referrals.\n\nBy default, the first domain controller in a forest is a Global Catalog server. In larger environments, additional GC servers are deployed — particularly at remote sites — to reduce login times and search latency.\n\n## Key Concepts\n\n- **Partial Replica:** The GC doesn't store all attributes of every object — it stores a curated subset (defined in the schema) sufficient for common queries. This keeps the GC manageable in size.\n- **Global Catalog Server:** A domain controller designated to host the GC. Identified by port 3268 (LDAP) and 3269 (LDAP over SSL).\n- **Forest-wide Search:** Users can search for any object (user, group, printer) across all domains in the forest by querying a GC server.\n- **Universal Group Caching:** When a user logs in, their universal group memberships are looked up in the GC. Without a reachable GC, users may be unable to log in (a critical failure point).\n- **[[Replication]]:** GC data is replicated between all GC servers in the forest. Changes to GC-replicated attributes propagate to all GC servers.\n- **Site Topology:** Deploying GC servers in each AD site prevents WAN dependency for login — if the WAN link to the primary site is down, users can still authenticate using the local GC.\n- **Schema Attributes:** Administrators can mark additional attributes to be included in the GC by modifying the schema — useful if specific searches need more data.\n\n## Why It Matters\nThe Global Catalog is a critical infrastructure component in any multi-domain Active Directory environment. Login failures, slow searches, and Outlook address book problems are often traced back to GC availability or replication issues. IT professionals managing AD must understand GC placement, monitor GC replication health, and ensure GC servers are available in each AD site where users authenticate.\n\n## Related Topics\n- [[Active Directory]]\n- [[Forest]]\n- [[Domain]]\n- [[Replication]]\n- [[LDAP]]\n- [[Active Directory Domain Services]]"},{"id":"Terms and Concepts/GPU","title":"GPU","section":"Terms and Concepts","domain":"Hardware","description":"A specialized processor designed for parallel computation, originally built for rendering graphics but now widely used for AI training, scientific computing, and cryptocurrency mining.","tags":["IT","IT/Hardware","Level/Foundational"],"content":"# GPU (Graphics Processing Unit)\n\n> A specialized processor designed for parallel computation, originally built for rendering graphics but now widely used for AI training, scientific computing, and cryptocurrency mining.\n\n## Overview\nA Graphics Processing Unit (GPU) is a processor architecturally different from a [[CPU]]. While a CPU has a small number of powerful cores optimized for sequential tasks, a GPU contains thousands of smaller, simpler cores designed to handle many operations simultaneously. This massive parallelism makes GPUs ideal for rendering graphics (where millions of pixels must be calculated simultaneously) and for any workload that can be broken into many parallel computations.\n\nModern GPUs have two major application domains: **graphics rendering** (games, video production, 3D modeling) and **compute** (AI/ML training, scientific simulation, data analytics). NVIDIA dominates both markets, though AMD provides competitive options for graphics, and specialized AI accelerators (TPUs, custom ASICs) are increasingly common in data centers.\n\nFor IT professionals, GPUs are relevant in workstation specifications for graphics-intensive roles, in cloud compute for ML/AI workloads, and in understanding why GPU-accelerated computing is transforming data science and AI.\n\n## Key Concepts\n\n- **VRAM (Video RAM):** The GPU's dedicated memory for textures, frame buffers, and compute data. More VRAM enables higher resolutions, larger textures, and bigger AI models. Modern GPUs have 8GB–80GB+ VRAM.\n- **CUDA (NVIDIA):** NVIDIA's parallel computing platform and programming model for writing GPU-accelerated code. Required for most deep learning frameworks (TensorFlow, PyTorch).\n- **GPU Acceleration:** Offloading compute-intensive tasks from the CPU to the GPU. Can produce 10–100x speedups for parallelizable workloads.\n- **Dedicated vs. Integrated:** Discrete GPUs are separate cards with their own VRAM (performance GPUs). Integrated GPUs share system RAM and are built into the CPU (sufficient for basic display; inadequate for gaming or ML).\n- **PCIe Interface:** GPUs connect to the [[Motherboard]] via the PCIe (Peripheral Component Interconnect Express) bus. PCIe 4.0 and 5.0 offer increasing bandwidth for data-hungry workloads.\n- **Machine Learning GPUs:** NVIDIA H100, A100, and older V100 are data center GPUs designed specifically for AI training at massive scale — used by cloud providers and research labs.\n- **Display Output:** For workstation use, GPUs drive monitors via DisplayPort, HDMI, or other video interfaces.\n\n## Why It Matters\nGPUs are increasingly central to IT beyond just gaming or video editing. AI/ML workloads run on GPU clusters in the cloud and on-premises. Video production, 3D design, and scientific computing require powerful GPUs. IT professionals who spec workstations, manage cloud infrastructure, or work in AI-adjacent environments need to understand GPU capabilities, VRAM requirements, and when to recommend GPU-accelerated compute.\n\n## Related Topics\n- [[CPU]]\n- [[Motherboard]]\n- [[Hardware]]\n- [[Machine Learning]]\n- [[Cloud Computing]]\n- [[Drivers]]"},{"id":"Terms and Concepts/GRE","title":"GRE","section":"Terms and Concepts","domain":"Networking","description":"A tunneling protocol that encapsulates one network protocol inside another, creating a virtual point-to-point link between network endpoints over an IP network.","tags":["IT","IT/Networking","Level/Advanced"],"content":"# GRE (Generic Routing Encapsulation)\n\n> A tunneling protocol that encapsulates one network protocol inside another, creating a virtual point-to-point link between network endpoints over an IP network.\n\n## Overview\nGeneric Routing Encapsulation (GRE) is a protocol developed by Cisco (RFC 2784) that creates a tunnel between two routers or network devices. It wraps (encapsulates) one type of packet inside a GRE header and an outer IP header, then routes it across the network. At the destination, the GRE header is removed and the original packet is forwarded normally.\n\nGRE is protocol-agnostic — it can encapsulate IPv4, IPv6, IPX, and other network protocols inside an IP carrier. This makes it useful for connecting networks that run different protocols, or for extending routing protocols across networks that wouldn't otherwise support them.\n\nA key limitation of basic GRE is that it provides **no encryption** — it only creates a tunnel, not a secure one. For secure tunnels, GRE is often combined with [[IPsec]] (called GRE over IPsec or IPsec over GRE) to add encryption.\n\n## Key Concepts\n\n- **Tunnel Interface:** A virtual interface configured on a router representing one end of the GRE tunnel. The tunnel source and destination define which real IP addresses form the endpoints.\n- **[[Encapsulation]]:** When a packet enters the tunnel, GRE adds a GRE header (with protocol type) and an outer IP header. The original packet becomes the payload.\n- **Protocol Independence:** GRE can carry multicast, broadcast, and non-IP traffic that IPsec alone cannot carry — this is why GRE + IPsec is commonly used.\n- **No Encryption:** GRE alone doesn't encrypt traffic. Use GRE over [[IPsec]] for a secure tunnel.\n- **GRE over IPsec:** The most common production deployment — GRE provides the tunnel and protocol flexibility, IPsec provides encryption and authentication.\n- **[[VPN]] Use:** GRE tunnels are used to build site-to-site VPNs, especially when routing protocols (OSPF, EIGRP) need to run across the tunnel (which IPsec alone doesn't support).\n- **DMVPN (Dynamic Multipoint VPN):** A Cisco technology that uses GRE as its underlying mechanism for building scalable hub-and-spoke VPN networks.\n\n## How It Works\n\n1. Router A (tunnel source) receives a packet destined for a network across the GRE tunnel.\n2. The packet is encapsulated with a GRE header (protocol type field) and a new outer IP header pointing to Router B.\n3. The encapsulated packet is routed normally across the internet to Router B.\n4. Router B (tunnel destination) removes the outer IP header and GRE header, then forwards the original packet.\n\n## Why It Matters\nGRE is a foundational tunneling protocol in enterprise networking. IT professionals working with Cisco routers, site-to-site VPNs, or DMVPN deployments will encounter GRE regularly. Understanding how encapsulation works with GRE deepens understanding of how VPNs, overlay networks, and tunneling protocols function at a practical level.\n\n## Related Topics\n- [[VPN]]\n- [[IPsec]]\n- [[Encapsulation]]\n- [[Router]]\n- [[IP Routing]]\n- [[Network]]"},{"id":"Terms and Concepts/Group Policy","title":"Group Policy","section":"Terms and Concepts","domain":"Security","description":"A Windows feature that allows administrators to centrally define and enforce configuration settings, security policies, and software deployments across domain-joined computers and users.","tags":["IT","IT/IAM","Level/Intermediate"],"content":"# Group Policy\n\n> A Windows feature that allows administrators to centrally define and enforce configuration settings, security policies, and software deployments across domain-joined computers and users.\n\n## Overview\nGroup Policy is one of the most powerful administration tools in a Windows [[Active Directory]] environment. It allows a single administrator to configure hundreds of settings — password requirements, desktop backgrounds, software installations, security configurations, script execution, firewall rules — and apply them automatically to thousands of computers and users across the organization.\n\nSettings are defined in **Group Policy Objects (GPOs)**, which are then linked to [[Active Directory]] containers (sites, domains, or [[OU|OUs]]). When a computer starts or a user logs in, Windows contacts the domain controller, downloads applicable GPOs, and applies them. This process is automatic, consistent, and auditable.\n\nGroup Policy is a daily tool for Windows administrators — from locking down user workstations to deploying software to enforcing security baselines.\n\n## Key Concepts\n\n- **Group Policy Object (GPO):** A container for policy settings. GPOs are created in the Group Policy Management Console (GPMC) and can be linked to sites, domains, or OUs.\n- **Computer Configuration vs. User Configuration:** GPOs have two sections. Computer Configuration applies when the machine starts (regardless of who logs in). User Configuration applies when a user logs in (regardless of which machine they use).\n- **Linking:** A GPO must be linked to an AD container to take effect. A GPO can be linked to multiple containers; a container can have multiple GPOs linked.\n- **Inheritance:** GPOs apply in order from highest to lowest in the AD hierarchy — Site → Domain → OU → Child OU. Child settings inherit from parents but can override them.\n- **Processing Order (LSDOU):** Local → Site → Domain → OU. Policies applied later (closer to the object) win in case of conflict — unless Block Inheritance or Enforce is set.\n- **Enforce:** Prevents child OUs from blocking or overriding a parent GPO. Used for critical security policies.\n- **Block Inheritance:** Prevents a child OU from inheriting GPOs from parent containers.\n- **WMI Filters:** Conditions that control whether a GPO applies to a machine (e.g., only apply to Windows 11 machines, or only to laptops).\n- **Resultant Set of Policy (RSoP):** A tool for seeing the effective policy applied to a user or computer — essential for troubleshooting.\n- **`gpupdate /force`:** Command to immediately refresh Group Policy on a machine without waiting for the default refresh interval.\n- **`gpresult /r`:** Command to show the currently applied GPOs for the logged-in user and computer.\n\n## Why It Matters\nGroup Policy is foundational to Windows enterprise management. Every Windows administrator uses it to enforce security settings, manage software, and configure user environments. Understanding how GPOs are created, linked, inherited, and applied — and how to troubleshoot when they don't work as expected — is essential knowledge for helpdesk, sysadmin, and security roles. It is tested heavily on Microsoft certifications.\n\n## Related Topics\n- [[Active Directory]]\n- [[OU]]\n- [[Domain]]\n- [[Software Deployment]]\n- [[Default Groups]]\n- [[Windows Operating Systems]]"},{"id":"Terms and Concepts/Group Scope","title":"Group Scope","section":"Terms and Concepts","domain":"Security","description":"The property of an Active Directory group that defines where in the forest the group can be used to assign permissions and who can be a member.","tags":["IT","IT/IAM","Level/Intermediate"],"content":"# Group Scope\n\n> The property of an Active Directory group that defines where in the forest the group can be used to assign permissions and who can be a member.\n\n## Overview\nIn [[Active Directory]], groups are characterized by two properties: **type** (security or distribution) and **scope** (domain local, global, or universal). Group scope determines how broadly a group can be used — whether it's restricted to one domain, usable across domains, or forest-wide.\n\nUnderstanding scope is essential for correctly designing permission structures in multi-domain environments. Using the wrong scope can prevent permissions from working correctly or create excessive replication overhead.\n\nA common best practice in AD design is the **AGDLP** model: Add user **A**ccounts to **G**lobal groups, nest global groups into **D**omain **L**ocal groups, and assign **P**ermissions to domain local groups. This keeps the permission assignment layer consistent while organizing users at a meaningful level.\n\n## Key Concepts\n\n- **Domain Local Group:**\n  - Scope: Can only be used to assign permissions **within its own domain**.\n  - Membership: Can contain users, global groups, and universal groups from any domain in the forest; other domain local groups from the same domain.\n  - Best used: Assigning access to resources (file shares, printers) within the local domain.\n\n- **Global Group:**\n  - Scope: Can be used to assign permissions in **any domain in the forest**, but primarily used within its own domain.\n  - Membership: Can only contain users and other global groups from the **same domain**.\n  - Best used: Grouping users by role or function (e.g., \"Marketing Staff\").\n\n- **Universal Group:**\n  - Scope: Can be used to assign permissions anywhere in the **forest**.\n  - Membership: Can contain users, global groups, and universal groups from any domain in the forest.\n  - Best used: Forest-wide access spanning multiple domains. Stored in the [[Global Catalog]].\n  - Caution: Changes to universal group membership trigger [[Global Catalog]] replication — use sparingly and thoughtfully.\n\n- **AGDLP Best Practice:** User Accounts → Global Groups → Domain Local Groups → Permissions. Scales well in multi-domain environments.\n\n- **Security vs. Distribution:**\n  - **Security Groups:** Used for permissions and access control. Can also receive email.\n  - **Distribution Groups:** Email-only groups (e.g., for Exchange/Outlook mailing lists). Cannot be used for permissions.\n\n## Why It Matters\nIncorrect group scope configuration is a common source of permissions problems in enterprise AD environments. IT professionals managing AD must understand when to use each scope to ensure permissions work correctly — especially in multi-domain forests. AGDLP is a best practice cited in Microsoft certifications (AZ-800, MD-102) and encountered constantly in enterprise AD administration.\n\n## Related Topics\n- [[Groups]]\n- [[Active Directory]]\n- [[Domain]]\n- [[Forest]]\n- [[Access Control]]\n- [[Principle of least Privilege]]"},{"id":"Terms and Concepts/Groups","title":"Groups","section":"Terms and Concepts","domain":"Security","description":"Collections of user accounts, computers, and other objects in Active Directory that are managed together — used to simplify permission assignment and administration.","tags":["IT","IT/IAM","Level/Intermediate"],"content":"# Groups\n\n> Collections of user accounts, computers, and other objects in Active Directory that are managed together — used to simplify permission assignment and administration.\n\n## Overview\nGroups are one of the fundamental building blocks of user management in [[Active Directory]] and operating systems. Rather than assigning permissions and policies to each individual user or computer, administrators assign them to groups and then add users to appropriate groups. When a user's job changes, adjusting group membership automatically adjusts all their access — no need to individually modify dozens of permission entries.\n\nGroups exist at two levels: **local groups** (on individual machines, managed through Computer Management) and **domain groups** (in Active Directory, available to all domain-joined machines). Domain groups are far more powerful and are used in all enterprise environments.\n\n## Key Concepts\n\n- **Security Groups:** Used to assign permissions and access rights to resources. Adding a user to a security group grants them all permissions assigned to that group. Can also be used for email distribution.\n- **Distribution Groups:** Email-only groups (used in Exchange/Outlook for mailing lists). Cannot be used for file, folder, or resource permissions.\n- **[[Group Scope]]:** Each AD group has a scope — Domain Local, Global, or Universal — that determines where it can be used for permissions and who can be a member.\n- **Nested Groups:** A group can be a member of another group, inheriting its parent group's permissions. Enables hierarchical organization (e.g., \"IT Staff\" → \"IT Admins\" → specific resource permissions).\n- **[[Default Groups]]:** Built-in groups created automatically — Administrators, Users, Domain Admins, Schema Admins, etc. These have predefined permissions appropriate for common roles.\n- **Group Membership and Kerberos:** When a user logs in, their group memberships are included in their Kerberos ticket. Very large numbers of group memberships can cause token bloat — a practical issue in complex environments.\n- **`net localgroup` / `Get-ADGroup`:** Command-line tools for managing local and domain groups respectively.\n- **[[Principle of least Privilege]] with Groups:** Users should be members of only the groups necessary for their role. Excessive group membership is a security risk.\n\n## Why It Matters\nGroups are how enterprise permissions and access control are managed at scale. IT professionals create groups for new departments, add users to groups when they join teams, remove them when they leave, and audit group membership as part of security reviews. Proper group management is the foundation of least-privilege access control and is central to Windows administration, Active Directory design, and compliance auditing.\n\n## Related Topics\n- [[Active Directory]]\n- [[Group Scope]]\n- [[Default Groups]]\n- [[Local Groups]]\n- [[Group Policy]]\n- [[Access Control]]\n- [[Principle of least Privilege]]"},{"id":"Terms and Concepts/GUI","title":"GUI","section":"Terms and Concepts","domain":"Systems","description":"A visual interface that allows users to interact with a computer using graphical elements — windows, icons, menus, and buttons — rather than typed commands.","tags":["IT","IT/OS","Level/Foundational"],"content":"# GUI (Graphical User Interface)\n\n> A visual interface that allows users to interact with a computer using graphical elements — windows, icons, menus, and buttons — rather than typed commands.\n\n## Overview\nA Graphical User Interface (GUI) is the visual layer most users interact with on computers, phones, and tablets. Rather than typing text commands into a terminal, users click icons, drag windows, select from menus, and interact with buttons and forms. The operating system translates these visual interactions into the underlying system operations.\n\nGUIs made computing accessible to mainstream users who had no interest in learning command-line syntax. Windows, macOS, and modern Linux distributions all present GUIs as their primary interface. However, IT professionals routinely work with both GUIs and command-line interfaces ([[Terminal]], [[Powershell]], [[BASH]]) — recognizing when each is more efficient.\n\n## Key Concepts\n\n- **WIMP Paradigm:** The dominant GUI model — Windows, Icons, Menus, Pointer. Introduced by Xerox PARC, popularized by Apple Macintosh and Windows.\n- **Desktop Environment:** The GUI layer of an operating system — on Windows, this is Explorer; on macOS, the Finder; on Linux, options include GNOME, KDE, and others.\n- **CLI vs. GUI:** GUIs are intuitive and easy to learn; CLIs are faster for repetitive tasks, automatable, and available when GUI is unavailable (servers, recovery modes).\n- **Remote GUI:** Protocols like [[Remote Desktop|RDP]] (Windows Remote Desktop) and VNC transmit a graphical desktop session over a network, allowing remote administration through a GUI.\n- **GUI in IT Tools:** Many IT administration tools (Active Directory Users and Computers, SQL Server Management Studio, VMware vCenter) provide GUIs for managing complex systems.\n- **Resource Usage:** GUIs consume more CPU, RAM, and GPU resources than CLI. Servers often run without a GUI (\"headless\") to conserve resources.\n- **Accessibility:** GUIs can support accessibility features (screen readers, high contrast, keyboard navigation) that make computing accessible to users with disabilities.\n\n## Why It Matters\nIT professionals work with GUIs every day — in operating systems, management tools, and applications. Understanding GUI concepts helps when supporting users, configuring systems, and troubleshooting display or interface issues. Knowing when to use a GUI vs. CLI also improves efficiency — tasks that are repetitive or need to run on many machines are better suited to scripting than clicking through menus.\n\n## Related Topics\n- [[Operating System]]\n- [[Terminal]]\n- [[Remote Desktop]]\n- [[Powershell]]\n- [[BASH]]\n- [[Desktop]]"},{"id":"Terms and Concepts/Hardware","title":"Hardware","section":"Terms and Concepts","domain":"Hardware","description":"The physical, tangible components of a computer system — everything you can touch, including the processor, memory, storage, input/output devices, and circuit boards.","tags":["IT","IT/Hardware","Level/Foundational"],"content":"# Hardware\n\n> The physical, tangible components of a computer system — everything you can touch, including the processor, memory, storage, input/output devices, and circuit boards.\n\n## Overview\nHardware refers to the physical components that make up a computer or electronic device. Unlike [[Software]] (programs and data) which are intangible, hardware is the material substrate — the chips, circuits, drives, cables, and enclosures that physically implement computing.\n\nAll hardware components must work together as a system: the [[CPU]] processes instructions, [[RAM]] provides fast temporary storage, drives provide permanent storage, the [[Motherboard]] interconnects everything, the [[Power Supply]] provides regulated electricity, and input/output devices allow interaction. Understanding what each component does, how they connect, and how to diagnose failures is foundational IT knowledge.\n\n## Key Concepts\n\n- **[[CPU]] (Central Processing Unit):** The processor — executes instructions. The primary determinant of computational performance.\n- **[[RAM]] (Random Access Memory):** Fast, volatile temporary storage. Holds data the CPU is actively working with. Data is lost when power is cut.\n- **[[Storage]] (HDD/SSD):** Non-volatile permanent storage for the OS, applications, and data. HDDs use spinning magnetic platters; SSDs use flash memory.\n- **[[Motherboard]]:** The main circuit board connecting all components — CPU socket, RAM slots, PCIe slots for expansion, storage connectors, and I/O ports.\n- **[[GPU]] (Graphics Processing Unit):** Handles graphics rendering and parallel computing tasks. May be integrated (in the CPU) or discrete (a separate card).\n- **[[Power Supply]] (PSU):** Converts AC power from the wall to DC voltages needed by components. Must be sized appropriately for the system's power draw.\n- **Input Devices:** Keyboard, mouse, scanner, microphone, touchscreen — allow users to provide data to the computer.\n- **Output Devices:** Monitor, printer, speakers, projector — present processed information to users.\n- **Peripheral Devices:** External hardware connected to the computer — USB drives, external drives, printers, monitors.\n- **[[Drivers]]:** Software that allows the OS to communicate with specific hardware components.\n\n## Why It Matters\nHardware knowledge is the bedrock of IT support. Diagnosing a slow computer, replacing a failed drive, adding RAM to improve performance, or troubleshooting a display issue all require understanding hardware. Hardware is also the focus of CompTIA A+ certification — the entry point for IT careers — where candidates must demonstrate knowledge of PC components, mobile devices, printers, and peripherals.\n\n## Related Topics\n- [[CPU]]\n- [[RAM]]\n- [[Motherboard]]\n- [[SSD]]\n- [[HHD]]\n- [[Drivers]]\n- [[Computer]]"},{"id":"Terms and Concepts/Hashing","title":"Hashing","section":"Terms and Concepts","domain":"Networking","description":"A one-way cryptographic function that transforms input data of any size into a fixed-length string (the hash), used for data integrity verification, password storage, and digital signatures.","tags":["IT","IT/Security","Level/Intermediate"],"content":"# Hashing\n\n> A one-way cryptographic function that transforms input data of any size into a fixed-length string (the hash), used for data integrity verification, password storage, and digital signatures.\n\n## Overview\nHashing is a fundamental cryptographic concept that differs from [[Encryption]] in one critical way: it's **one-way**. You can hash data and get a hash value, but you cannot reverse a hash to recover the original data. This property makes hashing ideal for situations where you want to verify data without storing the data itself — like passwords.\n\nWhen you set a password, the system stores its hash. When you log in, it hashes what you typed and compares hashes — if they match, you're authenticated. The actual password is never stored, so a database breach exposing hashes doesn't directly expose passwords (though weak passwords can still be cracked via rainbow tables or brute force).\n\nHashing is also used to verify file integrity: a file's SHA-256 hash before and after transfer should be identical — any mismatch indicates corruption or tampering.\n\n## Key Concepts\n\n- **Hash Function:** An algorithm that takes input and produces a fixed-length output. MD5, SHA-1, SHA-256, SHA-3, bcrypt, and Argon2 are examples.\n- **Hash Value / Digest:** The output of the hash function — a fixed-length string (e.g., SHA-256 always produces 64 hex characters).\n- **One-Way Property:** Computationally infeasible to reverse. You cannot derive the input from the hash.\n- **Deterministic:** The same input always produces the same hash. This is what enables verification.\n- **Collision Resistance:** A good hash function rarely produces the same output for different inputs. MD5 and SHA-1 are no longer collision-resistant and are considered insecure for security-critical use.\n- **Avalanche Effect:** A tiny change in input produces a completely different hash. `\"hello\"` and `\"Hello\"` produce radically different SHA-256 values.\n- **Salt:** Random data added to input before hashing — prevents precomputed rainbow table attacks. Essential for password hashing.\n- **Rainbow Table Attack:** A precomputed table of hash values for common passwords. Defeated by salting.\n- **Password Hashing Algorithms:** bcrypt, Argon2, and scrypt are purpose-built for passwords — they are deliberately slow to make brute-force attacks impractical.\n- **File Integrity:** Hashing a file produces a checksum — comparing it to a known-good hash verifies the file hasn't been altered.\n\n## Common Hash Algorithms\n\n| Algorithm | Output Size | Status |\n|-----------|------------|--------|\n| MD5 | 128-bit | Insecure (collisions known) |\n| SHA-1 | 160-bit | Insecure (deprecated) |\n| SHA-256 | 256-bit | Secure, widely used |\n| SHA-3 | Variable | Secure, newer standard |\n| bcrypt | Variable | Recommended for passwords |\n\n## Why It Matters\nHashing is involved in password security, file integrity verification, digital signatures, [[Blockchain]] technology, and forensic evidence preservation ([[Chain of Custody]]). IT professionals must understand when to use hashing vs. encryption, which hash algorithms are secure, and why password storage must use salted, slow hash functions rather than simple MD5.\n\n## Related Topics\n- [[Encryption]]\n- [[Password]]\n- [[Digital Forensics]]\n- [[Chain of Custody]]\n- [[Blockchain]]\n- [[CIA Triad]]\n- [[SHA]]"},{"id":"Terms and Concepts/HHD","title":"HHD","section":"Terms and Concepts","domain":"Hardware","description":"A magnetic storage device that uses spinning platters and read/write heads to store and retrieve data — the traditional, mechanical storage medium in computers.","tags":["IT","IT/Hardware","Level/Foundational"],"content":"# HDD (Hard Disk Drive)\n\n> A magnetic storage device that uses spinning platters and read/write heads to store and retrieve data — the traditional, mechanical storage medium in computers.\n\n## Overview\nA Hard Disk Drive (HDD) is the traditional mass storage technology that has been the primary storage medium in computers since the 1950s. Data is stored magnetically on spinning platters coated with ferromagnetic material. Read/write heads float micrometers above the spinning surface, reading and writing data as the platter rotates beneath them.\n\nHDDs are being rapidly displaced by [[SSD|Solid State Drives (SSDs)]] in laptops and desktops due to SSDs' dramatically higher speed, lower power consumption, and better shock resistance. However, HDDs remain relevant as cost-effective, high-capacity storage — particularly for bulk data storage, NAS devices, backup systems, and data centers where cost per terabyte matters more than performance.\n\n## Key Concepts\n\n- **Platters:** Circular disks coated with magnetic material. Most modern HDDs have 2–5 platters. Data is stored in concentric tracks on each platter surface.\n- **Read/Write Heads:** Tiny electromagnetic components on actuator arms that read and write data by detecting and altering magnetic patterns on the platters.\n- **RPM (Revolutions Per Minute):** The speed at which platters spin. Common speeds: 5,400 RPM (laptop/economy), 7,200 RPM (standard desktop), 10,000–15,000 RPM (enterprise/server).\n- **Seek Time:** The time it takes for the read/write head to position over the correct track. A key performance limitation of HDDs vs. SSDs.\n- **SATA Interface:** The most common HDD connection standard — SATA III supports up to 600 MB/s. Enterprise drives also use SAS (Serial Attached SCSI).\n- **Cache (Buffer):** A small amount of fast DRAM on the HDD that buffers frequently accessed data, improving performance.\n- **Fragmentation:** Over time, files become stored in non-contiguous blocks on the platter, increasing seek time. Defragmentation reorganizes data for better performance.\n- **HDD vs. SSD:** SSDs have no moving parts, are 5–10x faster for random access, more shock-resistant, quieter, and consume less power — but cost more per GB. HDDs win on cost per terabyte for large-capacity storage.\n\n## Why It Matters\nHDDs remain a major part of enterprise storage infrastructure, especially for bulk data, backups, and NAS systems. IT professionals must understand HDD characteristics when selecting storage for different use cases — database servers need fast SSDs; archive storage benefits from HDD cost-efficiency. Knowing failure modes (clicking sounds, SMART errors) and understanding the HDD vs. SSD trade-off are practical helpdesk and sysadmin skills.\n\n## Related Topics\n- [[SSD]]\n- [[Storage]]\n- [[NAS]]\n- [[RAID]]\n- [[Backups]]\n- [[DAS]]"},{"id":"Terms and Concepts/HIPAA","title":"HIPAA","section":"Terms and Concepts","domain":"Security","description":"A U.S. federal law establishing national standards to protect individuals' medical information (PHI) and requiring healthcare organizations to implement privacy and security safeguards.","tags":["IT","IT/Compliance","Level/Intermediate"],"content":"# HIPAA (Health Insurance Portability and Accountability Act)\n\n> A U.S. federal law establishing national standards to protect individuals' medical information (PHI) and requiring healthcare organizations to implement privacy and security safeguards.\n\n## Overview\nHIPAA (1996) sets the rules for protecting Protected Health Information (PHI) — any information that can identify an individual and relates to their health condition, healthcare treatment, or payment for healthcare. It applies to **covered entities** (healthcare providers, health plans, healthcare clearinghouses) and their **business associates** (vendors and partners who handle PHI on their behalf).\n\nFor IT professionals, HIPAA is significant because electronic PHI (ePHI) is subject to the Security Rule — specific technical, physical, and administrative safeguards must be implemented for any system that stores, processes, or transmits health information. IT departments in healthcare settings spend considerable effort ensuring HIPAA compliance.\n\n## Key Concepts\n\n- **PHI (Protected Health Information):** Any individually identifiable health information — medical records, lab results, billing information, diagnoses, prescriptions — whether in paper, electronic, or oral form.\n- **ePHI:** Electronic PHI — PHI stored or transmitted electronically. Subject to the HIPAA Security Rule.\n- **Privacy Rule:** Establishes who can access PHI and for what purposes. Gives patients rights to access, amend, and get an accounting of disclosures of their records.\n- **Security Rule:** Requires covered entities to implement administrative, physical, and technical safeguards for ePHI. Technical safeguards include access controls, audit controls, [[Encryption]], and automatic logoff.\n- **Breach Notification Rule:** Requires notification of affected individuals, HHS, and sometimes the media when unsecured PHI is breached. Major breaches (500+ individuals) must be reported to HHS immediately.\n- **Business Associate Agreement (BAA):** A required contract between a covered entity and any vendor that handles PHI, specifying the vendor's obligations to protect the data.\n- **Minimum Necessary Standard:** Use or disclose only the minimum PHI necessary for a given purpose.\n- **Penalties:** Range from $100 to $50,000 per violation, up to $1.9 million per violation category per year. Criminal penalties also apply for intentional violations.\n\n## Why It Matters\nHIPAA compliance is non-negotiable for any organization handling health data. IT professionals working in healthcare, health insurance, or any organization that handles medical data must understand HIPAA requirements — particularly the Security Rule's technical controls (encryption, access logging, user authentication). Misconfigured systems, insufficient access controls, or failure to encrypt ePHI regularly result in costly HIPAA violations.\n\n## Related Topics\n- [[Data Privacy Laws]]\n- [[PII]]\n- [[Encryption]]\n- [[Access Control]]\n- [[Auditing]]\n- [[Data Breach]]\n- [[CIA Triad]]"},{"id":"Terms and Concepts/Honeypots","title":"Honeypots","section":"Terms and Concepts","domain":"Security","description":"Decoy systems or resources deliberately designed to attract and detect attackers, allowing security teams to observe attack techniques, gather threat intelligence, and divert threats from production systems.","tags":["IT","IT/Security","Level/Advanced"],"content":"# Honeypots\n\n> Decoy systems or resources deliberately designed to attract and detect attackers, allowing security teams to observe attack techniques, gather threat intelligence, and divert threats from production systems.\n\n## Overview\nA honeypot is a controlled security trap — a fake system, service, or resource set up specifically to lure attackers. Because legitimate users have no reason to interact with a honeypot, any access to it is inherently suspicious and likely malicious. This makes honeypots powerful for detecting scanning, unauthorized access attempts, and malware propagation.\n\nUnlike traditional security controls (firewalls, IDS) that try to block threats, honeypots are passive traps that let attackers proceed while observing their methods. The intelligence gathered — what tools they use, how they move laterally, what they're looking for — can inform defensive improvements across the real environment.\n\nHoneypots range from simple (a fake user account or file share) to elaborate (full operating systems with intentional vulnerabilities). A collection of interconnected honeypots is called a **honeynet**.\n\n## Key Concepts\n\n- **Low-Interaction Honeypot:** Simulates only limited services or protocols — emulates open ports and returns fake responses. Easier to deploy and manage; less realistic. Good for detecting automated scanning.\n- **High-Interaction Honeypot:** A fully functioning system with real OS and applications. Provides deep insight into attacker behavior but is harder to manage and carries more risk if the attacker breaks containment.\n- **Honeynet:** A network of multiple honeypots, designed to simulate a realistic environment and capture complex multi-stage attacks.\n- **Honey Token:** A fake piece of data (fake credential, fake document, fake API key) placed where it would only be accessed by an attacker. If the token is used, an alert fires.\n- **Canary Token:** A type of honey token that triggers an alert when accessed — a link, a document, a DNS name that \"calls home\" when opened.\n- **Threat Intelligence:** Honeypots are valuable for capturing zero-day exploits, new malware, and attack techniques that haven't been documented elsewhere.\n- **Deception Technology:** The broader category of security tools that use deception — honeypots, honey tokens, fake credentials — to detect and delay attackers.\n- **Legal and Ethical Considerations:** Honeypots must be properly isolated to prevent them from being used to attack others. Entrapment concerns also exist for law enforcement scenarios.\n\n## Why It Matters\nHoneypots represent a fundamentally different approach to security: instead of pure defense, they gather intelligence on attackers. IT security professionals should understand honeypots as both a detection tool and a source of threat intelligence. They are particularly valuable for detecting insider threats (honey tokens), reconnaissance activity, and previously unknown attack methods.\n\n## Related Topics\n- [[DNS Sinkhole]]\n- [[IDS]]\n- [[CyberOps]]\n- [[Digital Forensics]]\n- [[Logging]]\n- [[Cyber Attacks]]"},{"id":"Terms and Concepts/host","title":"host","section":"Terms and Concepts","domain":"Networking","description":"A host is any device connected to a network that can send and receive data — including computers, servers, printers, smartphones, and IoT devices.","tags":["IT","IT/Networking","Level/Foundational"],"content":"# Host\n\n> A host is any device connected to a network that can send and receive data — including computers, servers, printers, smartphones, and IoT devices.\n\n## Overview\n\nIn networking, a \"host\" refers to any device that participates in network communication. Every host has at least one network interface and a unique IP address that identifies it on the network. Hosts can initiate communication (as clients), respond to requests (as servers), or do both depending on the context.\n\nThe term is broad and context-dependent. In virtualization, \"host\" refers specifically to the physical machine running a hypervisor. In web hosting, \"host\" refers to a server delivering web content. In networking generally, any network-connected device is a host.\n\n## Key Concepts\n\n- **IP Address**: Each host is assigned a unique IP address that identifies it on the network. This is how other devices find and route traffic to it. See [[IP Address]].\n- **MAC Address**: A hardware-level identifier assigned to the network interface card (NIC). Used for communication within a local network segment.\n- **Hostname**: A human-readable name (e.g., `server01`, `laptop-ryan`) mapped to an IP address via DNS or a hosts file.\n- **Hosts File**: A local text file on each OS (`/etc/hosts` on Linux/macOS, `C:\\Windows\\System32\\drivers\\etc\\hosts` on Windows) that maps hostnames to IP addresses, bypassing DNS.\n- **Client vs. Server**: A host acting as a client initiates requests; a host acting as a server responds to them. Many hosts can do both.\n- **Loopback Address**: `127.0.0.1` (IPv4) or `::1` (IPv6) — a special address that refers to the host itself, used for testing and local communication.\n\n## Why It Matters\n\nUnderstanding what a host is, how it's identified (IP address, MAC address, hostname), and how hosts communicate is foundational networking knowledge. Every networking concept — routing, DNS, firewalls, VLANs — revolves around how hosts are identified and how traffic moves between them. This is core content for CompTIA A+, Network+, and any IT fundamentals course.\n\n## Related Topics\n\n- [[IP Address]]\n- [[DNS]]\n- [[MAC]]\n- [[Network Layer]]\n- [[Client Server Model]]\n- [[Internet Protocol (IP)]]"},{"id":"Terms and Concepts/Hot Storage","title":"Hot Storage","section":"Terms and Concepts","domain":"Cloud","description":"The highest-performance storage tier, designed for data that is accessed frequently and requires immediate, low-latency retrieval.","tags":["IT","IT/Cloud","Level/Foundational"],"content":"# Hot Storage\n\n> The highest-performance storage tier, designed for data that is accessed frequently and requires immediate, low-latency retrieval.\n\n## Overview\nHot storage sits at the top of the storage tier pyramid — it provides the fastest possible access to data, typically using NVMe SSDs, all-flash arrays, or high-speed in-memory storage. It is the most expensive storage tier per gigabyte, but essential for workloads where performance matters most.\n\nIn cloud environments, hot storage corresponds to tiers like AWS S3 Standard, Azure Hot Blob Storage, or provisioned IOPS SSD volumes — where data retrieval is immediate and costs are higher per GB but with no retrieval fees.\n\nHot storage is appropriate for databases, active application data, operating system volumes, frequently accessed files, and real-time analytics. Data that's accessed less frequently should be tiered to [[Warm Storage]] or [[Cold Storage]] to reduce costs.\n\n## Key Concepts\n\n- **NVMe SSD:** The primary hot storage technology for local systems. NVMe SSDs operate at 5–7+ GB/s sequential read speeds — far faster than traditional SATA SSDs or HDDs.\n- **All-Flash Array (AFA):** Enterprise storage systems built entirely from flash (SSD) storage, providing consistently low latency and high IOPS for critical workloads.\n- **IOPS (Input/Output Operations Per Second):** The key performance metric for storage. Databases and transactional systems require high IOPS. Hot storage provides orders of magnitude more IOPS than cold storage.\n- **In-Memory Storage:** The hottest possible storage — data lives in RAM. Used for caching, session storage, and real-time data (Redis, Memcached).\n- **Storage Tiering:** Organizations automatically move data between hot, warm, and cold tiers based on access frequency — keeping active data fast and archiving inactive data cheaply.\n- **Cloud Hot Tier:** AWS S3 Standard, Azure Blob Hot, Google Cloud Standard Storage — designed for frequently accessed data with immediate retrieval and higher per-GB cost.\n- **Latency:** Hot storage is characterized by microsecond to low-millisecond latency. Cold storage may require seconds to hours for retrieval.\n\n## Why It Matters\nSelecting the right storage tier directly impacts both application performance and cost. Overspending on hot storage for infrequently accessed data wastes money; under-provisioning hot storage for active workloads causes performance degradation. IT professionals responsible for storage architecture, database performance, or cloud cost optimization must understand the hot/warm/cold tier model and how to align data placement with access patterns.\n\n## Related Topics\n- [[Warm Storage]]\n- [[Cold Storage]]\n- [[Storage]]\n- [[SSD]]\n- [[Cloud Storage]]\n- [[Backups]]"},{"id":"Terms and Concepts/HTML","title":"HTML","section":"Terms and Concepts","domain":"Networking","description":"The standard markup language used to create and structure the content of web pages — defining headings, paragraphs, links, images, and other elements that browsers render as web pages.","tags":["IT","IT/Scripting","Level/Foundational"],"content":"# HTML (Hypertext Markup Language)\n\n> The standard markup language used to create and structure the content of web pages — defining headings, paragraphs, links, images, and other elements that browsers render as web pages.\n\n## Overview\nHTML (HyperText Markup Language) is the foundational language of the web. Every web page you visit is built on HTML. It tells the browser what content to display and how it's structured — this is a heading, this is a paragraph, this image goes here, this text links to another page.\n\nHTML uses **tags** (enclosed in angle brackets like `<p>`, `<h1>`, `<a>`) to mark up content. Tags generally come in pairs — an opening tag and a closing tag — with content between them. HTML alone controls structure; **CSS** handles visual styling and **JavaScript** adds interactivity.\n\nFor IT professionals, understanding HTML is useful for troubleshooting web applications, understanding how web content is structured, reading source code, and basic web administration tasks.\n\n## Key Concepts\n\n- **Tags:** Instructions for the browser surrounded by `<` and `>`. Most tags have opening (`<p>`) and closing (`</p>`) forms, with content between them.\n- **Elements:** A complete unit: opening tag + content + closing tag. `<h1>Title</h1>` is an `h1` element.\n- **Attributes:** Additional information inside an opening tag. `<a href=\"https://example.com\">Link</a>` — `href` is an attribute.\n- **Document Structure:** Every HTML page has the same basic structure: `<!DOCTYPE html>`, `<html>`, `<head>` (metadata), and `<body>` (visible content).\n- **Semantic HTML:** Using tags that convey meaning — `<nav>` for navigation, `<article>` for articles, `<footer>` for footers — rather than generic `<div>` tags for everything.\n- **Forms:** HTML provides form elements (`<input>`, `<select>`, `<button>`) that capture user input — used for login screens, search boxes, and data entry.\n- **Links and Anchors:** `<a href=\"url\">` creates hyperlinks — the fundamental connection mechanism of the web.\n- **HTML5:** The current HTML standard, adding semantic elements, native video/audio support, and APIs for advanced web functionality without plugins.\n\n## Example Structure\n\n```html\n<!DOCTYPE html>\n<html>\n  <head>\n    <title>Page Title</title>\n  </head>\n  <body>\n    <h1>Heading</h1>\n    <p>Paragraph text with a <a href=\"https://example.com\">link</a>.</p>\n    <img src=\"image.jpg\" alt=\"Description\">\n  </body>\n</html>\n```\n\n## Why It Matters\nHTML is the building block of every web application and website. IT professionals working in web support, helpdesk for web-based tools, or security (identifying XSS vulnerabilities, reading source code) need basic HTML literacy. It also helps when troubleshooting \"the page looks broken\" issues — knowing what HTML looks like helps distinguish content problems from server problems.\n\n## Related Topics\n- [[JavaScript]]\n- [[Web Server]]\n- [[HTTP & HTTPS]]\n- [[Application Layer]]\n- [[Software]]"},{"id":"Terms and Concepts/HTTP & HTTPS","title":"HTTP & HTTPS","section":"Terms and Concepts","domain":"Networking","description":"The communication protocols used to transfer data between web browsers and web servers — HTTP in plaintext, HTTPS with TLS encryption.","tags":["IT","IT/Networking","Level/Foundational"],"content":"# HTTP & HTTPS\n\n> The communication protocols used to transfer data between web browsers and web servers — HTTP in plaintext, HTTPS with TLS encryption.\n\n## Overview\nHTTP (HyperText Transfer Protocol) is the foundation of data exchange on the web. When you type a URL and press Enter, your browser sends an HTTP request to a web server, which responds with the requested content (HTML, images, data). HTTP defines the format of these requests and responses — methods like GET, POST, PUT, and DELETE, along with status codes (200 OK, 404 Not Found, 500 Server Error).\n\nHTTPS (HTTP Secure) is HTTP with an added layer of [[TLS]] encryption. The \"S\" means the connection between browser and server is encrypted — no one intercepting the traffic can read the content or tamper with it. HTTPS is now the standard for all websites, required by browsers (which mark HTTP sites as \"Not Secure\"), search engines, and regulatory frameworks.\n\nHTTP operates on port 80; HTTPS on port 443.\n\n## Key Concepts\n\n- **HTTP Methods:**\n  - **GET:** Retrieve a resource (viewing a page, loading an image).\n  - **POST:** Send data to the server (submitting a form, login).\n  - **PUT:** Update a resource.\n  - **DELETE:** Remove a resource.\n- **Status Codes:**\n  - **2xx (Success):** 200 OK, 201 Created\n  - **3xx (Redirect):** 301 Moved Permanently, 302 Found\n  - **4xx (Client Error):** 400 Bad Request, 401 Unauthorized, 403 Forbidden, 404 Not Found\n  - **5xx (Server Error):** 500 Internal Server Error, 502 Bad Gateway\n- **[[TLS]] (Transport Layer Security):** The encryption layer in HTTPS. Provides confidentiality, integrity, and server authentication through digital certificates.\n- **SSL Certificate:** The digital certificate that proves a server's identity and enables HTTPS. Issued by a Certificate Authority (CA). Contains the server's public key.\n- **HTTP/2 and HTTP/3:** Modern versions of HTTP with improved performance — multiplexing (multiple requests over one connection), header compression, and HTTP/3's use of QUIC (UDP-based) instead of TCP.\n- **Cookies:** Small pieces of data the server sends to the browser to maintain session state (e.g., login status). Travel with HTTP requests.\n- **HSTS (HTTP Strict Transport Security):** A security policy that tells browsers to only ever connect via HTTPS, preventing SSL stripping attacks.\n\n## Why It Matters\nHTTP/HTTPS is the protocol of the web — understanding it is fundamental for IT support (troubleshooting web access), web administration (configuring web servers and certificates), security (recognizing HTTP vs. HTTPS risks, understanding SSL certificate errors), and networking (port 80/443 firewall rules). Every IT professional encounters HTTP and HTTPS daily.\n\n## Related Topics\n- [[TLS]]\n- [[SSL]]\n- [[Web Server]]\n- [[DNS]]\n- [[Common Ports]]\n- [[Encryption]]\n- [[Application Layer]]"},{"id":"Terms and Concepts/Hybrid Cloud","title":"Hybrid Cloud","section":"Terms and Concepts","domain":"Networking","description":"A cloud computing model that combines on-premises infrastructure (or a private cloud) with public cloud services, allowing data and applications to move between them.","tags":["IT","IT/Cloud","Level/Intermediate"],"content":"# Hybrid Cloud\n\n> A cloud computing model that combines on-premises infrastructure (or a private cloud) with public cloud services, allowing data and applications to move between them.\n\n## Overview\nHybrid cloud is a deployment strategy that bridges an organization's private infrastructure with one or more public clouds. Rather than choosing exclusively between on-premises and cloud, hybrid cloud allows organizations to keep sensitive or latency-sensitive workloads on-premises while bursting into the cloud for scalability, DR, or cost optimization.\n\nThe key requirement for hybrid cloud is **connectivity and integration** — on-premises and cloud environments must be able to exchange data and workloads securely. This is typically achieved through dedicated network connections (AWS Direct Connect, Azure ExpressRoute) and management platforms (Azure Arc, Google Anthos, VMware Cloud Foundation) that provide a consistent operational layer across environments.\n\nMost large enterprises use hybrid cloud — not because they can't move fully to the cloud, but because some workloads (regulated data, legacy applications, low-latency manufacturing systems) are better or required to stay on-premises.\n\n## Key Concepts\n\n- **On-Premises Component:** The organization's own data center or [[Private Cloud]]. Houses sensitive data, legacy systems, or workloads with strict latency requirements.\n- **[[Public Cloud]] Component:** [[AWS]], [[Azure]], [[GCP]], or other public cloud — provides elastic compute, managed services, and geographic reach.\n- **Workload Portability:** The ability to run or migrate workloads between on-premises and cloud environments. Enabled by containerization ([[Containers]]), [[Virtualization]], and standardized APIs.\n- **Cloud Bursting:** During peak demand, workloads automatically scale out to the public cloud, then scale back in when demand subsides.\n- **[[Disaster Recovery]] (DR):** A common hybrid use case — keep primary systems on-premises, replicate to the cloud, and failover to cloud DR if on-premises fails.\n- **Data Sovereignty:** Some regulations require data to remain in specific geographic locations — hybrid cloud allows sensitive data to stay on-premises in compliant facilities while using cloud for non-regulated workloads.\n- **Management Complexity:** Hybrid cloud is more complex to operate than a single environment — requires skills, tooling, and processes that span both on-premises and cloud.\n\n## Why It Matters\nHybrid cloud is the reality for most enterprise organizations. IT professionals must understand hybrid architectures to design connectivity between environments, troubleshoot cross-environment issues, manage identity across on-premises AD and cloud IAM, and implement security controls that span both worlds. Cloud migration isn't all-or-nothing — hybrid is the practical middle ground for most large organizations.\n\n## Related Topics\n- [[Cloud Computing]]\n- [[Public Cloud]]\n- [[Private Cloud]]\n- [[AWS]]\n- [[Azure]]\n- [[Disaster Recovery]]\n- [[Virtualization]]"},{"id":"Terms and Concepts/Hypervisor","title":"Hypervisor","section":"Terms and Concepts","domain":"Networking","description":"Software that creates and manages virtual machines by abstracting physical hardware resources and allocating them across multiple isolated guest operating systems.","tags":["IT","IT/Virtualization","Level/Intermediate"],"content":"# Hypervisor\n\n> Software that creates and manages virtual machines by abstracting physical hardware resources and allocating them across multiple isolated guest operating systems.\n\n## Overview\nA hypervisor — also called a Virtual Machine Monitor (VMM) — is the core software component that makes [[Virtualization]] possible. It sits between the physical hardware and the [[Virtual Machines]] (VMs) running on top of it, coordinating which VM gets access to the CPU, memory, storage, and network at any given moment.\n\nThere are two major types. A **Type 1 (bare-metal) hypervisor** runs directly on the hardware with no host OS underneath — this is the enterprise standard because it's faster and more secure. Examples include VMware ESXi, Microsoft Hyper-V, and Citrix XenServer. A **Type 2 (hosted) hypervisor** runs on top of an existing operating system, making it easy to install on a regular workstation. Examples include Oracle VirtualBox and VMware Workstation — common for labs, development, and testing.\n\nHypervisors enforce strong isolation between VMs: a crash or compromise in one VM does not affect the others. This isolation, combined with features like live migration and snapshots, makes hypervisors central to modern data center operations.\n\n## Key Concepts\n\n- **Type 1 (Bare-Metal):** Runs directly on hardware; used in production environments. Examples: VMware ESXi, Hyper-V.\n- **Type 2 (Hosted):** Runs on a host OS; used for development and labs. Examples: VirtualBox, VMware Workstation.\n- **Hardware Abstraction:** The hypervisor presents virtualized hardware to each VM, so a VM doesn't know (or care) what physical hardware it's on.\n- **Resource Allocation:** CPU time, RAM, storage, and network bandwidth are divided among VMs based on configured limits and priorities.\n- **Isolation:** Each VM is sandboxed — a compromise in one VM doesn't directly affect others.\n- **Snapshots:** Point-in-time captures of a VM's state, allowing rollback if something goes wrong.\n- **Live Migration:** Moving a running VM from one physical host to another without downtime — critical for maintenance and load balancing.\n- **Hardware Virtualization Extensions:** Modern CPUs include Intel VT-x or AMD-V instructions that accelerate hypervisor operations.\n\n## Why It Matters\nHypervisors are the foundation of modern cloud computing and enterprise infrastructure. Understanding the difference between Type 1 and Type 2, how resources are allocated, and how VMs are isolated is essential for any IT role touching servers, cloud platforms, or virtualized environments. Skills with hypervisors like Hyper-V or VirtualBox are directly testable on CompTIA A+, Network+, and Server+ exams.\n\n## Related Topics\n- [[Virtualization]]\n- [[Virtual Machines]]\n- [[Containers]]\n- [[Cloud Computing]]\n- [[Virtualization vs Containerization]]\n- [[Server]]"},{"id":"Terms and Concepts/IaaS","title":"IaaS","section":"Terms and Concepts","domain":"Networking","description":"A cloud computing model where a provider supplies virtualized compute, storage, and networking resources over the internet, and customers manage everything from the OS up.","tags":["IT","IT/Cloud","Level/Intermediate"],"content":"# IaaS (Infrastructure as a Service)\n\n> A cloud computing model where a provider supplies virtualized compute, storage, and networking resources over the internet, and customers manage everything from the OS up.\n\n## Overview\nIaaS is the most foundational layer of cloud computing. The cloud provider owns and operates the physical hardware — servers, storage systems, networking equipment, and data centers — and exposes it as on-demand virtual resources. Customers rent what they need (virtual machines, storage volumes, network bandwidth) and pay only for what they use.\n\nThe key characteristic of IaaS is the **division of responsibility**: the provider handles the physical infrastructure and virtualization layer; the customer controls the operating system, applications, and data. This gives customers maximum flexibility — you can run any OS, install any software, and configure the environment however you need — without buying or maintaining hardware.\n\nMajor IaaS providers include AWS (EC2, S3), Microsoft Azure (Virtual Machines, Blob Storage), and Google Cloud (Compute Engine). IaaS is commonly used for development/test environments, web hosting, big data processing, and disaster recovery.\n\n## Key Concepts\n\n- **Virtual Machines:** The core IaaS resource — virtualized servers you can spin up, configure, and scale on demand.\n- **Block/Object Storage:** Persistent storage services (like AWS S3 or Azure Blob) for storing data independent of VM lifecycle.\n- **Networking:** IaaS includes virtual networks, subnets, load balancers, and VPN gateways — all software-defined.\n- **Pay-as-You-Go:** You pay for compute and storage hours consumed, not fixed hardware costs.\n- **Scalability:** Resources can be added or removed quickly — scale up for a traffic spike, scale down to save cost.\n- **Shared Responsibility Model:** Provider secures the physical infrastructure; customer secures the OS, applications, and data.\n- **[[Virtualization]]:** The hypervisor layer makes IaaS possible by abstracting physical hardware into on-demand virtual resources.\n\n## Why It Matters\nIaaS is one of the three primary cloud service models (alongside [[PaaS]] and [[SaaS]]) tested on CompTIA Cloud+, Security+, and cloud vendor certifications. Understanding what the customer is responsible for vs. the provider — the shared responsibility model — is essential for secure cloud deployments. IaaS is the foundation of most enterprise cloud strategies.\n\n## Related Topics\n- [[Cloud Computing]]\n- [[PaaS]]\n- [[SaaS]]\n- [[Xaas]]\n- [[Virtualization]]\n- [[AWS]]\n- [[Azure]]"},{"id":"Terms and Concepts/Identity Mangement","title":"Identity Mangement","section":"Terms and Concepts","domain":"Security","description":"The policies, processes, and technologies used to manage digital identities and control what users can access within an organization.","tags":["IT","IT/IAM","Level/Intermediate"],"content":"# Identity Management\n\n> The policies, processes, and technologies used to manage digital identities and control what users can access within an organization.\n\n## Overview\nIdentity Management (IDM) — often called Identity and Access Management (IAM) — is the discipline of ensuring that the right people have the right access to the right resources at the right time. It covers everything from creating user accounts when someone joins an organization to removing access when they leave, and everything in between.\n\nAt its core, IAM connects three things: **who you are** (identity), **how you prove it** (authentication), and **what you're allowed to do** (authorization). In modern organizations, these functions are managed through IAM platforms (like Microsoft Entra ID, formerly Azure AD, or Okta) that centralize user provisioning, enforce access policies, and support features like Single Sign-On and Multi-Factor Authentication.\n\nIdentity management is directly tied to security and compliance. Improperly managed identities — like orphaned accounts from former employees or users with excessive privileges — are a leading cause of data breaches and insider threats.\n\n## Key Concepts\n\n- **User Provisioning:** Creating, modifying, and deactivating user accounts across systems based on the user's role and status. Often automated through HR system integrations.\n- **[[Authentication]]:** Verifying who a user claims to be — passwords, [[MFA]], biometrics, etc.\n- **Authorization:** Determining what an authenticated user is allowed to access, based on roles and permissions.\n- **[[SSO]] (Single Sign-On):** Allows users to authenticate once and access multiple systems without re-entering credentials.\n- **[[MFA]] (Multi-Factor Authentication):** Requires two or more verification factors to authenticate — significantly hardens security.\n- **[[Principle of least Privilege]]:** Users should have only the minimum access needed for their job — a core IAM principle.\n- **Identity Lifecycle Management:** Managing identities through their full lifecycle — onboarding, role changes, offboarding.\n- **Identity Federation:** Allows identities from one organization to be trusted by another (e.g., logging into a partner portal with your company credentials via SAML or [[OAuth]]).\n- **IAM Systems:** Platforms like Microsoft Entra ID, Okta, or AWS IAM that centralize identity management operations.\n\n## Why It Matters\nIAM is one of the most important areas of enterprise security. Weak identity management — such as shared accounts, over-privileged users, or unrevoked access — creates serious vulnerabilities. Understanding provisioning, authentication, authorization, and access governance is tested on CompTIA Security+ and is essential for IT, security, and cloud roles.\n\n## Related Topics\n- [[Authentication]]\n- [[MFA]]\n- [[SSO]]\n- [[Active Directory]]\n- [[Principle of least Privilege]]\n- [[OAuth]]"},{"id":"Terms and Concepts/IDS","title":"IDS","section":"Terms and Concepts","domain":"Networking","description":"A security tool that monitors network traffic or system activity and generates alerts when suspicious or potentially malicious behavior is detected.","tags":["IT","IT/Security","Level/Intermediate"],"content":"# Intrusion Detection System (IDS)\n\n> A security tool that monitors network traffic or system activity and generates alerts when suspicious or potentially malicious behavior is detected.\n\n## Overview\nAn Intrusion Detection System (IDS) is a passive security monitoring tool — it watches, analyzes, and alerts, but does not block traffic on its own. It sits on the network or on individual hosts, continuously inspecting traffic and logs for signs of attack, policy violations, or unusual behavior.\n\nIDS can be deployed at two levels: a **Network IDS (NIDS)** monitors traffic across the entire network, while a **Host-based IDS (HIDS)** monitors activity on a specific device. Many organizations use both in combination. When an IDS detects something suspicious, it logs the event and sends an alert to administrators or a Security Operations Center (SOC) for investigation.\n\nThe key distinction between IDS and [[IPS|IPS (Intrusion Prevention System)]] is that an IDS only detects and reports — it does not automatically block or prevent the activity. This makes IDS valuable for visibility and forensics, but it requires human response to act on what it finds.\n\n## Key Concepts\n\n- **Signature-Based Detection:** Compares traffic against a database of known attack patterns. Fast and reliable for known threats, but blind to new or unknown attacks.\n- **Anomaly-Based Detection:** Establishes a baseline of normal behavior and alerts on deviations. Can detect novel attacks, but may produce false positives.\n- **NIDS (Network IDS):** Deployed at network choke points (e.g., near the firewall) to inspect traffic flowing across the network.\n- **HIDS (Host IDS):** Installed on individual endpoints; monitors system calls, log files, file integrity, and local activity.\n- **Alerts and Logging:** IDS output is typically fed into a SIEM (Security Information and Event Management) system for correlation and review.\n- **False Positives:** Legitimate traffic flagged as malicious — a common challenge in tuning IDS systems.\n\n## Why It Matters\nIDS is a foundational concept in cybersecurity. Understanding the difference between detection and prevention, signature vs. anomaly-based methods, and network vs. host-based deployment is tested on CompTIA Security+ and is essential for any security operations or sysadmin role. Even in environments with strong preventive controls, IDS provides critical visibility into what's happening on the network.\n\n## Related Topics\n- [[IPS]]\n- [[NIDS]]\n- [[NIPS]]\n- [[Firewalls]]\n- [[Network Traffic]]\n- [[Security Assessments]]"},{"id":"Terms and Concepts/Imaging","title":"Imaging","section":"Terms and Concepts","domain":"Networking","description":"In IT, the process of creating or deploying a complete copy of an operating system and its configuration to a computer — used for rapid deployment, system recovery, and standardized workstation setup.","tags":["IT","IT/OS","Level/Intermediate"],"content":"# Imaging\n\n> In IT, the process of creating or deploying a complete copy of an operating system and its configuration to a computer — used for rapid deployment, system recovery, and standardized workstation setup.\n\n## Overview\nIn the IT context, \"imaging\" specifically refers to **OS imaging** — creating a snapshot of a fully configured operating system (including installed software, drivers, and settings) and deploying that snapshot to other machines. This is how organizations rapidly set up dozens or hundreds of identical workstations without manually installing and configuring each one.\n\nThe workflow typically involves: configure one \"golden image\" machine exactly how you want it, capture that machine's disk as an image file, then deploy that image to other hardware via network (PXE boot), USB, or imaging software. Tools like Microsoft SCCM/Intune, Ghost, Clonezilla, and Windows Deployment Services ([[WDS]]) are commonly used.\n\nA disk image captures everything — the OS, applications, settings, and user profiles — as a single file (often an [[ISO]] or proprietary format). This is different from a backup: a backup preserves data; an image preserves the entire system state.\n\n## Key Concepts\n\n- **Golden Image / Master Image:** A reference machine that's been fully configured, then captured. All other deployments are copies of this image.\n- **Disk Image:** A sector-by-sector copy of a disk saved as a file — can be restored to any compatible machine.\n- **[[PXE Boot]]:** Allows computers to boot from the network and receive an OS image without needing local media — essential for large-scale deployments.\n- **[[WDS]] (Windows Deployment Services):** Microsoft's server role for deploying Windows images over a network.\n- **[[WINPE]] (Windows Preinstallation Environment):** A minimal Windows boot environment used during imaging — allows access to imaging tools before the full OS loads.\n- **Sysprep:** A Microsoft tool that generalizes a Windows image before capture, removing machine-specific identifiers (like the SID) so the image can be deployed to multiple unique machines.\n- **Thin vs. Thick Image:** A thick image includes the OS plus all applications; a thin image is just the OS, with applications installed separately post-deployment.\n\n## Why It Matters\nImaging is a core sysadmin skill. In any organization with more than a handful of computers, manual OS installation is impractical — imaging makes standardized, repeatable deployment possible. Understanding how to capture, store, and deploy images, and how tools like WDS and PXE boot work, is tested on CompTIA A+ and is a practical requirement for IT support and system administration roles.\n\n## Related Topics\n- [[ISO]]\n- [[WDS]]\n- [[WINPE]]\n- [[PXE Boot]]\n- [[Operating System]]\n- [[Software Deployment]]"},{"id":"Terms and Concepts/Input Device","title":"Input Device","section":"Terms and Concepts","domain":"Hardware","description":"Hardware that allows a user to send data or commands into a computer system.","tags":["IT","IT/Hardware","Level/Foundational"],"content":"# Input Device\n\n> Hardware that allows a user to send data or commands into a computer system.\n\n## Overview\nInput devices are the means by which humans interact with computers. They convert physical actions — keystrokes, mouse movements, touch, voice, or visual input — into digital signals that the computer can process. Every interaction a user has with a computer starts with an input device.\n\nThe most fundamental input devices are the keyboard and mouse, but modern computing uses a wide range of input technologies: touchscreens on phones and tablets, cameras and microphones for media and communication, scanners for digitizing documents, and specialized devices like graphics tablets or game controllers for specific use cases.\n\nInput devices pair with [[Output Device|output devices]] — the screen, speakers, and printers — to form the full loop of human-computer interaction.\n\n## Key Concepts\n\n- **Keyboard:** The primary text input device. Uses keys mapped to characters, commands, and shortcuts.\n- **Mouse:** Pointing device for controlling the on-screen cursor. Uses optical or laser sensors to track movement.\n- **Touchscreen:** Combines input and output — users interact directly with the display via touch gestures.\n- **Trackpad:** Touch-sensitive pad on laptops serving as a substitute for a mouse.\n- **Microphone:** Captures audio input — used for voice commands, VoIP, and recording.\n- **Webcam:** Captures video input — used for video conferencing, streaming, and facial recognition.\n- **Scanner:** Converts physical documents or images into digital format.\n- **Digital Pen / Stylus:** Allows handwriting or drawing input on touch-sensitive surfaces.\n- **Biometric Readers:** Fingerprint sensors, facial recognition cameras, and iris scanners used for authentication.\n\n## Why It Matters\nUnderstanding input devices is foundational IT knowledge covered on CompTIA A+. When supporting users, you'll troubleshoot keyboards, mice, touchscreens, and webcams regularly. Knowing how these devices connect (USB, Bluetooth, PS/2) and how to diagnose basic input failures is a day-one help desk skill.\n\n## Related Topics\n- [[Output Device]]\n- [[Computer]]\n- [[USB]]\n- [[Bluetooth]]\n- [[Authentication]]"},{"id":"Terms and Concepts/Insider Trheat","title":"Insider Trheat","section":"Terms and Concepts","domain":"Security","description":"A security risk that originates from within an organization — employees, contractors, or other trusted individuals who misuse their authorized access to cause harm.","tags":["IT","IT/Security","Level/Intermediate"],"content":"# Insider Threat\n\n> A security risk that originates from within an organization — employees, contractors, or other trusted individuals who misuse their authorized access to cause harm.\n\n## Overview\nAn insider threat is distinct from external attacks because the threat actor already has legitimate access to systems and data. This makes insider threats particularly difficult to detect — the activity can look like normal user behavior. Insider threats can be intentional (a disgruntled employee stealing data) or unintentional (a well-meaning employee falling for a phishing attack or misconfiguring a system).\n\nOrganizations must balance trust with oversight. Because insiders already have credentials and familiarity with internal systems, they can potentially cause more damage with less effort than an external attacker trying to break in. High-profile insider incidents have resulted in massive data breaches, intellectual property theft, and sabotage.\n\nThe three main categories of insider threat are **malicious insiders** (intentional harm), **negligent insiders** (accidental harm), and **compromised insiders** (accounts hijacked by external attackers).\n\n## Key Concepts\n\n- **Malicious Insider:** An employee or contractor who deliberately abuses their access — often motivated by financial gain, grievance, or coercion.\n- **Negligent Insider:** An unintentional threat — a user who clicks a phishing link, mishandles data, or disables security controls out of carelessness.\n- **Compromised Insider:** A legitimate user whose account or credentials have been taken over by an external attacker.\n- **[[Principle of least Privilege]]:** Limiting user access to only what's needed for their role — reduces the damage any one insider can do.\n- **Behavioral Monitoring:** Watching for unusual access patterns, large data transfers, or after-hours activity that may signal an insider threat.\n- **Data Loss Prevention (DLP):** Tools that monitor and restrict the movement of sensitive data, flagging or blocking suspicious transfers.\n- **Offboarding Controls:** Promptly revoking access when employees leave — a critical step that organizations often neglect.\n\n## Why It Matters\nInsider threats are one of the hardest security problems to solve because they involve people who are supposed to have access. Security programs must combine technical controls (access restrictions, monitoring, DLP) with organizational practices (training, clear policies, prompt offboarding). This topic appears on CompTIA Security+ and is a core concern for any IT security role.\n\n## Related Topics\n- [[Social Engineering]]\n- [[Principle of least Privilege]]\n- [[Identity Mangement]]\n- [[Access Control]]\n- [[Logging]]\n- [[Security Assessments]]"},{"id":"Terms and Concepts/Integrity","title":"Integrity","section":"Terms and Concepts","domain":"Security","description":"The security principle that data must remain accurate, complete, and unaltered — any unauthorized modification should be detected.","tags":["IT","IT/Security","Level/Foundational"],"content":"# Integrity\n\n> The security principle that data must remain accurate, complete, and unaltered — any unauthorized modification should be detected.\n\n## Overview\nIntegrity is the \"I\" in the [[CIA Triad]] — the three foundational principles of information security (Confidentiality, Integrity, Availability). While confidentiality is about keeping data secret and availability is about keeping it accessible, integrity is about keeping data **accurate and trustworthy**. Data has integrity when it hasn't been tampered with, corrupted, or modified in unauthorized ways.\n\nIntegrity applies at multiple levels: a single file's contents shouldn't change unexpectedly, database records should accurately reflect real transactions, and software shouldn't be modified after it leaves the developer. Maintaining integrity means ensuring that data is exactly what it's supposed to be — from the moment it's created to the moment it's used.\n\nThe primary technical mechanism for verifying integrity is **hashing** — a cryptographic function that produces a fixed-length fingerprint of data. If even one bit changes, the hash changes entirely. Organizations use hashes to verify file downloads, sign code, and detect tampering.\n\n## Key Concepts\n\n- **[[CIA Triad]]:** Integrity is one of the three core security principles alongside [[Confidentiality]] and [[Availability]].\n- **Hashing:** Produces a unique fixed-size digest of data (e.g., SHA-256). Used to verify that data hasn't changed.\n- **Digital Signatures:** Combine hashing with asymmetric encryption to verify both integrity and authenticity of a message or file.\n- **Checksums:** Simpler hash-like values used to detect accidental corruption (e.g., during file transmission).\n- **Access Controls:** Preventing unauthorized users from modifying data is the first line of defense for integrity.\n- **Audit Trails / [[Logging]]:** Recording changes to data so that unauthorized modifications can be detected and traced.\n- **Data Validation:** Ensuring inputs meet expected formats and rules before being accepted by a system.\n\n## Why It Matters\nIntegrity is tested on virtually every IT security certification, especially CompTIA Security+. In practice, maintaining data integrity protects against both malicious tampering and accidental corruption. Whether verifying software downloads, protecting database records, or ensuring log files haven't been altered during an incident, integrity controls are everywhere in security work.\n\n## Related Topics\n- [[CIA Triad]]\n- [[Confidentiality]]\n- [[Availability]]\n- [[SHA]]\n- [[Encryption]]\n- [[Logging]]"},{"id":"Terms and Concepts/Internet Protocol (IP)","title":"Internet Protocol (IP)","section":"Terms and Concepts","domain":"Networking","description":"The foundational network protocol that provides addressing and routing for packets across interconnected networks, forming the basis of the internet.","tags":["IT","IT/Networking","Level/Foundational"],"content":"# Internet Protocol (IP)\n\n> The foundational network protocol that provides addressing and routing for packets across interconnected networks, forming the basis of the internet.\n\n## Overview\nThe Internet Protocol (IP) is the core protocol of the internet. It defines how packets of data are addressed, structured, and routed from one device to another across multiple interconnected networks. Every device on the internet uses IP, and every data transmission — web pages, emails, video streams — is broken into IP packets and reassembled at the destination.\n\nIP is a **connectionless, best-effort protocol**: it doesn't establish a dedicated connection before sending data and doesn't guarantee delivery or ordering. Those concerns are handled by higher-layer protocols like [[TCP]] (which adds reliability on top of IP). Together, TCP and IP form the [[TCP IP Model|TCP/IP stack]] — the foundational protocol suite of the internet.\n\nThere are two versions in active use: [[IPV4]] (32-bit addresses, e.g., `192.168.1.1`) and [[IPV6]] (128-bit addresses, e.g., `2001:db8::1`). IPv6 was developed to address the IPv4 address exhaustion problem.\n\n## Key Concepts\n\n- **[[IP Address]]:** Unique numerical identifier for each device on a network. IP addresses are the \"postal addresses\" that tell packets where to go.\n- **[[IPV4]] vs. [[IPV6]]:** IPv4 uses 32-bit addresses; IPv6 uses 128-bit. IPv6 solves address exhaustion and adds built-in features like SLAAC.\n- **Packet:** The basic unit of data transmission. IP breaks data into packets, routes them independently, and they're reassembled at the destination.\n- **IP Header:** Contains source address, destination address, TTL, and protocol information. Routers read this to make forwarding decisions.\n- **TTL (Time to Live):** A counter in each packet that decrements at each hop. When it reaches zero, the packet is discarded — prevents infinite routing loops.\n- **[[IP Routing]]:** Routers use [[Routing Tables]] to determine where to forward each packet based on its destination IP.\n- **Best-Effort Delivery:** IP doesn't guarantee packets arrive, arrive in order, or arrive without errors. [[TCP]] provides those guarantees on top of IP.\n\n## Why It Matters\nIP is literally what makes the internet possible. Understanding how addressing, routing, and packet structure work is foundational knowledge for every networking, systems, or cloud role. The TCP/IP model and IP addressing are tested on CompTIA A+, Network+, and Security+, and are referenced in virtually every area of IT work.\n\n## Related Topics\n- [[IP Address]]\n- [[IPV4]]\n- [[IPV6]]\n- [[TCP]]\n- [[TCP IP Model]]\n- [[IP Routing]]\n- [[Router]]"},{"id":"Terms and Concepts/IoT","title":"IoT","section":"Terms and Concepts","domain":"Networking","description":"The network of physical devices — sensors, appliances, vehicles, and other objects — that are embedded with connectivity and software to collect and exchange data over the internet.","tags":["IT","IT/Fundamentals","IT/Networking","Level/Intermediate"],"content":"# Internet of Things (IoT)\n\n> The network of physical devices — sensors, appliances, vehicles, and other objects — that are embedded with connectivity and software to collect and exchange data over the internet.\n\n## Overview\nThe Internet of Things (IoT) refers to the billions of devices beyond traditional computers and phones that are now connected to the internet. A smart thermostat, an industrial sensor on a factory floor, a connected medical monitor, or a GPS tracker in a delivery truck — these are all IoT devices. They collect data from the physical world, transmit it over networks, and often receive instructions in return.\n\nIoT devices typically have limited processing power and are purpose-built for specific tasks. They connect via Wi-Fi, Bluetooth, Zigbee, cellular (LTE/5G), or specialized low-power protocols like LoRaWAN. Collected data is often sent to cloud platforms for storage and analysis, enabling automation, monitoring, and decision-making at scale.\n\nThe massive growth of IoT has created significant security challenges. Many IoT devices ship with weak default credentials, infrequent security updates, and minimal security hardening — making them attractive targets for attackers. Compromised IoT devices have been used in large-scale DDoS attacks (e.g., the Mirai botnet).\n\n## Key Concepts\n\n- **Sensors and Actuators:** IoT devices read physical data (temperature, motion, pressure) via sensors and can trigger physical actions via actuators (turning on a motor, unlocking a door).\n- **Connectivity Protocols:** Wi-Fi, Bluetooth, Zigbee, Z-Wave, LoRaWAN, NB-IoT, cellular — different use cases favor different protocols based on range, power, and bandwidth needs.\n- **Edge Computing:** Processing data locally on or near the IoT device instead of sending everything to the cloud — reduces latency and bandwidth.\n- **[[Cloud Computing]]:** Central platform for aggregating IoT data, running analytics, and managing device fleets at scale.\n- **IoT Security Risks:** Weak passwords, lack of update mechanisms, large attack surface, and network exposure make IoT a major security concern.\n- **Firmware Updates:** Critical for patching vulnerabilities — but many IoT devices never receive updates after deployment.\n\n## Why It Matters\nIoT is expanding rapidly across industries — healthcare, manufacturing, smart buildings, transportation, and consumer electronics. For IT professionals, IoT introduces network management challenges (device inventory, segmentation), security responsibilities (hardening, monitoring), and new infrastructure demands. IoT security is increasingly covered on CompTIA Security+ and is a real-world concern in enterprise environments.\n\n## Related Topics\n- [[Network]]\n- [[Cloud Computing]]\n- [[Wi-Fi]]\n- [[Bluetooth]]\n- [[Cloud Security]]\n- [[Shadow IT]]"},{"id":"Terms and Concepts/IP Address","title":"IP Address","section":"Terms and Concepts","domain":"Networking","description":"A unique numerical label assigned to every device on a network, used to identify it and route data to and from it.","tags":["IT","IT/Networking","Level/Foundational"],"content":"# IP Address\n\n> A unique numerical label assigned to every device on a network, used to identify it and route data to and from it.\n\n## Overview\nAn IP (Internet Protocol) address is essentially a device's mailing address on a network. Every computer, phone, printer, or server that communicates over a network needs one. When you visit a website, your device sends packets to the site's IP address and receives packets back at yours.\n\nThere are two versions in use today. **[[IPV4]]** uses 32-bit addresses written as four decimal numbers separated by dots (e.g., `192.168.1.1`) — there are about 4.3 billion possible addresses, which proved insufficient as the internet grew. **[[IPV6]]** uses 128-bit addresses in hexadecimal (e.g., `2001:0db8:85a3::8a2e:0370:7334`), providing a vastly larger address space to accommodate modern devices.\n\nIP addresses have two logical parts: the **network portion** (identifying which network the device is on) and the **host portion** (identifying the specific device within that network). The [[Subnet Mask]] determines where one ends and the other begins.\n\n## Key Concepts\n\n- **[[IPV4]]:** 32-bit, dotted-decimal notation (e.g., `10.0.0.1`). Still dominant on most networks.\n- **[[IPV6]]:** 128-bit, hexadecimal with colons. Designed to replace IPv4 long-term.\n- **Public IP Address:** Routable on the internet; assigned by an ISP. See [[Public IP Address]].\n- **Private IP Address:** Used within local networks (e.g., `192.168.x.x`, `10.x.x.x`). Not routable on the internet. See [[Private IP Address]].\n- **Static vs. Dynamic:** A static IP is manually assigned and doesn't change. A dynamic IP is assigned automatically via [[DHCP]] and may change.\n- **[[Subnet Mask]]:** Defines which part of the address is the network vs. host portion.\n- **IPv4 Classes (historical):** Class A (1–126), Class B (128–191), Class C (192–223), Class D (multicast), Class E (experimental). Largely replaced by CIDR notation.\n\n## Why It Matters\nIP addressing is one of the most fundamental concepts in networking. You'll encounter it constantly — configuring devices, troubleshooting connectivity, setting up servers, and reading network documentation. Understanding static vs. dynamic addressing, public vs. private ranges, and the basics of IPv4 vs. IPv6 is required knowledge for CompTIA A+, Network+, and virtually any IT certification.\n\n## Related Topics\n- [[IPV4]]\n- [[IPV6]]\n- [[Subnet Mask]]\n- [[DHCP]]\n- [[Public IP Address]]\n- [[Private IP Address]]\n- [[NAT]]"}]$field_desk$::jsonb) as note(
    id text,
    title text,
    section text,
    domain text,
    description text,
    tags jsonb,
    content text
  )
)
insert into public.knowledge_articles (
  slug, title, course_id, category, status, author_id, body, tags,
  source_type, source_id, created_at, updated_at, published_at
)
select
  'field-desk-' || md5(note.id),
  note.title,
  case note.domain
    when 'Networking' then 'net'
    when 'Hardware' then 'hw'
    when 'Security' then 'cyber'
    else null
  end,
  coalesce(nullif(note.section, ''), 'General'),
  'published',
  '6e37eaa9-f4f9-4fb0-8ba9-45e8fd55db52'::uuid,
  case when coalesce(note.description, '') <> ''
    then '> ' || note.description || E'\n\n' || coalesce(note.content, '')
    else coalesce(note.content, '')
  end,
  array(
    select distinct tag
    from (
      select jsonb_array_elements_text(coalesce(note.tags, '[]'::jsonb)) as tag
      union all select note.domain
      union all select note.section
    ) labels
    where coalesce(tag, '') <> ''
  ),
  'field_desk',
  note.id,
  now(),
  now(),
  now()
from source_notes note
where not exists (
  select 1 from public.knowledge_articles existing
  where existing.source_type = 'field_desk' and existing.source_id = note.id
);

insert into public.knowledge_article_revisions (
  article_id, editor_id, title, body, tags, status, change_summary, created_at
)
select article.id, article.author_id, article.title, article.body, article.tags,
  article.status, 'Imported from Ember IT Field Desk', article.updated_at
from public.knowledge_articles article
where article.source_type = 'field_desk'
  and not exists (
    select 1 from public.knowledge_article_revisions revision
    where revision.article_id = article.id
  );
